-- izohlar bilan). scripts/learning/build-bank-migration.ts yaratgan —
-- qo'lda tahrirlamang. Mavjud (externalId) savollar o'zgartirilmaydi.

INSERT INTO "learning_questions" ("id", "external_id", "subject", "difficulty",
  "min_grade", "max_grade", "topic", "prompt", "options", "answer_index",
  "explanation", "status", "created_at", "updated_at")
VALUES
('165b95e9-8520-546f-9af1-a3af0ad352b2', 'biology-01', 'BIOLOGY', 1, 5, 9, '{"uz":"Hujayra","ru":"Клетка","en":"Cells"}'::jsonb, '{"uz":"Barcha tirik organizmlarning eng kichik tuzilish va hayotiy birligi nima?","ru":"Что является наименьшей структурной и функциональной единицей всех живых организмов?","en":"What is the smallest structural and functional unit of all living things?"}'::jsonb, '[{"uz":"To‘qima","ru":"Ткань","en":"Tissue"},{"uz":"Organ","ru":"Орган","en":"Organ"},{"uz":"Hujayra","ru":"Клетка","en":"Cell"},{"uz":"Organlar tizimi","ru":"Система органов","en":"Organ system"}]'::jsonb, 2, '{"uz":"Barcha tirik organizmlar hujayralardan tuzilgan. Bakteriya bitta hujayradan, odam tanasi esa trillionlab hujayradan iborat.","ru":"Все живые организмы состоят из клеток. Бактерия — это одна клетка, а тело человека состоит из триллионов клеток.","en":"All living things are made of cells. A bacterium is a single cell, while the human body has trillions of them."}'::jsonb, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
('b9a18640-faea-5c67-8f15-96177023222d', 'biology-02', 'BIOLOGY', 1, 5, 9, '{"uz":"Fotosintez","ru":"Фотосинтез","en":"Photosynthesis"}'::jsonb, '{"uz":"Fotosintez jarayonida o‘simliklar havodan qaysi gazni yutadi?","ru":"Какой газ растения поглощают из воздуха во время фотосинтеза?","en":"Which gas do plants take in from the air during photosynthesis?"}'::jsonb, '[{"uz":"Karbonat angidrid (CO₂)","ru":"Углекислый газ (CO₂)","en":"Carbon dioxide (CO₂)"},{"uz":"Kislorod (O₂)","ru":"Кислород (O₂)","en":"Oxygen (O₂)"},{"uz":"Azot (N₂)","ru":"Азот (N₂)","en":"Nitrogen (N₂)"},{"uz":"Vodorod (H₂)","ru":"Водород (H₂)","en":"Hydrogen (H₂)"}]'::jsonb, 0, '{"uz":"Quyosh nuri yordamida o‘simliklar karbonat angidrid va suvdan organik modda (glyukoza) hosil qiladi va havoga kislorod chiqaradi.","ru":"С помощью солнечного света растения превращают углекислый газ и воду в органическое вещество (глюкозу) и выделяют кислород.","en":"Using sunlight, plants turn carbon dioxide and water into sugar (glucose) and release oxygen into the air."}'::jsonb, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
('7d50fa59-ed1b-5994-8c7f-1b2c823ff1c9', 'biology-03', 'BIOLOGY', 1, 5, 9, '{"uz":"Odam organlari","ru":"Органы человека","en":"Human organs"}'::jsonb, '{"uz":"Odam yuragi nechta kameradan iborat?","ru":"Сколько камер в сердце человека?","en":"How many chambers does the human heart have?"}'::jsonb, '[{"uz":"Bitta","ru":"Одна","en":"One"},{"uz":"Ikkita","ru":"Две","en":"Two"},{"uz":"Uchta","ru":"Три","en":"Three"},{"uz":"To‘rtta","ru":"Четыре","en":"Four"}]'::jsonb, 3, '{"uz":"Odam yuragi ikkita bo‘lmacha va ikkita qorinchadan, ya’ni to‘rtta kameradan iborat. U qonni butun tanaga haydab beradi.","ru":"Сердце человека состоит из двух предсердий и двух желудочков — всего четырёх камер. Оно перекачивает кровь по всему телу.","en":"The human heart has two atria and two ventricles, four chambers in total. It pumps blood around the whole body."}'::jsonb, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
('8b448038-88b1-5ce8-bc1e-1ac163d43ba8', 'biology-04', 'BIOLOGY', 1, 5, 9, '{"uz":"Hayvonlar olami","ru":"Мир животных","en":"Animal kingdom"}'::jsonb, '{"uz":"Quyidagi dengiz hayvonlaridan qaysi biri sutemizuvchi?","ru":"Какое из этих морских животных — млекопитающее?","en":"Which of these sea animals is a mammal?"}'::jsonb, '[{"uz":"Akula","ru":"Акула","en":"Shark"},{"uz":"Kit","ru":"Кит","en":"Whale"},{"uz":"Sakkizoyoq","ru":"Осьминог","en":"Octopus"},{"uz":"Meduza","ru":"Медуза","en":"Jellyfish"}]'::jsonb, 1, '{"uz":"Kit o‘pka bilan nafas oladi va bolasini sut bilan boqadi, shuning uchun u baliq emas, sutemizuvchi hisoblanadi.","ru":"Кит дышит лёгкими и выкармливает детёныша молоком, поэтому он не рыба, а млекопитающее.","en":"A whale breathes with lungs and feeds its calf with milk, so it is a mammal, not a fish."}'::jsonb, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
('e334cf57-0c07-5a9c-9fb2-53308a65279d', 'biology-05', 'BIOLOGY', 1, 5, 9, '{"uz":"Hasharotlar","ru":"Насекомые","en":"Insects"}'::jsonb, '{"uz":"Hasharotlarning nechta oyog‘i bor?","ru":"Сколько ног у насекомых?","en":"How many legs do insects have?"}'::jsonb, '[{"uz":"To‘rtta","ru":"Четыре","en":"Four"},{"uz":"Oltita","ru":"Шесть","en":"Six"},{"uz":"Sakkizta","ru":"Восемь","en":"Eight"},{"uz":"O‘nta","ru":"Десять","en":"Ten"}]'::jsonb, 1, '{"uz":"Hasharotlarning uch juft, ya’ni oltita oyog‘i bor. O‘rgimchakning esa sakkizta oyog‘i bo‘ladi, shuning uchun u hasharot emas.","ru":"У насекомых три пары ног, то есть шесть. У паука восемь ног, поэтому он не насекомое.","en":"Insects have three pairs of legs, six in total. Spiders have eight legs, so they are not insects."}'::jsonb, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
('7d9c1134-cfa3-5bb5-ad34-ca456c3f7198', 'biology-06', 'BIOLOGY', 2, 5, 9, '{"uz":"O‘simliklar","ru":"Растения","en":"Plants"}'::jsonb, '{"uz":"O‘simlik barglariga yashil rang beradigan modda qanday ataladi?","ru":"Как называется вещество, которое придаёт листьям растений зелёный цвет?","en":"What is the substance that gives plant leaves their green colour called?"}'::jsonb, '[{"uz":"Gemoglobin","ru":"Гемоглобин","en":"Haemoglobin"},{"uz":"Melanin","ru":"Меланин","en":"Melanin"},{"uz":"Xlorofill","ru":"Хлорофилл","en":"Chlorophyll"},{"uz":"Insulin","ru":"Инсулин","en":"Insulin"}]'::jsonb, 2, '{"uz":"Xlorofill xloroplastlarda joylashgan bo‘lib, quyosh nurini tutib oladi. Bu energiya o‘simlikka fotosintez uchun kerak.","ru":"Хлорофилл находится в хлоропластах и улавливает солнечный свет. Эта энергия нужна растению для фотосинтеза.","en":"Chlorophyll is found in chloroplasts and captures sunlight. The plant uses this energy for photosynthesis."}'::jsonb, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
('1fc215cf-603c-5607-b325-d81463fe5197', 'biology-07', 'BIOLOGY', 2, 5, 9, '{"uz":"Ayirish tizimi","ru":"Выделительная система","en":"Excretory system"}'::jsonb, '{"uz":"Qonni filtrlab, ortiqcha suv va zararli moddalarni siydik holida chiqaradigan organ qaysi?","ru":"Какой орган фильтрует кровь и выводит лишнюю воду и вредные вещества с мочой?","en":"Which organ filters the blood and removes extra water and waste as urine?"}'::jsonb, '[{"uz":"Yurak","ru":"Сердце","en":"Heart"},{"uz":"O‘pka","ru":"Лёгкие","en":"Lungs"},{"uz":"Buyrak","ru":"Почки","en":"Kidneys"},{"uz":"Oshqozon","ru":"Желудок","en":"Stomach"}]'::jsonb, 2, '{"uz":"Buyraklar har kuni ko‘p miqdordagi qonni filtrlab, undagi keraksiz moddalarni siydik orqali chiqarib tashlaydi.","ru":"Почки каждый день фильтруют большое количество крови и выводят ненужные вещества с мочой.","en":"Every day the kidneys filter a large amount of blood and get rid of unneeded substances in urine."}'::jsonb, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
('c75205c5-e732-5762-8d20-4cf80d37251f', 'biology-08', 'BIOLOGY', 2, 5, 9, '{"uz":"Ekologiya","ru":"Экология","en":"Ecology"}'::jsonb, '{"uz":"Oziq zanjirida yashil o‘simliklar qaysi guruhga kiradi?","ru":"К какой группе относятся зелёные растения в пищевой цепи?","en":"Which group do green plants belong to in a food chain?"}'::jsonb, '[{"uz":"Produtsentlar","ru":"Продуценты","en":"Producers"},{"uz":"Konsumentlar","ru":"Консументы","en":"Consumers"},{"uz":"Redutsentlar","ru":"Редуценты","en":"Decomposers"},{"uz":"Parazitlar","ru":"Паразиты","en":"Parasites"}]'::jsonb, 0, '{"uz":"O‘simliklar quyosh energiyasi yordamida organik modda hosil qiladi, shuning uchun ular produtsentlardir. Ularni yeydigan hayvonlar konsumentlar deyiladi.","ru":"Растения сами создают органические вещества за счёт энергии Солнца, поэтому они продуценты. Животные, которые их едят, — консументы.","en":"Plants make their own food using energy from the Sun, so they are producers. Animals that eat them are called consumers."}'::jsonb, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
('89d19a29-b8e8-5901-a89d-b9dd61b22842', 'biology-09', 'BIOLOGY', 2, 5, 9, '{"uz":"Mikroorganizmlar","ru":"Микроорганизмы","en":"Microorganisms"}'::jsonb, '{"uz":"Mashhur antibiotik — penitsillinni kim kashf etgan?","ru":"Кто открыл знаменитый антибиотик пенициллин?","en":"Who discovered the famous antibiotic penicillin?"}'::jsonb, '[{"uz":"Lui Paster","ru":"Луи Пастер","en":"Louis Pasteur"},{"uz":"Charlz Darvin","ru":"Чарльз Дарвин","en":"Charles Darwin"},{"uz":"Isaak Nyuton","ru":"Исаак Ньютон","en":"Isaac Newton"},{"uz":"Aleksandr Fleming","ru":"Александр Флеминг","en":"Alexander Fleming"}]'::jsonb, 3, '{"uz":"1928-yilda Aleksandr Fleming mog‘or zamburug‘i bakteriyalarni o‘ldirishini payqagan. Keyinchalik penitsillin millionlab odamlarning hayotini saqlab qolgan.","ru":"В 1928 году Александр Флеминг заметил, что плесневый грибок убивает бактерии. Позже пенициллин спас миллионы жизней.","en":"In 1928 Alexander Fleming noticed that a mould was killing bacteria. Penicillin later saved millions of lives."}'::jsonb, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
('4ed75cc8-2409-5a8c-a149-3aa56e02557c', 'biology-10', 'BIOLOGY', 2, 5, 9, '{"uz":"Skelet","ru":"Скелет","en":"Skeleton"}'::jsonb, '{"uz":"Katta yoshli odam skeletida taxminan nechta suyak bor?","ru":"Сколько примерно костей в скелете взрослого человека?","en":"About how many bones are there in an adult human skeleton?"}'::jsonb, '[{"uz":"106","ru":"106","en":"106"},{"uz":"206","ru":"206","en":"206"},{"uz":"306","ru":"306","en":"306"},{"uz":"406","ru":"406","en":"406"}]'::jsonb, 1, '{"uz":"Katta yoshli odamda 206 ga yaqin suyak bor. Chaqaloqda suyaklar ko‘proq bo‘ladi, o‘sish davomida ularning bir qismi o‘zaro birikib ketadi.","ru":"У взрослого человека около 206 костей. У младенца их больше: по мере роста часть костей срастается.","en":"An adult has about 206 bones. Babies have more, but some of them fuse together as the body grows."}'::jsonb, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
('b9bf995e-5919-5021-bb78-85b0b3086b79', 'biology-11', 'BIOLOGY', 3, 5, 9, '{"uz":"Genetika asoslari","ru":"Основы генетики","en":"Genetics basics"}'::jsonb, '{"uz":"Irsiy belgilarni ota-onadan farzandlarga o‘tkazuvchi molekula qanday ataladi?","ru":"Как называется молекула, которая передаёт наследственные признаки от родителей потомкам?","en":"What is the molecule that passes hereditary traits from parents to offspring called?"}'::jsonb, '[{"uz":"DNK","ru":"ДНК","en":"DNA"},{"uz":"Kraxmal","ru":"Крахмал","en":"Starch"},{"uz":"Glyukoza","ru":"Глюкоза","en":"Glucose"},{"uz":"Yog‘","ru":"Жир","en":"Fat"}]'::jsonb, 0, '{"uz":"DNK asosan hujayra yadrosidagi xromosomalarda joylashgan. Uning genlar deb ataluvchi qismlari ko‘z rangi kabi belgilarni belgilaydi.","ru":"ДНК находится в основном в хромосомах клеточного ядра. Её участки — гены — определяют такие признаки, как цвет глаз.","en":"DNA is found mainly in the chromosomes of the cell nucleus. Its sections, called genes, determine traits such as eye colour."}'::jsonb, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
('d502147d-cdc9-5945-afdc-683d4c782d2e', 'biology-12', 'BIOLOGY', 3, 5, 9, '{"uz":"Irsiyat qonunlari","ru":"Законы наследственности","en":"Laws of heredity"}'::jsonb, '{"uz":"No‘xat o‘simligi ustida tajribalar o‘tkazib, irsiyat qonunlarini kashf etgan olim kim?","ru":"Какой учёный открыл законы наследственности, проводя опыты с горохом?","en":"Which scientist discovered the laws of heredity by experimenting with pea plants?"}'::jsonb, '[{"uz":"Robert Guk","ru":"Роберт Гук","en":"Robert Hooke"},{"uz":"Lui Paster","ru":"Луи Пастер","en":"Louis Pasteur"},{"uz":"Charlz Darvin","ru":"Чарльз Дарвин","en":"Charles Darwin"},{"uz":"Gregor Mendel","ru":"Грегор Мендель","en":"Gregor Mendel"}]'::jsonb, 3, '{"uz":"XIX asrda Gregor Mendel no‘xatning turli navlarini chatishtirib, belgilar nasldan naslga qanday o‘tishini aniqlagan. Shu sababli uni genetika asoschisi deyishadi.","ru":"В XIX веке Грегор Мендель скрещивал разные сорта гороха и выяснил, как передаются признаки. Поэтому его называют основателем генетики.","en":"In the 19th century Gregor Mendel crossed different varieties of peas and found out how traits are inherited. That is why he is called the father of genetics."}'::jsonb, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
('f987358c-dabc-5578-8f52-662d2c43ca3c', 'biology-13', 'BIOLOGY', 3, 5, 9, '{"uz":"Biologiya tarixi","ru":"История биологии","en":"History of biology"}'::jsonb, '{"uz":"«Hujayra» atamasini fanga birinchi bo‘lib kiritgan olim kim?","ru":"Какой учёный первым ввёл в науку термин «клетка»?","en":"Which scientist first introduced the term “cell” into science?"}'::jsonb, '[{"uz":"Gregor Mendel","ru":"Грегор Мендель","en":"Gregor Mendel"},{"uz":"Robert Guk","ru":"Роберт Гук","en":"Robert Hooke"},{"uz":"Aleksandr Fleming","ru":"Александр Флеминг","en":"Alexander Fleming"},{"uz":"Charlz Darvin","ru":"Чарльз Дарвин","en":"Charles Darwin"}]'::jsonb, 1, '{"uz":"1665-yilda Robert Guk mikroskopda po‘kakning yupqa kesmasini ko‘rib, undagi mayda katakchalarni «hujayralar» deb atagan.","ru":"В 1665 году Роберт Гук рассмотрел под микроскопом тонкий срез пробки и назвал увиденные в нём ячейки «клетками».","en":"In 1665 Robert Hooke looked at a thin slice of cork under a microscope and called the tiny compartments he saw “cells”."}'::jsonb, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
('a4e8b329-ecb5-57ad-be76-93c4b83d5116', 'biology-14', 'BIOLOGY', 3, 5, 9, '{"uz":"Barg tuzilishi","ru":"Строение листа","en":"Leaf structure"}'::jsonb, '{"uz":"Barg yuzasidagi gaz almashinuvi va suv bug‘lanishi sodir bo‘ladigan mayda teshikchalar nima deb ataladi?","ru":"Как называются крошечные отверстия на поверхности листа, через которые идут газообмен и испарение воды?","en":"What are the tiny pores on a leaf''s surface that allow gas exchange and water evaporation called?"}'::jsonb, '[{"uz":"Ildiz tukchalari","ru":"Корневые волоски","en":"Root hairs"},{"uz":"Gulbarglar","ru":"Лепестки","en":"Petals"},{"uz":"Og‘izchalar (ustitsalar)","ru":"Устьица","en":"Stomata"},{"uz":"Barg tomirlari","ru":"Жилки листа","en":"Leaf veins"}]'::jsonb, 2, '{"uz":"Og‘izchalar orqali barg karbonat angidridni yutadi, kislorod chiqaradi va suvni bug‘latadi. Suvning bug‘lanishi transpiratsiya deyiladi.","ru":"Через устьица лист поглощает углекислый газ, выделяет кислород и испаряет воду. Испарение воды растением называется транспирацией.","en":"Through stomata a leaf takes in carbon dioxide, releases oxygen and evaporates water. This evaporation of water is called transpiration."}'::jsonb, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
('0d284e7d-404d-5ef1-97f2-c5832dbd5b56', 'biology-15', 'BIOLOGY', 3, 5, 9, '{"uz":"Qon tarkibi","ru":"Состав крови","en":"Blood"}'::jsonb, '{"uz":"Qonning qaysi hujayralari o‘pkadan barcha a’zolarga kislorod tashiydi?","ru":"Какие клетки крови переносят кислород от лёгких ко всем органам?","en":"Which blood cells carry oxygen from the lungs to all organs?"}'::jsonb, '[{"uz":"Eritrotsitlar","ru":"Эритроциты","en":"Red blood cells"},{"uz":"Leykotsitlar","ru":"Лейкоциты","en":"White blood cells"},{"uz":"Trombotsitlar","ru":"Тромбоциты","en":"Platelets"},{"uz":"Neyronlar","ru":"Нейроны","en":"Neurons"}]'::jsonb, 0, '{"uz":"Eritrotsitlar tarkibidagi gemoglobin o‘pkada kislorodni biriktirib oladi. Leykotsitlar mikroblardan himoya qiladi, trombotsitlar esa qon ivishiga yordam beradi.","ru":"Гемоглобин в эритроцитах связывает кислород в лёгких. Лейкоциты защищают от микробов, а тромбоциты помогают крови свёртываться.","en":"Haemoglobin inside red blood cells picks up oxygen in the lungs. White blood cells fight germs, and platelets help blood to clot."}'::jsonb, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
('39f4de80-9a76-5d2c-9808-6fdb466f80f1', 'chemistry-01', 'CHEMISTRY', 1, 5, 9, '{"uz":"Kimyoviy belgilar","ru":"Химические знаки","en":"Element symbols"}'::jsonb, '{"uz":"Kislorodning kimyoviy belgisi qanday?","ru":"Какой химический знак у кислорода?","en":"What is the chemical symbol for oxygen?"}'::jsonb, '[{"uz":"Ok","ru":"Ok","en":"Ok"},{"uz":"Os","ru":"Os","en":"Os"},{"uz":"O","ru":"O","en":"O"},{"uz":"Ox","ru":"Ox","en":"Ox"}]'::jsonb, 2, '{"uz":"Kislorod lotincha Oxygenium deb ataladi, uning belgisi — O. Os esa osmiy elementining belgisi.","ru":"Кислород по-латински — Oxygenium, его знак — O. А Os — это знак осмия.","en":"Oxygen’s Latin name is Oxygenium and its symbol is O. Os is the symbol for osmium."}'::jsonb, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
('3cdc898f-72de-5cd6-8d87-131510508764', 'chemistry-02', 'CHEMISTRY', 1, 5, 9, '{"uz":"Suv","ru":"Вода","en":"Water"}'::jsonb, '{"uz":"Suvning kimyoviy formulasi qaysi?","ru":"Какова химическая формула воды?","en":"What is the chemical formula of water?"}'::jsonb, '[{"uz":"H₂O","ru":"H₂O","en":"H₂O"},{"uz":"CO₂","ru":"CO₂","en":"CO₂"},{"uz":"H₂O₂","ru":"H₂O₂","en":"H₂O₂"},{"uz":"NaCl","ru":"NaCl","en":"NaCl"}]'::jsonb, 0, '{"uz":"Suv molekulasi ikkita vodorod va bitta kislorod atomidan iborat: H₂O. H₂O₂ — vodorod peroksid, NaCl — osh tuzi.","ru":"Молекула воды состоит из двух атомов водорода и одного атома кислорода: H₂O. H₂O₂ — пероксид водорода, NaCl — поваренная соль.","en":"A water molecule has two hydrogen atoms and one oxygen atom: H₂O. H₂O₂ is hydrogen peroxide and NaCl is table salt."}'::jsonb, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
('8219ebb9-71c3-5cac-afca-b77239c756c7', 'chemistry-03', 'CHEMISTRY', 1, 5, 9, '{"uz":"Metallar va nometallar","ru":"Металлы и неметаллы","en":"Metals and non-metals"}'::jsonb, '{"uz":"Quyidagi elementlardan qaysi biri metall?","ru":"Какой из этих элементов является металлом?","en":"Which of these elements is a metal?"}'::jsonb, '[{"uz":"Oltingugurt","ru":"Сера","en":"Sulfur"},{"uz":"Kislorod","ru":"Кислород","en":"Oxygen"},{"uz":"Uglerod","ru":"Углерод","en":"Carbon"},{"uz":"Temir","ru":"Железо","en":"Iron"}]'::jsonb, 3, '{"uz":"Temir (Fe) — metall: u yaltiroq, issiqlik va elektr tokini yaxshi o‘tkazadi. Oltingugurt, kislorod va uglerod — nometallar.","ru":"Железо (Fe) — металл: оно блестит и хорошо проводит тепло и электрический ток. Сера, кислород и углерод — неметаллы.","en":"Iron (Fe) is a metal: it is shiny and conducts heat and electricity well. Sulfur, oxygen and carbon are non-metals."}'::jsonb, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
('52e64fdf-455d-5dcb-aa28-2541ad27160c', 'chemistry-04', 'CHEMISTRY', 1, 5, 9, '{"uz":"Aralashmalar","ru":"Смеси","en":"Mixtures"}'::jsonb, '{"uz":"Quyidagilardan qaysi biri aralashma emas, balki toza modda?","ru":"Что из перечисленного является чистым веществом, а не смесью?","en":"Which of these is a pure substance rather than a mixture?"}'::jsonb, '[{"uz":"Havo","ru":"Воздух","en":"Air"},{"uz":"Dengiz suvi","ru":"Морская вода","en":"Sea water"},{"uz":"Distillangan suv","ru":"Дистиллированная вода","en":"Distilled water"},{"uz":"Sut","ru":"Молоко","en":"Milk"}]'::jsonb, 2, '{"uz":"Distillangan suv faqat H₂O molekulalaridan iborat. Havo — gazlar aralashmasi, dengiz suvida tuzlar erigan, sut ham ko‘p moddalar aralashmasi.","ru":"Дистиллированная вода состоит только из молекул H₂O. Воздух — смесь газов, в морской воде растворены соли, молоко — тоже смесь многих веществ.","en":"Distilled water contains only H₂O molecules. Air is a mix of gases, sea water has dissolved salts, and milk is a mixture of many substances."}'::jsonb, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
('340de20a-811e-5c1b-94fc-af5a7818abe5', 'chemistry-05', 'CHEMISTRY', 1, 5, 9, '{"uz":"Kimyoviy hodisalar","ru":"Химические явления","en":"Chemical changes"}'::jsonb, '{"uz":"Quyidagilardan qaysi biri kimyoviy hodisa?","ru":"Какое из этих явлений является химическим?","en":"Which of these is a chemical change?"}'::jsonb, '[{"uz":"Muzning erishi","ru":"Таяние льда","en":"Melting ice"},{"uz":"Qog‘ozning yonishi","ru":"Горение бумаги","en":"Burning paper"},{"uz":"Suvning qaynashi","ru":"Кипение воды","en":"Boiling water"},{"uz":"Shishaning sinishi","ru":"Разбивание стекла","en":"Breaking glass"}]'::jsonb, 1, '{"uz":"Qog‘oz yonganda yangi moddalar — karbonat angidrid, suv va kul hosil bo‘ladi. Qolgan holatlarda modda o‘zgarmaydi, faqat uning holati yoki shakli o‘zgaradi.","ru":"При горении бумаги образуются новые вещества — углекислый газ, вода и зола. В остальных случаях вещество не меняется, меняется лишь его состояние или форма.","en":"Burning paper produces new substances: carbon dioxide, water and ash. In the other cases the substance stays the same and only its state or shape changes."}'::jsonb, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
('bd4fc851-3645-57d4-977a-a88eba8b4957', 'chemistry-06', 'CHEMISTRY', 2, 5, 9, '{"uz":"Atom tuzilishi","ru":"Строение атома","en":"Atomic structure"}'::jsonb, '{"uz":"Natriyning tartib raqami 11, nisbiy atom massasi 23. Neytral natriy atomida nechta elektron bor?","ru":"Порядковый номер натрия — 11, относительная атомная масса — 23. Сколько электронов в нейтральном атоме натрия?","en":"Sodium has atomic number 11 and relative atomic mass 23. How many electrons does a neutral sodium atom have?"}'::jsonb, '[{"uz":"11","ru":"11","en":"11"},{"uz":"23","ru":"23","en":"23"},{"uz":"12","ru":"12","en":"12"},{"uz":"34","ru":"34","en":"34"}]'::jsonb, 0, '{"uz":"Neytral atomda elektronlar soni protonlar soniga, ya’ni tartib raqamiga teng — 11 ta. 12 esa neytronlar soni (23 − 11).","ru":"В нейтральном атоме число электронов равно числу протонов, то есть порядковому номеру, — 11. А 12 — это число нейтронов (23 − 11).","en":"In a neutral atom the number of electrons equals the number of protons, which is the atomic number: 11. 12 is the number of neutrons (23 − 11)."}'::jsonb, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
('b09e140f-b009-5547-ac8a-d1994ecd2598', 'chemistry-07', 'CHEMISTRY', 2, 5, 9, '{"uz":"Molekulyar massa","ru":"Молекулярная масса","en":"Molecular mass"}'::jsonb, '{"uz":"CO₂ ning nisbiy molekulyar massasini hisoblang. (Ar: C = 12, O = 16)","ru":"Вычислите относительную молекулярную массу CO₂. (Ar: C = 12, O = 16)","en":"Calculate the relative molecular mass of CO₂. (Ar: C = 12, O = 16)"}'::jsonb, '[{"uz":"28","ru":"28","en":"28"},{"uz":"44","ru":"44","en":"44"},{"uz":"40","ru":"40","en":"40"},{"uz":"32","ru":"32","en":"32"}]'::jsonb, 1, '{"uz":"CO₂ tarkibida bitta uglerod va ikkita kislorod atomi bor: 12 + 2 · 16 = 44.","ru":"В CO₂ один атом углерода и два атома кислорода: 12 + 2 · 16 = 44.","en":"CO₂ has one carbon atom and two oxygen atoms: 12 + 2 × 16 = 44."}'::jsonb, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
('419672cf-97b7-5638-ae52-b9d7160fe47a', 'chemistry-08', 'CHEMISTRY', 2, 5, 9, '{"uz":"Indikatorlar","ru":"Индикаторы","en":"Indicators"}'::jsonb, '{"uz":"Lakmus kislotali eritmada qanday rangga kiradi?","ru":"В какой цвет окрашивается лакмус в растворе кислоты?","en":"What colour does litmus turn in an acidic solution?"}'::jsonb, '[{"uz":"Ko‘k","ru":"Синий","en":"Blue"},{"uz":"Qizil","ru":"Красный","en":"Red"},{"uz":"Binafsha","ru":"Фиолетовый","en":"Purple"},{"uz":"Sariq","ru":"Жёлтый","en":"Yellow"}]'::jsonb, 1, '{"uz":"Kislota lakmusni qizil rangga bo‘yaydi. Ishqorda lakmus ko‘karadi, neytral muhitda esa binafsha rangda qoladi.","ru":"Кислота окрашивает лакмус в красный цвет. В щёлочи лакмус синеет, а в нейтральной среде остаётся фиолетовым.","en":"Acids turn litmus red. In alkalis litmus turns blue, and in a neutral solution it stays purple."}'::jsonb, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
('87067596-da67-5ca1-a42c-5f44b28dd3f3', 'chemistry-09', 'CHEMISTRY', 2, 5, 9, '{"uz":"Valentlik","ru":"Валентность","en":"Valency"}'::jsonb, '{"uz":"Ko‘pchilik birikmalarda kislorodning valentligi nechaga teng?","ru":"Какова валентность кислорода в большинстве соединений?","en":"What is the valency of oxygen in most compounds?"}'::jsonb, '[{"uz":"I","ru":"I","en":"I"},{"uz":"IV","ru":"IV","en":"IV"},{"uz":"III","ru":"III","en":"III"},{"uz":"II","ru":"II","en":"II"}]'::jsonb, 3, '{"uz":"Kislorod deyarli barcha birikmalarda ikki valentli (II). Masalan, suvda (H₂O) bitta kislorod atomi ikkita vodorod atomi bilan bog‘langan.","ru":"Кислород почти во всех соединениях двухвалентен (II). Например, в воде (H₂O) один атом кислорода связан с двумя атомами водорода.","en":"Oxygen has a valency of II in almost all compounds. For example, in water (H₂O) one oxygen atom is bonded to two hydrogen atoms."}'::jsonb, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
('6b28cd2d-f5ed-5205-8077-dc316dae5b23', 'chemistry-10', 'CHEMISTRY', 2, 5, 9, '{"uz":"Aralashmalarni ajratish","ru":"Разделение смесей","en":"Separating mixtures"}'::jsonb, '{"uz":"Temir qipiqlari va oltingugurt kukuni aralashmasini qaysi usulda oson ajratish mumkin?","ru":"Каким способом проще всего разделить смесь железных опилок и порошка серы?","en":"What is the easiest way to separate a mixture of iron filings and sulfur powder?"}'::jsonb, '[{"uz":"Filtrlash","ru":"Фильтрованием","en":"Filtering"},{"uz":"Bug‘latish","ru":"Выпариванием","en":"Evaporating"},{"uz":"Distillash","ru":"Перегонкой","en":"Distilling"},{"uz":"Magnit yordamida","ru":"С помощью магнита","en":"Using a magnet"}]'::jsonb, 3, '{"uz":"Temir magnitga tortiladi, oltingugurt esa tortilmaydi. Shuning uchun magnit temir qipiqlarini aralashmadan oson ajratib oladi.","ru":"Железо притягивается магнитом, а сера — нет. Поэтому магнит легко извлекает железные опилки из смеси.","en":"Iron is attracted to a magnet but sulfur is not, so a magnet easily pulls the iron filings out of the mixture."}'::jsonb, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
('e6f6e885-1885-530c-9840-7dcf757634b7', 'chemistry-11', 'CHEMISTRY', 3, 5, 9, '{"uz":"Eritmalar","ru":"Растворы","en":"Solutions"}'::jsonb, '{"uz":"180 g suvda 20 g tuz eritildi. Eritmadagi tuzning massa ulushi qancha?","ru":"В 180 г воды растворили 20 г соли. Какова массовая доля соли в растворе?","en":"20 g of salt is dissolved in 180 g of water. What is the mass fraction of salt in the solution?"}'::jsonb, '[{"uz":"11%","ru":"11%","en":"11%"},{"uz":"9%","ru":"9%","en":"9%"},{"uz":"10%","ru":"10%","en":"10%"},{"uz":"20%","ru":"20%","en":"20%"}]'::jsonb, 2, '{"uz":"Eritma massasi 180 + 20 = 200 g. Tuzning massa ulushi: 20 : 200 = 0,1, ya’ni 10%.","ru":"Масса раствора 180 + 20 = 200 г. Массовая доля соли: 20 : 200 = 0,1, то есть 10%.","en":"The solution weighs 180 + 20 = 200 g. The mass fraction of salt is 20 ÷ 200 = 0.1, which is 10%."}'::jsonb, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
('d638aa90-7d47-5d1d-99ae-631a35cf5950', 'chemistry-12', 'CHEMISTRY', 3, 5, 9, '{"uz":"Reaksiya tenglamalari","ru":"Уравнения реакций","en":"Chemical equations"}'::jsonb, '{"uz":"2H₂ + O₂ → ?H₂O tenglamada H₂O oldiga qanday koeffitsiyent qo‘yiladi?","ru":"Какой коэффициент нужно поставить перед H₂O в уравнении 2H₂ + O₂ → ?H₂O?","en":"Which coefficient goes in front of H₂O in the equation 2H₂ + O₂ → ?H₂O?"}'::jsonb, '[{"uz":"1","ru":"1","en":"1"},{"uz":"2","ru":"2","en":"2"},{"uz":"3","ru":"3","en":"3"},{"uz":"4","ru":"4","en":"4"}]'::jsonb, 1, '{"uz":"Chap tomonda 4 ta vodorod va 2 ta kislorod atomi bor. O‘ng tomonda ham shuncha bo‘lishi uchun 2H₂O yoziladi.","ru":"Слева 4 атома водорода и 2 атома кислорода. Чтобы справа было столько же, пишем 2H₂O.","en":"The left side has 4 hydrogen atoms and 2 oxygen atoms. To get the same on the right, write 2H₂O."}'::jsonb, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
('4c90d682-1d26-55ed-b146-c2eadab1b94a', 'chemistry-13', 'CHEMISTRY', 3, 5, 9, '{"uz":"Elementning massa ulushi","ru":"Массовая доля элемента","en":"Mass fraction of element"}'::jsonb, '{"uz":"Suvdagi (H₂O) kislorodning massa ulushi taxminan qancha? (Ar: H = 1, O = 16)","ru":"Какова примерно массовая доля кислорода в воде (H₂O)? (Ar: H = 1, O = 16)","en":"Roughly what is the mass fraction of oxygen in water (H₂O)? (Ar: H = 1, O = 16)"}'::jsonb, '[{"uz":"89%","ru":"89%","en":"89%"},{"uz":"11%","ru":"11%","en":"11%"},{"uz":"50%","ru":"50%","en":"50%"},{"uz":"94%","ru":"94%","en":"94%"}]'::jsonb, 0, '{"uz":"Mr(H₂O) = 2 · 1 + 16 = 18. Kislorodning ulushi: 16 : 18 ≈ 0,89, ya’ni taxminan 89%.","ru":"Mr(H₂O) = 2 · 1 + 16 = 18. Доля кислорода: 16 : 18 ≈ 0,89, то есть около 89%.","en":"Mr(H₂O) = 2 × 1 + 16 = 18. Oxygen’s share is 16 ÷ 18 ≈ 0.89, or about 89%."}'::jsonb, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
('d85b475e-752a-511f-b14d-95c5c6ce1aca', 'chemistry-14', 'CHEMISTRY', 3, 5, 9, '{"uz":"Modda miqdori","ru":"Количество вещества","en":"Amount of substance"}'::jsonb, '{"uz":"36 g suvda necha mol modda bor? (M(H₂O) = 18 g/mol)","ru":"Сколько моль вещества содержится в 36 г воды? (M(H₂O) = 18 г/моль)","en":"How many moles are there in 36 g of water? (M(H₂O) = 18 g/mol)"}'::jsonb, '[{"uz":"2 mol","ru":"2 моль","en":"2 mol"},{"uz":"0,5 mol","ru":"0,5 моль","en":"0.5 mol"},{"uz":"18 mol","ru":"18 моль","en":"18 mol"},{"uz":"648 mol","ru":"648 моль","en":"648 mol"}]'::jsonb, 0, '{"uz":"Modda miqdori massani molyar massaga bo‘lish bilan topiladi: n = m / M = 36 : 18 = 2 mol.","ru":"Количество вещества равно массе, делённой на молярную массу: n = m / M = 36 : 18 = 2 моль.","en":"The amount of substance is mass divided by molar mass: n = m / M = 36 ÷ 18 = 2 mol."}'::jsonb, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
('4c3f8805-0694-52a1-8b6c-15edb2cd16e8', 'chemistry-15', 'CHEMISTRY', 3, 5, 9, '{"uz":"Reaksiya turlari","ru":"Типы реакций","en":"Types of reactions"}'::jsonb, '{"uz":"Zn + 2HCl → ZnCl₂ + H₂↑ reaksiyasi qaysi turga kiradi?","ru":"К какому типу относится реакция Zn + 2HCl → ZnCl₂ + H₂↑?","en":"What type of reaction is Zn + 2HCl → ZnCl₂ + H₂↑?"}'::jsonb, '[{"uz":"Birikish","ru":"Соединения","en":"Combination"},{"uz":"Parchalanish","ru":"Разложения","en":"Decomposition"},{"uz":"O‘rin olish","ru":"Замещения","en":"Substitution"},{"uz":"Almashinish","ru":"Обмена","en":"Exchange"}]'::jsonb, 2, '{"uz":"Oddiy modda (rux) murakkab moddadagi vodorodning o‘rnini oladi. Bunday reaksiya o‘rin olish reaksiyasi deyiladi.","ru":"Простое вещество (цинк) занимает место водорода в сложном веществе. Такая реакция называется реакцией замещения.","en":"A simple substance (zinc) takes the place of hydrogen in a compound. This is called a substitution reaction."}'::jsonb, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
('143d4709-0bd3-58c5-8d0e-6c629245e93c', 'english-01', 'ENGLISH', 1, 5, 9, '{"uz":"Hozirgi oddiy zamon","ru":"Present Simple","en":"Present Simple"}'::jsonb, '{"uz":"Gapni to‘ldiring: She ___ to school every day.","ru":"Заполните пропуск: She ___ to school every day.","en":"Fill in the blank: She ___ to school every day."}'::jsonb, '[{"uz":"go","ru":"go","en":"go"},{"uz":"goes","ru":"goes","en":"goes"},{"uz":"going","ru":"going","en":"going"},{"uz":"gone","ru":"gone","en":"gone"}]'::jsonb, 1, '{"uz":"Present Simple zamonida he, she, it bilan fe’lga -s yoki -es qo‘shiladi: she goes.","ru":"В Present Simple с he, she, it к глаголу добавляется -s или -es: she goes.","en":"In the Present Simple, verbs take -s or -es after he, she and it: she goes."}'::jsonb, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
('8b994fc9-6c91-57b3-80ca-4704dab1bec1', 'english-02', 'ENGLISH', 1, 5, 9, '{"uz":"Artikllar","ru":"Артикли","en":"Articles"}'::jsonb, '{"uz":"Gapni to‘ldiring: I have ___ umbrella.","ru":"Заполните пропуск: I have ___ umbrella.","en":"Fill in the blank: I have ___ umbrella."}'::jsonb, '[{"uz":"some","ru":"some","en":"some"},{"uz":"a","ru":"a","en":"a"},{"uz":"two","ru":"two","en":"two"},{"uz":"an","ru":"an","en":"an"}]'::jsonb, 3, '{"uz":"“Umbrella” so‘zi unli tovush bilan boshlanadi, shuning uchun “an” artikli ishlatiladi.","ru":"Слово umbrella начинается с гласного звука, поэтому нужен артикль an.","en":"Umbrella starts with a vowel sound, so we use the article an."}'::jsonb, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
('6d449a6f-201e-5afa-ac7c-b7c531ee7e82', 'english-03', 'ENGLISH', 1, 5, 9, '{"uz":"Ko‘plik shakli","ru":"Множественное число","en":"Plural nouns"}'::jsonb, '{"uz":"“child” so‘zining ko‘plik shaklini tanlang.","ru":"Выберите форму множественного числа слова “child”.","en":"Choose the plural form of “child”."}'::jsonb, '[{"uz":"children","ru":"children","en":"children"},{"uz":"childs","ru":"childs","en":"childs"},{"uz":"childrens","ru":"childrens","en":"childrens"},{"uz":"childes","ru":"childes","en":"childes"}]'::jsonb, 0, '{"uz":"“Child” qoidaga bo‘ysunmaydigan ot: uning ko‘plik shakli “children” bo‘ladi.","ru":"Child — исключение: его множественное число — children.","en":"Child is an irregular noun: its plural is children."}'::jsonb, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
('2c312f45-2c93-55b8-8c7c-3d7ceabaecd8', 'english-04', 'ENGLISH', 1, 5, 9, '{"uz":"Antonimlar","ru":"Антонимы","en":"Opposites"}'::jsonb, '{"uz":"“cheap” so‘zining antonimini tanlang.","ru":"Выберите антоним к слову “cheap”.","en":"Choose the opposite of “cheap”."}'::jsonb, '[{"uz":"small","ru":"small","en":"small"},{"uz":"easy","ru":"easy","en":"easy"},{"uz":"poor","ru":"poor","en":"poor"},{"uz":"expensive","ru":"expensive","en":"expensive"}]'::jsonb, 3, '{"uz":"“Cheap” — arzon, “expensive” — qimmat degani, ular qarama-qarshi ma’noli so‘zlar.","ru":"Cheap значит «дешёвый», а expensive — «дорогой»; это антонимы.","en":"Cheap means low in price and expensive means high in price, so they are opposites."}'::jsonb, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
('025f52c4-6716-503e-8857-dcc1fbbdd5af', 'english-05', 'ENGLISH', 1, 5, 9, '{"uz":"Predloglar","ru":"Предлоги","en":"Prepositions"}'::jsonb, '{"uz":"Gapni to‘ldiring: My birthday is ___ May.","ru":"Заполните пропуск: My birthday is ___ May.","en":"Fill in the blank: My birthday is ___ May."}'::jsonb, '[{"uz":"on","ru":"on","en":"on"},{"uz":"at","ru":"at","en":"at"},{"uz":"in","ru":"in","en":"in"},{"uz":"to","ru":"to","en":"to"}]'::jsonb, 2, '{"uz":"Oylar nomi oldidan “in” predlogi ishlatiladi: in May, in June.","ru":"Перед названиями месяцев используется предлог in: in May, in June.","en":"We use in with months: in May, in June."}'::jsonb, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
('c3f3adaf-6e9e-5ae0-adbc-416444232e26', 'english-06', 'ENGLISH', 2, 5, 9, '{"uz":"O‘tgan oddiy zamon","ru":"Past Simple","en":"Past Simple"}'::jsonb, '{"uz":"Gapni to‘ldiring: Yesterday we ___ a great film.","ru":"Заполните пропуск: Yesterday we ___ a great film.","en":"Fill in the blank: Yesterday we ___ a great film."}'::jsonb, '[{"uz":"saw","ru":"saw","en":"saw"},{"uz":"see","ru":"see","en":"see"},{"uz":"seen","ru":"seen","en":"seen"},{"uz":"seeing","ru":"seeing","en":"seeing"}]'::jsonb, 0, '{"uz":"“Yesterday” o‘tgan zamonni bildiradi; “see” fe’lining Past Simple shakli — “saw”.","ru":"Yesterday указывает на прошлое; форма Past Simple глагола see — saw.","en":"Yesterday points to the past, and the Past Simple form of see is saw."}'::jsonb, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
('a0becfd1-9bb8-5e60-8839-31e3f2f071c3', 'english-07', 'ENGLISH', 2, 5, 9, '{"uz":"Qiyosiy daraja","ru":"Сравнительная степень","en":"Comparatives"}'::jsonb, '{"uz":"Gapni to‘ldiring: This book is ___ than that one.","ru":"Заполните пропуск: This book is ___ than that one.","en":"Fill in the blank: This book is ___ than that one."}'::jsonb, '[{"uz":"interesting","ru":"interesting","en":"interesting"},{"uz":"most interesting","ru":"most interesting","en":"most interesting"},{"uz":"more interesting","ru":"more interesting","en":"more interesting"},{"uz":"interestinger","ru":"interestinger","en":"interestinger"}]'::jsonb, 2, '{"uz":"Ko‘p bo‘g‘inli sifatlar “more” yordamida qiyoslanadi: more interesting than.","ru":"Длинные прилагательные образуют сравнительную степень с more: more interesting than.","en":"Long adjectives form the comparative with more: more interesting than."}'::jsonb, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
('70cacef3-c5e9-50d2-8bc0-3b6970d34727', 'english-08', 'ENGLISH', 2, 5, 9, '{"uz":"Hozirgi davomli zamon","ru":"Present Continuous","en":"Present Continuous"}'::jsonb, '{"uz":"Gapni to‘ldiring: Look! The children ___ in the garden.","ru":"Заполните пропуск: Look! The children ___ in the garden.","en":"Fill in the blank: Look! The children ___ in the garden."}'::jsonb, '[{"uz":"play","ru":"play","en":"play"},{"uz":"plays","ru":"plays","en":"plays"},{"uz":"played","ru":"played","en":"played"},{"uz":"are playing","ru":"are playing","en":"are playing"}]'::jsonb, 3, '{"uz":"“Look!” harakat ayni paytda bo‘layotganini ko‘rsatadi, shuning uchun Present Continuous kerak: are playing.","ru":"Look! показывает, что действие происходит сейчас, поэтому нужен Present Continuous: are playing.","en":"Look! shows the action is happening right now, so we need the Present Continuous: are playing."}'::jsonb, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
('2a9364c3-ff07-5e9f-876a-35102c1af4f5', 'english-09', 'ENGLISH', 2, 5, 9, '{"uz":"So‘roq so‘zlari","ru":"Вопросительные слова","en":"Question words"}'::jsonb, '{"uz":"Gapni to‘ldiring: ___ do you live? — In Tashkent.","ru":"Заполните пропуск: ___ do you live? — In Tashkent.","en":"Fill in the blank: ___ do you live? — In Tashkent."}'::jsonb, '[{"uz":"What","ru":"What","en":"What"},{"uz":"Where","ru":"Where","en":"Where"},{"uz":"When","ru":"When","en":"When"},{"uz":"Who","ru":"Who","en":"Who"}]'::jsonb, 1, '{"uz":"Javob joyni bildiradi (In Tashkent), joy haqida esa “Where” bilan so‘raladi.","ru":"Ответ называет место (In Tashkent), а о месте спрашивают словом Where.","en":"The answer names a place (In Tashkent), and we ask about places with Where."}'::jsonb, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
('6a7bb478-b585-525a-80f8-94604b081dbf', 'english-10', 'ENGLISH', 2, 5, 9, '{"uz":"Orttirma daraja","ru":"Превосходная степень","en":"Superlatives"}'::jsonb, '{"uz":"“bad” sifatining orttirma darajasini tanlang.","ru":"Выберите превосходную степень прилагательного “bad”.","en":"Choose the superlative form of “bad”."}'::jsonb, '[{"uz":"the worst","ru":"the worst","en":"the worst"},{"uz":"worse","ru":"worse","en":"worse"},{"uz":"the baddest","ru":"the baddest","en":"the baddest"},{"uz":"the most bad","ru":"the most bad","en":"the most bad"}]'::jsonb, 0, '{"uz":"“Bad” qoidaga bo‘ysunmaydigan sifat: bad – worse – the worst.","ru":"Bad — исключение: bad – worse – the worst.","en":"Bad is irregular: bad – worse – the worst."}'::jsonb, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
('f90fedcd-1956-5e57-86ba-ea83a8b2ad1b', 'english-11', 'ENGLISH', 3, 5, 9, '{"uz":"Hozirgi tugallangan zamon","ru":"Present Perfect","en":"Present Perfect"}'::jsonb, '{"uz":"Gapni to‘ldiring: She ___ here since 2020.","ru":"Заполните пропуск: She ___ here since 2020.","en":"Fill in the blank: She ___ here since 2020."}'::jsonb, '[{"uz":"lives","ru":"lives","en":"lives"},{"uz":"is living","ru":"is living","en":"is living"},{"uz":"has lived","ru":"has lived","en":"has lived"},{"uz":"lived","ru":"lived","en":"lived"}]'::jsonb, 2, '{"uz":"“Since” o‘tmishda boshlanib hozirgacha davom etayotgan holatni bildiradi, bu Present Perfect: has lived.","ru":"Since обозначает действие, которое началось в прошлом и длится до сих пор, — это Present Perfect: has lived.","en":"Since describes something that started in the past and is still true, so we use the Present Perfect: has lived."}'::jsonb, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
('44279794-0a26-5cbe-8439-8138fd59b316', 'english-12', 'ENGLISH', 3, 5, 9, '{"uz":"Majhul nisbat","ru":"Страдательный залог","en":"Passive voice"}'::jsonb, '{"uz":"Gapni to‘ldiring: This bridge ___ in 1990.","ru":"Заполните пропуск: This bridge ___ in 1990.","en":"Fill in the blank: This bridge ___ in 1990."}'::jsonb, '[{"uz":"built","ru":"built","en":"built"},{"uz":"was built","ru":"was built","en":"was built"},{"uz":"has built","ru":"has built","en":"has built"},{"uz":"is building","ru":"is building","en":"is building"}]'::jsonb, 1, '{"uz":"Ko‘prikni kimdir qurgan, shuning uchun o‘tgan zamon majhul nisbati kerak: was + V3 (was built).","ru":"Мост кто-то построил, поэтому нужен страдательный залог в прошедшем времени: was + V3 (was built).","en":"Someone built the bridge, so we need the past passive: was + V3 (was built)."}'::jsonb, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
('22e772fd-8d94-5496-b136-a221d380a507', 'english-13', 'ENGLISH', 3, 5, 9, '{"uz":"Shart gaplar","ru":"Условные предложения","en":"Conditionals"}'::jsonb, '{"uz":"Gapni to‘ldiring: If it ___ tomorrow, we will stay at home.","ru":"Заполните пропуск: If it ___ tomorrow, we will stay at home.","en":"Fill in the blank: If it ___ tomorrow, we will stay at home."}'::jsonb, '[{"uz":"rains","ru":"rains","en":"rains"},{"uz":"will rain","ru":"will rain","en":"will rain"},{"uz":"rained","ru":"rained","en":"rained"},{"uz":"raining","ru":"raining","en":"raining"}]'::jsonb, 0, '{"uz":"Birinchi tur shart gapda “if” qismida Present Simple ishlatiladi: If it rains, we will…","ru":"В условных предложениях первого типа после if используется Present Simple: If it rains, we will…","en":"In first conditional sentences, the if-part uses the Present Simple: If it rains, we will…"}'::jsonb, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
('9d2db8af-1088-5c90-add6-4fd5d93d06d2', 'english-14', 'ENGLISH', 3, 5, 9, '{"uz":"Gerundiy","ru":"Герундий","en":"Gerunds"}'::jsonb, '{"uz":"Gapni to‘ldiring: I enjoy ___ books in the evening.","ru":"Заполните пропуск: I enjoy ___ books in the evening.","en":"Fill in the blank: I enjoy ___ books in the evening."}'::jsonb, '[{"uz":"read","ru":"read","en":"read"},{"uz":"to read","ru":"to read","en":"to read"},{"uz":"reads","ru":"reads","en":"reads"},{"uz":"reading","ru":"reading","en":"reading"}]'::jsonb, 3, '{"uz":"“Enjoy” fe’lidan keyin keladigan fe’l -ing shaklini oladi: enjoy reading.","ru":"После глагола enjoy следующий глагол ставится в форму -ing: enjoy reading.","en":"After enjoy, the next verb takes the -ing form: enjoy reading."}'::jsonb, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
('3ad6843b-79ba-573a-8913-2acfdf3b28fe', 'english-15', 'ENGLISH', 3, 5, 9, '{"uz":"Noto‘g‘ri fe’llar","ru":"Неправильные глаголы","en":"Irregular verbs"}'::jsonb, '{"uz":"Gapni to‘ldiring: They have already ___ their homework.","ru":"Заполните пропуск: They have already ___ their homework.","en":"Fill in the blank: They have already ___ their homework."}'::jsonb, '[{"uz":"do","ru":"do","en":"do"},{"uz":"done","ru":"done","en":"done"},{"uz":"did","ru":"did","en":"did"},{"uz":"doing","ru":"doing","en":"doing"}]'::jsonb, 1, '{"uz":"“Have”dan keyin fe’lning uchinchi shakli (V3) keladi: do – did – done, demak “done”.","ru":"После have нужна третья форма глагола (V3): do – did – done, значит done.","en":"After have we need the third form (V3): do – did – done, so the answer is done."}'::jsonb, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
('126e47c8-e551-5fce-bfa7-9b13a810af65', 'english-16', 'ENGLISH', 1, 1, 4, '{"uz":"Ranglar","ru":"Цвета","en":"Colours"}'::jsonb, '{"uz":"Pishgan pomidor qanday rangda bo‘ladi? Inglizcha so‘zni tanlang.","ru":"Какого цвета спелый помидор? Выберите английское слово.","en":"What colour is a ripe tomato?"}'::jsonb, '[{"uz":"blue","ru":"blue","en":"blue"},{"uz":"green","ru":"green","en":"green"},{"uz":"red","ru":"red","en":"red"},{"uz":"white","ru":"white","en":"white"}]'::jsonb, 2, '{"uz":"Pishgan pomidor qizil bo‘ladi, inglizchada qizil — “red”.","ru":"Спелый помидор красный, а «красный» по-английски — red.","en":"A ripe tomato is red."}'::jsonb, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
('0cd39af9-1246-5f2f-9096-66b1733d89a9', 'english-17', 'ENGLISH', 1, 1, 4, '{"uz":"Hayvonlar","ru":"Животные","en":"Animals"}'::jsonb, '{"uz":"Qaysi hayvon “mu-u” deb ovoz chiqaradi? Inglizcha so‘zni tanlang.","ru":"Какое животное говорит «му-у»? Выберите английское слово.","en":"Which animal says “moo”?"}'::jsonb, '[{"uz":"cat","ru":"cat","en":"cat"},{"uz":"dog","ru":"dog","en":"dog"},{"uz":"duck","ru":"duck","en":"duck"},{"uz":"cow","ru":"cow","en":"cow"}]'::jsonb, 3, '{"uz":"Sigir “mu-u” deydi; inglizchada sigir — “cow”.","ru":"«Му-у» говорит корова, а корова по-английски — cow.","en":"A cow says moo."}'::jsonb, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
('5aa9ce33-7891-56ca-8a2e-67d7496704b6', 'english-18', 'ENGLISH', 1, 1, 4, '{"uz":"Alifbo","ru":"Алфавит","en":"Alphabet"}'::jsonb, '{"uz":"Ingliz alifbosida “C” harfidan keyin qaysi harf keladi?","ru":"Какая буква идёт после “C” в английском алфавите?","en":"Which letter comes after “C” in the English alphabet?"}'::jsonb, '[{"uz":"D","ru":"D","en":"D"},{"uz":"B","ru":"B","en":"B"},{"uz":"E","ru":"E","en":"E"},{"uz":"F","ru":"F","en":"F"}]'::jsonb, 0, '{"uz":"Ingliz alifbosi shunday boshlanadi: A, B, C, D, E…","ru":"Английский алфавит начинается так: A, B, C, D, E…","en":"The English alphabet starts like this: A, B, C, D, E…"}'::jsonb, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
('7f7f0f1f-2b6e-5c82-8f52-4504686ff0e7', 'english-19', 'ENGLISH', 1, 1, 4, '{"uz":"Antonimlar","ru":"Антонимы","en":"Opposites"}'::jsonb, '{"uz":"“big” so‘zining antonimini tanlang.","ru":"Выберите слово, противоположное по значению “big”.","en":"What is the opposite of “big”?"}'::jsonb, '[{"uz":"tall","ru":"tall","en":"tall"},{"uz":"long","ru":"long","en":"long"},{"uz":"small","ru":"small","en":"small"},{"uz":"old","ru":"old","en":"old"}]'::jsonb, 2, '{"uz":"“Big” — katta, “small” — kichik; ular qarama-qarshi ma’noli so‘zlar.","ru":"Big — «большой», small — «маленький»; это противоположности.","en":"Big and small have opposite meanings."}'::jsonb, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
('e7e85559-5dd6-59e1-80dc-efc1a9cb8c67', 'english-20', 'ENGLISH', 2, 1, 4, '{"uz":"Ko‘plik shakli","ru":"Множественное число","en":"Plural nouns"}'::jsonb, '{"uz":"Gapni to‘ldiring: one cat, two ___","ru":"Заполните пропуск: one cat, two ___","en":"Fill in the blank: one cat, two ___"}'::jsonb, '[{"uz":"cat","ru":"cat","en":"cat"},{"uz":"cats","ru":"cats","en":"cats"},{"uz":"cates","ru":"cates","en":"cates"},{"uz":"catts","ru":"catts","en":"catts"}]'::jsonb, 1, '{"uz":"Ko‘pchilik otlarning ko‘pligi oxiriga -s qo‘shish bilan yasaladi: cat — cats.","ru":"Множественное число большинства существительных образуется с помощью -s: cat — cats.","en":"Most nouns form the plural by adding -s: cat — cats."}'::jsonb, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
('6c53ce49-cdc0-5ebc-9f16-f5c254e8948d', 'english-21', 'ENGLISH', 2, 1, 4, '{"uz":"“To be” fe’li","ru":"Глагол to be","en":"The verb “to be”"}'::jsonb, '{"uz":"Gapni to‘ldiring: I ___ a pupil.","ru":"Заполните пропуск: I ___ a pupil.","en":"Fill in the blank: I ___ a pupil."}'::jsonb, '[{"uz":"am","ru":"am","en":"am"},{"uz":"is","ru":"is","en":"is"},{"uz":"are","ru":"are","en":"are"},{"uz":"be","ru":"be","en":"be"}]'::jsonb, 0, '{"uz":"“I” bilan “to be” fe’li “am” shaklida keladi: I am.","ru":"С местоимением I глагол to be имеет форму am: I am.","en":"With I, the verb to be becomes am: I am."}'::jsonb, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
('25bf256e-c15a-5cb7-b6ea-e742d9690c37', 'geography-01', 'GEOGRAPHY', 1, 5, 9, '{"uz":"Okeanlar","ru":"Океаны","en":"Oceans"}'::jsonb, '{"uz":"Yer sharidagi eng katta okean qaysi?","ru":"Какой океан самый большой на Земле?","en":"Which is the largest ocean on Earth?"}'::jsonb, '[{"uz":"Atlantika okeani","ru":"Атлантический","en":"Atlantic Ocean"},{"uz":"Hind okeani","ru":"Индийский","en":"Indian Ocean"},{"uz":"Tinch okeani","ru":"Тихий","en":"Pacific Ocean"},{"uz":"Shimoliy Muz okeani","ru":"Северный Ледовитый","en":"Arctic Ocean"}]'::jsonb, 2, '{"uz":"Tinch okeani eng katta va eng chuqur okean bo‘lib, Yer yuzasining qariyb uchdan bir qismini egallaydi.","ru":"Тихий океан — самый большой и самый глубокий: он занимает почти треть поверхности Земли.","en":"The Pacific is the largest and deepest ocean, covering almost a third of the Earth''s surface."}'::jsonb, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
('08d85699-cee2-5228-a812-87f23620cf29', 'geography-02', 'GEOGRAPHY', 1, 5, 9, '{"uz":"Materiklar","ru":"Материки","en":"Continents"}'::jsonb, '{"uz":"Eng katta materik qaysi?","ru":"Какой материк самый большой?","en":"Which is the largest continent?"}'::jsonb, '[{"uz":"Yevroosiyo","ru":"Евразия","en":"Eurasia"},{"uz":"Afrika","ru":"Африка","en":"Africa"},{"uz":"Antarktida","ru":"Антарктида","en":"Antarctica"},{"uz":"Shimoliy Amerika","ru":"Северная Америка","en":"North America"}]'::jsonb, 0, '{"uz":"Yevroosiyo eng katta materik bo‘lib, unda dunyoning ikki qismi — Yevropa va Osiyo joylashgan. O‘zbekiston ham shu materikda.","ru":"Евразия — самый большой материк, на нём расположены две части света: Европа и Азия. Узбекистан тоже находится здесь.","en":"Eurasia is the largest continent and includes two parts of the world, Europe and Asia. Uzbekistan is located on it too."}'::jsonb, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
('2f15b1a3-189e-546d-ae3b-b27394ff0a14', 'geography-03', 'GEOGRAPHY', 1, 5, 9, '{"uz":"O‘zbekiston geografiyasi","ru":"География Узбекистана","en":"Geography of Uzbekistan"}'::jsonb, '{"uz":"O‘zbekiston Respublikasining poytaxti qaysi shahar?","ru":"Какой город является столицей Республики Узбекистан?","en":"What is the capital city of the Republic of Uzbekistan?"}'::jsonb, '[{"uz":"Samarqand","ru":"Самарканд","en":"Samarkand"},{"uz":"Toshkent","ru":"Ташкент","en":"Tashkent"},{"uz":"Buxoro","ru":"Бухара","en":"Bukhara"},{"uz":"Namangan","ru":"Наманган","en":"Namangan"}]'::jsonb, 1, '{"uz":"Toshkent — O‘zbekistonning poytaxti va eng katta shahri. U Chirchiq daryosi vodiysida joylashgan.","ru":"Ташкент — столица и самый крупный город Узбекистана. Он расположен в долине реки Чирчик.","en":"Tashkent is the capital and largest city of Uzbekistan. It lies in the valley of the Chirchiq River."}'::jsonb, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
('ddc86bd0-337e-564a-a46a-0f20144129b4', 'geography-04', 'GEOGRAPHY', 1, 5, 9, '{"uz":"Tog‘lar","ru":"Горы","en":"Mountains"}'::jsonb, '{"uz":"Dunyodagi eng baland tog‘ cho‘qqisi qaysi?","ru":"Какая горная вершина самая высокая в мире?","en":"Which is the highest mountain peak in the world?"}'::jsonb, '[{"uz":"Elbrus","ru":"Эльбрус","en":"Elbrus"},{"uz":"Kilimanjaro","ru":"Килиманджаро","en":"Kilimanjaro"},{"uz":"Monblan","ru":"Монблан","en":"Mont Blanc"},{"uz":"Jomolungma (Everest)","ru":"Джомолунгма (Эверест)","en":"Everest (Chomolungma)"}]'::jsonb, 3, '{"uz":"Jomolungma (Everest) Himolay tog‘larida joylashgan va uning balandligi 8848 metrdan oshadi.","ru":"Джомолунгма (Эверест) находится в Гималаях, её высота превышает 8848 метров.","en":"Everest (Chomolungma) is in the Himalayas, and its height is more than 8,848 metres."}'::jsonb, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
('e84dfc3e-9563-5620-9bea-50f8179d9548', 'geography-05', 'GEOGRAPHY', 1, 5, 9, '{"uz":"Orol dengizi","ru":"Аральское море","en":"Aral Sea"}'::jsonb, '{"uz":"Amudaryo va Sirdaryo qaysi suv havzasiga quyiladi?","ru":"В какой водоём впадают Амударья и Сырдарья?","en":"Which body of water do the Amu Darya and the Syr Darya flow into?"}'::jsonb, '[{"uz":"Kaspiy dengizi","ru":"Каспийское море","en":"Caspian Sea"},{"uz":"Orol dengizi","ru":"Аральское море","en":"Aral Sea"},{"uz":"Qora dengiz","ru":"Чёрное море","en":"Black Sea"},{"uz":"Issiqko‘l","ru":"Иссык-Куль","en":"Lake Issyk-Kul"}]'::jsonb, 1, '{"uz":"Ikkala daryo ham Orol dengiziga quyiladi. Suvning ko‘p qismi sug‘orishga sarflangani uchun Orol dengizi ancha qurib, kichrayib ketgan.","ru":"Обе реки впадают в Аральское море. Из-за того что много воды забирают на орошение, море сильно обмелело и уменьшилось.","en":"Both rivers flow into the Aral Sea. Because so much of their water is used for irrigation, the sea has shrunk dramatically."}'::jsonb, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
('9b73328e-134d-54eb-b3cb-d4bc0f562063', 'geography-06', 'GEOGRAPHY', 2, 5, 9, '{"uz":"Ma’muriy bo‘linish","ru":"Административное деление","en":"Administrative divisions"}'::jsonb, '{"uz":"O‘zbekiston tarkibida nechta viloyat bor?","ru":"Сколько областей в составе Узбекистана?","en":"How many regions (viloyats) does Uzbekistan have?"}'::jsonb, '[{"uz":"8 ta","ru":"8","en":"8"},{"uz":"10 ta","ru":"10","en":"10"},{"uz":"12 ta","ru":"12","en":"12"},{"uz":"14 ta","ru":"14","en":"14"}]'::jsonb, 2, '{"uz":"O‘zbekistonda 12 ta viloyat bor. Ulardan tashqari, Qoraqalpog‘iston Respublikasi va Toshkent shahri ham alohida ma’muriy birlik hisoblanadi.","ru":"В Узбекистане 12 областей. Кроме того, отдельными единицами являются Республика Каракалпакстан и город Ташкент.","en":"Uzbekistan has 12 regions. In addition, the Republic of Karakalpakstan and the city of Tashkent are separate administrative units."}'::jsonb, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
('c6b84f17-6d29-5489-a7a0-d2620f7783ea', 'geography-07', 'GEOGRAPHY', 2, 5, 9, '{"uz":"Yerning tuzilishi","ru":"Строение Земли","en":"Earth''s structure"}'::jsonb, '{"uz":"Yer po‘sti ostida joylashgan va Yer hajmining eng katta qismini egallaydigan qatlam qanday ataladi?","ru":"Как называется слой под земной корой, который занимает большую часть объёма Земли?","en":"What is the layer beneath the Earth''s crust that makes up most of the Earth''s volume called?"}'::jsonb, '[{"uz":"Atmosfera","ru":"Атмосфера","en":"Atmosphere"},{"uz":"Yadro","ru":"Ядро","en":"Core"},{"uz":"Gidrosfera","ru":"Гидросфера","en":"Hydrosphere"},{"uz":"Mantiya","ru":"Мантия","en":"Mantle"}]'::jsonb, 3, '{"uz":"Mantiya Yer po‘sti bilan yadro orasida joylashgan va sayyora hajmining 80 foizdan ortig‘ini egallaydi.","ru":"Мантия лежит между земной корой и ядром и занимает более 80 % объёма планеты.","en":"The mantle lies between the crust and the core and makes up more than 80% of the planet''s volume."}'::jsonb, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
('414435de-84b9-5498-8d3e-9b8591398bb7', 'geography-08', 'GEOGRAPHY', 2, 5, 9, '{"uz":"Xarita va koordinatalar","ru":"Карты и координаты","en":"Maps and coordinates"}'::jsonb, '{"uz":"Geografik uzunlik qaysi chiziqdan boshlab hisoblanadi?","ru":"От какой линии отсчитывается географическая долгота?","en":"From which line is geographic longitude measured?"}'::jsonb, '[{"uz":"Bosh (Grinvich) meridiani","ru":"Нулевой (Гринвичский) меридиан","en":"Prime (Greenwich) meridian"},{"uz":"Ekvator","ru":"Экватор","en":"Equator"},{"uz":"Shimoliy tropik","ru":"Северный тропик","en":"Tropic of Cancer"},{"uz":"Shimoliy qutb doirasi","ru":"Северный полярный круг","en":"Arctic Circle"}]'::jsonb, 0, '{"uz":"Uzunlik Grinvich orqali o‘tuvchi bosh meridiandan sharqqa va g‘arbga qarab 0° dan 180° gacha hisoblanadi. Kenglik esa ekvatordan hisoblanadi.","ru":"Долготу отсчитывают от нулевого меридиана, проходящего через Гринвич, на восток и запад от 0° до 180°. А широту — от экватора.","en":"Longitude is measured east and west from 0° to 180°, starting at the prime meridian through Greenwich. Latitude is measured from the Equator."}'::jsonb, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
('6c943582-43cf-52a8-8a10-755e4baf8978', 'geography-09', 'GEOGRAPHY', 2, 5, 9, '{"uz":"Iqlim","ru":"Климат","en":"Climate"}'::jsonb, '{"uz":"O‘zbekiston iqlimi qanday iqlim turiga kiradi?","ru":"К какому типу относится климат Узбекистана?","en":"What type of climate does Uzbekistan have?"}'::jsonb, '[{"uz":"Nam tropik","ru":"Влажный тропический","en":"Humid tropical"},{"uz":"Ekvatorial","ru":"Экваториальный","en":"Equatorial"},{"uz":"Keskin kontinental","ru":"Резко континентальный","en":"Sharply continental"},{"uz":"Arktika iqlimi","ru":"Арктический","en":"Arctic"}]'::jsonb, 2, '{"uz":"O‘zbekiston okeanlardan juda uzoqda joylashgan. Shuning uchun yozi issiq va quruq, qishi nisbatan sovuq, yog‘ingarchilik esa kam bo‘ladi.","ru":"Узбекистан находится очень далеко от океанов. Поэтому лето здесь жаркое и сухое, зима сравнительно холодная, а осадков мало.","en":"Uzbekistan is very far from any ocean. That is why summers are hot and dry, winters are fairly cold, and there is little rainfall."}'::jsonb, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
('429a6558-db50-5674-8cf2-74c709aa4556', 'geography-10', 'GEOGRAPHY', 2, 5, 9, '{"uz":"Tabiiy zonalar","ru":"Природные зоны","en":"Natural zones"}'::jsonb, '{"uz":"Yil bo‘yi issiq va deyarli har kuni yomg‘ir yog‘adigan, qalin doim yashil o‘rmonlar o‘sadigan tabiiy zona qaysi?","ru":"В какой природной зоне круглый год жарко, почти каждый день идут дожди и растут густые вечнозелёные леса?","en":"Which natural zone is hot all year, gets rain almost every day and has dense evergreen forests?"}'::jsonb, '[{"uz":"Tundra","ru":"Тундра","en":"Tundra"},{"uz":"Dasht","ru":"Степь","en":"Steppe"},{"uz":"Cho‘l","ru":"Пустыня","en":"Desert"},{"uz":"Nam ekvatorial o‘rmonlar","ru":"Влажные экваториальные леса","en":"Tropical rainforest"}]'::jsonb, 3, '{"uz":"Nam ekvatorial o‘rmonlar ekvator yaqinida joylashgan. Masalan, Amazonka o‘rmonlari dunyodagi eng katta tropik o‘rmon hisoblanadi.","ru":"Влажные экваториальные леса растут вблизи экватора. Например, леса Амазонии — крупнейший тропический лес в мире.","en":"Tropical rainforests grow near the Equator. The Amazon rainforest, for example, is the largest tropical rainforest in the world."}'::jsonb, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
('8111a53b-b474-59ff-aa4a-1d15d4caa44e', 'geography-11', 'GEOGRAPHY', 3, 5, 9, '{"uz":"O‘zbekiston tog‘lari","ru":"Горы Узбекистана","en":"Mountains of Uzbekistan"}'::jsonb, '{"uz":"O‘zbekistonning eng baland nuqtasi — Hazrati Sulton cho‘qqisi qaysi tog‘ tizmasida joylashgan?","ru":"В каком горном хребте находится высшая точка Узбекистана — пик Хазрет-Султан?","en":"In which mountain range is Khazret Sultan, the highest point of Uzbekistan, located?"}'::jsonb, '[{"uz":"Hisor tizmasi","ru":"Гиссарский хребет","en":"Gissar Range"},{"uz":"Chotqol tizmasi","ru":"Чаткальский хребет","en":"Chatkal Range"},{"uz":"Nurota tog‘lari","ru":"Нуратинские горы","en":"Nuratau Mountains"},{"uz":"Qurama tizmasi","ru":"Кураминский хребет","en":"Kurama Range"}]'::jsonb, 0, '{"uz":"Hazrati Sulton cho‘qqisi O‘zbekiston janubidagi Hisor tizmasida joylashgan va uning balandligi 4643 metr.","ru":"Пик Хазрет-Султан находится в Гиссарском хребте на юге Узбекистана, его высота — 4643 метра.","en":"Khazret Sultan is in the Gissar Range in the south of Uzbekistan, and it is 4,643 metres high."}'::jsonb, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
('b3eaa734-0e99-5f6a-bad1-32ef40005134', 'geography-12', 'GEOGRAPHY', 3, 5, 9, '{"uz":"Cho‘llar","ru":"Пустыни","en":"Deserts"}'::jsonb, '{"uz":"Amudaryo va Sirdaryo oralig‘ida joylashgan katta cho‘l qaysi?","ru":"Какая большая пустыня расположена между Амударьёй и Сырдарьёй?","en":"Which large desert lies between the Amu Darya and the Syr Darya?"}'::jsonb, '[{"uz":"Qoraqum","ru":"Каракумы","en":"Karakum"},{"uz":"Qizilqum","ru":"Кызылкум","en":"Kyzylkum"},{"uz":"Sahroi Kabir","ru":"Сахара","en":"Sahara"},{"uz":"Gobi","ru":"Гоби","en":"Gobi"}]'::jsonb, 1, '{"uz":"Qizilqum («qizil qum») Amudaryo va Sirdaryo oralig‘ida joylashgan. Qoraqum esa Amudaryoning janubi-g‘arbida, Turkmanistonda.","ru":"Кызылкум («красные пески») лежит между Амударьёй и Сырдарьёй. А Каракумы находятся к юго-западу от Амударьи, в Туркменистане.","en":"The Kyzylkum (“red sands”) lies between the Amu Darya and the Syr Darya. The Karakum is south-west of the Amu Darya, in Turkmenistan."}'::jsonb, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
('c665bfc5-2c4d-5f33-864c-cb5ecab063b3', 'geography-13', 'GEOGRAPHY', 3, 5, 9, '{"uz":"Yerning harakati","ru":"Движение Земли","en":"Earth''s motion"}'::jsonb, '{"uz":"Yerning o‘z o‘qi atrofida aylanishi natijasida nima sodir bo‘ladi?","ru":"Что происходит в результате вращения Земли вокруг своей оси?","en":"What happens as a result of the Earth spinning on its axis?"}'::jsonb, '[{"uz":"Yil fasllari almashadi","ru":"Сменяются времена года","en":"The seasons change"},{"uz":"Oy fazalari o‘zgaradi","ru":"Меняются фазы Луны","en":"The Moon''s phases change"},{"uz":"Kecha va kunduz almashadi","ru":"Сменяются день и ночь","en":"Day and night alternate"},{"uz":"Zilzilalar sodir bo‘ladi","ru":"Происходят землетрясения","en":"Earthquakes happen"}]'::jsonb, 2, '{"uz":"Yer o‘z o‘qi atrofida taxminan 24 soatda bir marta aylanadi, shu sababli kecha va kunduz almashadi. Fasllar esa Yer o‘qining og‘maligi va Quyosh atrofida aylanishi bilan bog‘liq.","ru":"Земля делает оборот вокруг своей оси примерно за 24 часа, поэтому день сменяет ночь. А времена года связаны с наклоном земной оси и движением вокруг Солнца.","en":"The Earth turns once on its axis about every 24 hours, which gives us day and night. The seasons come from the tilt of the Earth''s axis as it travels around the Sun."}'::jsonb, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
('56e7124f-c69f-5cc0-8347-df0392e48af9', 'geography-14', 'GEOGRAPHY', 3, 5, 9, '{"uz":"Xarita masshtabi","ru":"Масштаб карты","en":"Map scale"}'::jsonb, '{"uz":"Masshtabi 1:100 000 bo‘lgan xaritadagi 1 sm joyda qancha masofaga teng?","ru":"Какому расстоянию на местности соответствует 1 см на карте масштаба 1:100 000?","en":"On a map with a scale of 1:100,000, how much real distance does 1 cm represent?"}'::jsonb, '[{"uz":"100 m","ru":"100 м","en":"100 m"},{"uz":"1 km","ru":"1 км","en":"1 km"},{"uz":"10 km","ru":"10 км","en":"10 km"},{"uz":"100 km","ru":"100 км","en":"100 km"}]'::jsonb, 1, '{"uz":"1:100 000 masshtab xaritadagi 1 sm joyda 100 000 sm ga teng ekanini bildiradi. 100 000 sm = 1000 m = 1 km.","ru":"Масштаб 1:100 000 означает, что 1 см на карте равен 100 000 см на местности, а 100 000 см = 1000 м = 1 км.","en":"A scale of 1:100,000 means 1 cm on the map equals 100,000 cm on the ground, and 100,000 cm = 1,000 m = 1 km."}'::jsonb, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
('a2b0e6b9-942c-5818-8877-3bda08772dcc', 'geography-15', 'GEOGRAPHY', 3, 5, 9, '{"uz":"Yarimsharlar","ru":"Полушария","en":"Hemispheres"}'::jsonb, '{"uz":"O‘zbekiston Yer sharining qaysi yarimsharlarida joylashgan?","ru":"В каких полушариях Земли расположен Узбекистан?","en":"In which hemispheres of the Earth is Uzbekistan located?"}'::jsonb, '[{"uz":"Janubiy va Sharqiy","ru":"Южное и Восточное","en":"Southern and Eastern"},{"uz":"Shimoliy va G‘arbiy","ru":"Северное и Западное","en":"Northern and Western"},{"uz":"Janubiy va G‘arbiy","ru":"Южное и Западное","en":"Southern and Western"},{"uz":"Shimoliy va Sharqiy","ru":"Северное и Восточное","en":"Northern and Eastern"}]'::jsonb, 3, '{"uz":"O‘zbekiston ekvatordan shimolda va Grinvich meridianidan sharqda joylashgan, ya’ni Shimoliy va Sharqiy yarimsharlarda.","ru":"Узбекистан лежит к северу от экватора и к востоку от Гринвичского меридиана — значит, в Северном и Восточном полушариях.","en":"Uzbekistan lies north of the Equator and east of the Greenwich meridian, so it is in the Northern and Eastern hemispheres."}'::jsonb, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
('1ed73eaf-b65f-5470-9c11-16905b1e404b', 'history-01', 'HISTORY', 1, 5, 9, '{"uz":"Mustaqillik","ru":"Независимость","en":"Independence"}'::jsonb, '{"uz":"O‘zbekiston qaysi yilda mustaqillikka erishgan?","ru":"В каком году Узбекистан обрёл независимость?","en":"In which year did Uzbekistan gain independence?"}'::jsonb, '[{"uz":"1989-yil","ru":"1989 год","en":"1989"},{"uz":"1990-yil","ru":"1990 год","en":"1990"},{"uz":"1991-yil","ru":"1991 год","en":"1991"},{"uz":"1992-yil","ru":"1992 год","en":"1992"}]'::jsonb, 2, '{"uz":"O‘zbekiston 1991-yil 31-avgustda mustaqil deb e’lon qilindi. Mustaqillik kuni esa har yili 1-sentabrda nishonlanadi.","ru":"Независимость Узбекистана была провозглашена 31 августа 1991 года, а День независимости отмечается каждый год 1 сентября.","en":"Uzbekistan declared its independence on 31 August 1991, and Independence Day is celebrated every year on 1 September."}'::jsonb, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
('03ec3153-d3c6-5409-90ae-11d5889e9375', 'history-02', 'HISTORY', 1, 5, 9, '{"uz":"Amir Temur davri","ru":"Эпоха Амира Темура","en":"Timurid era"}'::jsonb, '{"uz":"Amir Temur qaysi shaharni o‘z davlatining poytaxtiga aylantirgan?","ru":"Какой город Амир Темур сделал столицей своего государства?","en":"Which city did Amir Timur make the capital of his state?"}'::jsonb, '[{"uz":"Buxoro","ru":"Бухара","en":"Bukhara"},{"uz":"Samarqand","ru":"Самарканд","en":"Samarkand"},{"uz":"Xiva","ru":"Хива","en":"Khiva"},{"uz":"Termiz","ru":"Термез","en":"Termez"}]'::jsonb, 1, '{"uz":"Amir Temur Samarqandni poytaxt qilib, uni Bibixonim masjidi kabi ulug‘vor binolar bilan bezagan.","ru":"Амир Темур сделал столицей Самарканд и украсил его величественными зданиями, например мечетью Биби-Ханым.","en":"Amir Timur made Samarkand his capital and adorned it with grand buildings such as the Bibi-Khanym Mosque."}'::jsonb, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
('0c6959f5-2eeb-5f38-afaf-d619b3db2e62', 'history-03', 'HISTORY', 1, 5, 9, '{"uz":"Buyuk ipak yo‘li","ru":"Великий шёлковый путь","en":"Great Silk Road"}'::jsonb, '{"uz":"Buyuk ipak yo‘li qaysi hududlarni bir-biri bilan bog‘lagan?","ru":"Какие регионы соединял Великий шёлковый путь?","en":"Which regions did the Great Silk Road connect?"}'::jsonb, '[{"uz":"Xitoy va O‘rta yer dengizi bo‘yi","ru":"Китай и Средиземноморье","en":"China and the Mediterranean"},{"uz":"Avstraliya va Afrika","ru":"Австралия и Африка","en":"Australia and Africa"},{"uz":"Amerika va Yevropa","ru":"Америка и Европа","en":"America and Europe"},{"uz":"Hindiston va Antarktida","ru":"Индия и Антарктида","en":"India and Antarctica"}]'::jsonb, 0, '{"uz":"Bu savdo yo‘li Xitoydan O‘rta Osiyo orqali O‘rta yer dengizigacha cho‘zilgan. Samarqand va Buxoro unda muhim savdo markazlari bo‘lgan.","ru":"Этот торговый путь тянулся из Китая через Центральную Азию до Средиземного моря. Самарканд и Бухара были на нём важными торговыми центрами.","en":"This trade route stretched from China through Central Asia to the Mediterranean Sea. Samarkand and Bukhara were important trading centres along it."}'::jsonb, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
('2e617a66-75d6-51c0-8f3c-335e4b78e257', 'history-04', 'HISTORY', 1, 5, 9, '{"uz":"Qadimgi sivilizatsiyalar","ru":"Древние цивилизации","en":"Ancient civilisations"}'::jsonb, '{"uz":"Mashhur Giza piramidalari qaysi qadimgi davlatda qurilgan?","ru":"В каком древнем государстве построены знаменитые пирамиды Гизы?","en":"In which ancient civilisation were the famous Pyramids of Giza built?"}'::jsonb, '[{"uz":"Qadimgi Rim","ru":"Древний Рим","en":"Ancient Rome"},{"uz":"Qadimgi Xitoy","ru":"Древний Китай","en":"Ancient China"},{"uz":"Qadimgi Yunoniston","ru":"Древняя Греция","en":"Ancient Greece"},{"uz":"Qadimgi Misr","ru":"Древний Египет","en":"Ancient Egypt"}]'::jsonb, 3, '{"uz":"Giza piramidalari Qadimgi Misrda fir’avnlar uchun maqbara sifatida qurilgan. Ular 4500 yildan ham ko‘proq vaqt oldin barpo etilgan.","ru":"Пирамиды Гизы построили в Древнем Египте как гробницы фараонов. Им более 4500 лет.","en":"The Pyramids of Giza were built in Ancient Egypt as tombs for the pharaohs. They are more than 4,500 years old."}'::jsonb, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
('66b2b56b-6422-5af4-866d-e0c326a3b3dd', 'history-05', 'HISTORY', 1, 5, 9, '{"uz":"Mirzo Ulug‘bek","ru":"Мирзо Улугбек","en":"Ulugh Beg"}'::jsonb, '{"uz":"Mirzo Ulug‘bek qaysi fan sohasidagi ishlari bilan dunyoga mashhur bo‘lgan?","ru":"Благодаря трудам в какой науке Мирзо Улугбек прославился на весь мир?","en":"Ulugh Beg became world-famous for his work in which science?"}'::jsonb, '[{"uz":"Geologiya","ru":"Геология","en":"Geology"},{"uz":"Kimyo","ru":"Химия","en":"Chemistry"},{"uz":"Astronomiya","ru":"Астрономия","en":"Astronomy"},{"uz":"Botanika","ru":"Ботаника","en":"Botany"}]'::jsonb, 2, '{"uz":"Ulug‘bek Samarqandda rasadxona qurdirgan va 1000 dan ortiq yulduzning o‘rni ko‘rsatilgan mashhur yulduzlar jadvalini tuzgan.","ru":"Улугбек построил в Самарканде обсерваторию и составил знаменитый звёздный каталог с положением более 1000 звёзд.","en":"Ulugh Beg built an observatory in Samarkand and compiled a famous star catalogue listing the positions of more than 1,000 stars."}'::jsonb, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
('da2a85df-1fd4-5091-850a-b16db8983b05', 'history-06', 'HISTORY', 2, 5, 9, '{"uz":"Al-Xorazmiy","ru":"Аль-Хорезми","en":"Al-Khwarizmi"}'::jsonb, '{"uz":"«Algoritm» so‘zi qaysi olimning nomidan kelib chiqqan?","ru":"От имени какого учёного произошло слово «алгоритм»?","en":"The word “algorithm” comes from the name of which scholar?"}'::jsonb, '[{"uz":"Al-Xorazmiy","ru":"Аль-Хорезми","en":"Al-Khwarizmi"},{"uz":"Ibn Sino","ru":"Ибн Сина","en":"Avicenna (Ibn Sina)"},{"uz":"Abu Rayhon Beruniy","ru":"Абу Рейхан Беруни","en":"Al-Biruni"},{"uz":"Ahmad al-Farg‘oniy","ru":"Ахмад аль-Фергани","en":"Al-Farghani"}]'::jsonb, 0, '{"uz":"Lotin tilidagi tarjimalarda al-Xorazmiyning nomi «Algoritmi» deb yozilgan, «algoritm» so‘zi shundan kelib chiqqan. «Algebra» so‘zi ham uning kitobi nomidan olingan.","ru":"В латинских переводах имя аль-Хорезми писали как «Algoritmi» — отсюда слово «алгоритм». Из названия его книги произошло и слово «алгебра».","en":"In Latin translations al-Khwarizmi''s name was written as “Algoritmi”, which gave us the word “algorithm”. The word “algebra” comes from the title of his book."}'::jsonb, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
('1f6bed13-6c88-5613-8ce4-007ed1d72d3c', 'history-07', 'HISTORY', 2, 5, 9, '{"uz":"Ibn Sino","ru":"Ибн Сина","en":"Avicenna (Ibn Sina)"}'::jsonb, '{"uz":"Ibn Sinoning tibbiyotga oid eng mashhur asari qaysi?","ru":"Какое медицинское произведение Ибн Сины самое известное?","en":"Which is the most famous medical work by Avicenna (Ibn Sina)?"}'::jsonb, '[{"uz":"«Boburnoma»","ru":"«Бабур-наме»","en":"Baburnama"},{"uz":"«Tib qonunlari»","ru":"«Канон врачебной науки»","en":"The Canon of Medicine"},{"uz":"«Qutadg‘u bilig»","ru":"«Кутадгу билиг»","en":"Kutadgu Bilig"},{"uz":"«Devonu lug‘otit turk»","ru":"«Диван лугат ат-тюрк»","en":"Diwan Lughat al-Turk"}]'::jsonb, 1, '{"uz":"«Tib qonunlari» besh kitobdan iborat bo‘lib, Yevropada bir necha asr davomida tibbiyot darsligi sifatida o‘qitilgan.","ru":"«Канон врачебной науки» состоит из пяти книг и несколько веков служил в Европе учебником медицины.","en":"The Canon of Medicine consists of five books and was used as a medical textbook in Europe for several centuries."}'::jsonb, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
('84e6e837-15a4-5723-92bd-63def94b2f89', 'history-08', 'HISTORY', 2, 5, 9, '{"uz":"Somoniylar davlati","ru":"Государство Саманидов","en":"Samanid state"}'::jsonb, '{"uz":"Ismoil Somoniy davrida Somoniylar davlatining poytaxti qaysi shahar bo‘lgan?","ru":"Какой город был столицей государства Саманидов при Исмаиле Самани?","en":"Which city was the capital of the Samanid state under Ismail Samani?"}'::jsonb, '[{"uz":"Xiva","ru":"Хива","en":"Khiva"},{"uz":"Qo‘qon","ru":"Коканд","en":"Kokand"},{"uz":"Toshkent","ru":"Ташкент","en":"Tashkent"},{"uz":"Buxoro","ru":"Бухара","en":"Bukhara"}]'::jsonb, 3, '{"uz":"Ismoil Somoniy Buxoroni poytaxt qildi va shahar ilm-fan va madaniyat markaziga aylandi. U yerda hozir ham Somoniylar maqbarasi saqlanib qolgan.","ru":"Исмаил Самани сделал столицей Бухару, и город стал центром науки и культуры. Там до сих пор стоит мавзолей Саманидов.","en":"Ismail Samani made Bukhara his capital, and it became a centre of learning and culture. The Samanid Mausoleum still stands there today."}'::jsonb, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
('9d5c6161-33cb-5042-997d-b9fe81693f96', 'history-09', 'HISTORY', 2, 5, 9, '{"uz":"Qadimgi Yunoniston","ru":"Древняя Греция","en":"Ancient Greece"}'::jsonb, '{"uz":"Qadimgi Olimpiya o‘yinlari qaysi mamlakatda o‘tkazila boshlagan?","ru":"В какой стране начали проводить древние Олимпийские игры?","en":"In which country did the ancient Olympic Games begin?"}'::jsonb, '[{"uz":"Qadimgi Rim","ru":"Древний Рим","en":"Ancient Rome"},{"uz":"Qadimgi Misr","ru":"Древний Египет","en":"Ancient Egypt"},{"uz":"Qadimgi Yunoniston","ru":"Древняя Греция","en":"Ancient Greece"},{"uz":"Qadimgi Hindiston","ru":"Древняя Индия","en":"Ancient India"}]'::jsonb, 2, '{"uz":"Ma’lum bo‘lgan ilk Olimpiya o‘yinlari miloddan avvalgi 776-yilda Qadimgi Yunonistonning Olimpiya degan joyida o‘tkazilgan. Ular Zevs sharafiga bag‘ishlangan.","ru":"Первые известные Олимпийские игры прошли в 776 году до н. э. в Олимпии, в Древней Греции. Их посвящали Зевсу.","en":"The first recorded Olympic Games took place in 776 BC at Olympia in Ancient Greece. They were held in honour of Zeus."}'::jsonb, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
('1887bd25-8bff-5001-a21c-dce29fd895ab', 'history-10', 'HISTORY', 2, 5, 9, '{"uz":"Geografik kashfiyotlar","ru":"Великие открытия","en":"Age of Discovery"}'::jsonb, '{"uz":"Xristofor Kolumb ekspeditsiyasi Amerika qirg‘oqlariga qaysi yilda yetib borgan?","ru":"В каком году экспедиция Христофора Колумба достигла берегов Америки?","en":"In which year did Christopher Columbus''s expedition reach the Americas?"}'::jsonb, '[{"uz":"1453-yil","ru":"1453 год","en":"1453"},{"uz":"1492-yil","ru":"1492 год","en":"1492"},{"uz":"1517-yil","ru":"1517 год","en":"1517"},{"uz":"1610-yil","ru":"1610 год","en":"1610"}]'::jsonb, 1, '{"uz":"Kolumb Hindistonga g‘arb tomondan yangi yo‘l izlab, 1492-yilda Atlantika okeanini kesib o‘tdi va Amerika yaqinidagi orollarga yetib bordi.","ru":"Колумб искал западный путь в Индию и в 1492 году, переплыв Атлантический океан, достиг островов у берегов Америки.","en":"Looking for a western sea route to India, Columbus crossed the Atlantic Ocean in 1492 and reached islands off the coast of the Americas."}'::jsonb, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
('dcdb1797-db77-54e0-a3a6-c497233256d8', 'history-11', 'HISTORY', 3, 5, 9, '{"uz":"Abu Rayhon Beruniy","ru":"Абу Рейхан Беруни","en":"Al-Biruni"}'::jsonb, '{"uz":"Abu Rayhon Beruniy tog‘ning balandligini va undan ufqqa qarash burchagini o‘lchab, nimani hisoblab chiqqan?","ru":"Что вычислил Абу Рейхан Беруни, измерив высоту горы и угол, под которым с неё виден горизонт?","en":"What did Al-Biruni calculate by measuring a mountain''s height and the angle to the horizon from its top?"}'::jsonb, '[{"uz":"Yerning radiusini","ru":"Радиус Земли","en":"The radius of the Earth"},{"uz":"Oygacha bo‘lgan masofani","ru":"Расстояние до Луны","en":"The distance to the Moon"},{"uz":"Quyoshning haroratini","ru":"Температуру Солнца","en":"The temperature of the Sun"},{"uz":"Okeanning chuqurligini","ru":"Глубину океана","en":"The depth of the ocean"}]'::jsonb, 0, '{"uz":"Beruniy geometriya yordamida Yerning radiusini hisoblagan va uning natijasi hozirgi qiymatga juda yaqin chiqqan.","ru":"С помощью геометрии Беруни вычислил радиус Земли, и его результат оказался очень близок к современному значению.","en":"Using geometry, Al-Biruni calculated the Earth''s radius, and his result was very close to the value known today."}'::jsonb, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
('d5636e6a-207a-5ecf-ad7c-a81d666a835c', 'history-12', 'HISTORY', 3, 5, 9, '{"uz":"Temuriylar","ru":"Тимуриды","en":"Timurids"}'::jsonb, '{"uz":"Zahiriddin Muhammad Bobur Hindistonda yangi davlatga qaysi yilda asos solgan?","ru":"В каком году Захириддин Мухаммад Бабур основал новое государство в Индии?","en":"In which year did Zahiriddin Muhammad Babur found a new state in India?"}'::jsonb, '[{"uz":"1494-yil","ru":"1494 год","en":"1494"},{"uz":"1405-yil","ru":"1405 год","en":"1405"},{"uz":"1600-yil","ru":"1600 год","en":"1600"},{"uz":"1526-yil","ru":"1526 год","en":"1526"}]'::jsonb, 3, '{"uz":"1526-yilda Panipat jangidagi g‘alabadan so‘ng Bobur Hindistonda Boburiylar davlatiga asos solgan. U «Boburnoma» asarining muallifi hamdir.","ru":"В 1526 году, после победы в битве при Панипате, Бабур основал в Индии державу Бабуридов (Великих Моголов). Он также автор «Бабур-наме».","en":"In 1526, after winning the Battle of Panipat, Babur founded the Mughal Empire in India. He also wrote the Baburnama."}'::jsonb, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
('32969d35-7304-5a93-9fb5-0b9db26c4547', 'history-13', 'HISTORY', 3, 5, 9, '{"uz":"Qadimgi Mesopotamiya","ru":"Древняя Месопотамия","en":"Ancient Mesopotamia"}'::jsonb, '{"uz":"Qadimgi Mesopotamiya (Ikki daryo oralig‘i) qaysi daryolar orasida joylashgan?","ru":"Между какими реками располагалась Древняя Месопотамия (Двуречье)?","en":"Between which rivers was ancient Mesopotamia located?"}'::jsonb, '[{"uz":"Nil va Kongo","ru":"Нил и Конго","en":"Nile and Congo"},{"uz":"Dajla va Frot","ru":"Тигр и Евфрат","en":"Tigris and Euphrates"},{"uz":"Amudaryo va Sirdaryo","ru":"Амударья и Сырдарья","en":"Amu Darya and Syr Darya"},{"uz":"Gang va Hind","ru":"Ганг и Инд","en":"Ganges and Indus"}]'::jsonb, 1, '{"uz":"Mesopotamiya Dajla va Frot daryolari oralig‘ida joylashgan. Bu yerda yashagan shumerlar dunyodagi ilk yozuvlardan biri — mixxatni yaratgan.","ru":"Месопотамия лежала между Тигром и Евфратом. Жившие там шумеры создали одну из первых систем письма — клинопись.","en":"Mesopotamia lay between the Tigris and Euphrates rivers. The Sumerians who lived there created one of the earliest writing systems, cuneiform."}'::jsonb, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
('cc86df7e-7b93-51cb-bac9-5bc8b1194165', 'history-14', 'HISTORY', 3, 5, 9, '{"uz":"Qadimgi Sug‘d","ru":"Древний Согд","en":"Ancient Sogdiana"}'::jsonb, '{"uz":"Qadimgi yunon mualliflari Samarqandni qanday nom bilan atashgan?","ru":"Как называли Самарканд древнегреческие авторы?","en":"What name did ancient Greek writers use for Samarkand?"}'::jsonb, '[{"uz":"Marakanda","ru":"Мараканда","en":"Maracanda"},{"uz":"Aleksandriya","ru":"Александрия","en":"Alexandria"},{"uz":"Karfagen","ru":"Карфаген","en":"Carthage"},{"uz":"Vavilon","ru":"Вавилон","en":"Babylon"}]'::jsonb, 0, '{"uz":"Aleksandr Makedonskiy yurishlari haqida yozgan yunon mualliflari Samarqandni Marakanda deb atashgan. U Sug‘diyonaning bosh shahri bo‘lgan.","ru":"Греческие авторы, описывавшие походы Александра Македонского, называли Самарканд Маракандой. Это был главный город Согдианы.","en":"Greek writers describing the campaigns of Alexander the Great called Samarkand Maracanda. It was the main city of Sogdiana."}'::jsonb, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
('5f510a29-fb41-5fdd-96fe-b7535bfce6d2', 'history-15', 'HISTORY', 3, 5, 9, '{"uz":"Amir Temur davri","ru":"Эпоха Амира Темура","en":"Timurid era"}'::jsonb, '{"uz":"Amir Temur qaysi yilda tug‘ilgan?","ru":"В каком году родился Амир Темур?","en":"In which year was Amir Timur born?"}'::jsonb, '[{"uz":"1370-yil","ru":"1370 год","en":"1370"},{"uz":"1405-yil","ru":"1405 год","en":"1405"},{"uz":"1220-yil","ru":"1220 год","en":"1220"},{"uz":"1336-yil","ru":"1336 год","en":"1336"}]'::jsonb, 3, '{"uz":"Amir Temur 1336-yilda Kesh (hozirgi Shahrisabz) yaqinida tug‘ilgan. U 1370-yilda hokimiyatga kelgan va 1405-yilda vafot etgan.","ru":"Амир Темур родился в 1336 году близ Кеша (ныне Шахрисабз). В 1370 году он пришёл к власти, а умер в 1405 году.","en":"Amir Timur was born in 1336 near Kesh (today''s Shahrisabz). He came to power in 1370 and died in 1405."}'::jsonb, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
('b5564500-05cf-59fb-88b1-fb65be2598be', 'informatics-01', 'INFORMATICS', 1, 5, 9, '{"uz":"Axborot birliklari","ru":"Единицы информации","en":"Units of information"}'::jsonb, '{"uz":"1 baytda necha bit bor?","ru":"Сколько бит в 1 байте?","en":"How many bits are there in 1 byte?"}'::jsonb, '[{"uz":"2","ru":"2","en":"2"},{"uz":"8","ru":"8","en":"8"},{"uz":"10","ru":"10","en":"10"},{"uz":"16","ru":"16","en":"16"}]'::jsonb, 1, '{"uz":"1 bayt = 8 bit. Bit — axborotning eng kichik birligi, u 0 yoki 1 qiymatni oladi.","ru":"1 байт = 8 бит. Бит — наименьшая единица информации, он принимает значение 0 или 1.","en":"1 byte = 8 bits. A bit is the smallest unit of information and can be either 0 or 1."}'::jsonb, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
('613efd7b-0640-5267-ab44-ef660c345c41', 'informatics-02', 'INFORMATICS', 1, 5, 9, '{"uz":"Kompyuter qurilmalari","ru":"Устройства компьютера","en":"Computer devices"}'::jsonb, '{"uz":"Quyidagilardan qaysi biri ma’lumot kiritish qurilmasi?","ru":"Какое из этих устройств является устройством ввода?","en":"Which of these is an input device?"}'::jsonb, '[{"uz":"Monitor","ru":"Монитор","en":"Monitor"},{"uz":"Printer","ru":"Принтер","en":"Printer"},{"uz":"Klaviatura","ru":"Клавиатура","en":"Keyboard"},{"uz":"Karnaylar","ru":"Колонки","en":"Speakers"}]'::jsonb, 2, '{"uz":"Klaviatura yordamida kompyuterga matn va buyruqlar kiritiladi. Monitor, printer va karnaylar esa ma’lumotni chiqaradi.","ru":"С клавиатуры в компьютер вводят текст и команды. Монитор, принтер и колонки, наоборот, выводят информацию.","en":"A keyboard is used to type text and commands into a computer. A monitor, printer and speakers are output devices."}'::jsonb, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
('0aad54c2-f2a5-5649-9920-ad9a717d20ff', 'informatics-03', 'INFORMATICS', 1, 5, 9, '{"uz":"Parol xavfsizligi","ru":"Надёжные пароли","en":"Password safety"}'::jsonb, '{"uz":"Quyidagi parollardan qaysi biri eng ishonchli?","ru":"Какой из этих паролей самый надёжный?","en":"Which of these passwords is the strongest?"}'::jsonb, '[{"uz":"123456","ru":"123456","en":"123456"},{"uz":"qwerty","ru":"qwerty","en":"qwerty"},{"uz":"ali2010","ru":"ali2010","en":"ali2010"},{"uz":"Kq7#mP2!xL","ru":"Kq7#mP2!xL","en":"Kq7#mP2!xL"}]'::jsonb, 3, '{"uz":"Ishonchli parol uzun bo‘ladi va katta-kichik harflar, raqamlar hamda belgilardan iborat bo‘ladi. Oddiy raqamlar, ism va tug‘ilgan yilni topish oson.","ru":"Надёжный пароль длинный и содержит заглавные и строчные буквы, цифры и символы. Простые цифры, имя и год рождения легко подобрать.","en":"A strong password is long and mixes upper- and lower-case letters, numbers and symbols. Simple digits, names and birth years are easy to guess."}'::jsonb, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
('c61a15ec-516f-59bd-97a9-01c6974a1fc1', 'informatics-04', 'INFORMATICS', 1, 5, 9, '{"uz":"Fayllar","ru":"Файлы","en":"Files"}'::jsonb, '{"uz":"Qaysi kengaytma odatda rasm faylini bildiradi?","ru":"Какое расширение обычно имеет файл с изображением?","en":"Which file extension usually means the file is a picture?"}'::jsonb, '[{"uz":".mp3","ru":".mp3","en":".mp3"},{"uz":".docx","ru":".docx","en":".docx"},{"uz":".jpg","ru":".jpg","en":".jpg"},{"uz":".exe","ru":".exe","en":".exe"}]'::jsonb, 2, '{"uz":".jpg — rasm (fotosurat) fayli. .mp3 — audio, .docx — matnli hujjat, .exe esa dastur fayli.","ru":".jpg — файл изображения (фотографии). .mp3 — аудио, .docx — текстовый документ, .exe — программа.","en":".jpg is an image (photo) file. .mp3 is audio, .docx is a text document and .exe is a program."}'::jsonb, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
('696e818d-2bab-5517-b784-a4e06b19f9b1', 'informatics-05', 'INFORMATICS', 1, 5, 9, '{"uz":"Internetda xavfsizlik","ru":"Безопасность в интернете","en":"Online safety"}'::jsonb, '{"uz":"Internetda notanish odam sizdan uy manzilingizni so‘rayapti. Nima qilish kerak?","ru":"Незнакомый человек в интернете просит назвать домашний адрес. Как правильно поступить?","en":"A stranger online asks for your home address. What should you do?"}'::jsonb, '[{"uz":"Manzilni yozib yuborish","ru":"Отправить адрес","en":"Send the address"},{"uz":"Rad etib, kattalarga aytish","ru":"Отказать и рассказать взрослым","en":"Say no and tell an adult"},{"uz":"Faqat ko‘cha nomini aytish","ru":"Назвать только улицу","en":"Give only the street name"},{"uz":"Uyning rasmini yuborish","ru":"Отправить фото дома","en":"Send a photo of the house"}]'::jsonb, 1, '{"uz":"Shaxsiy ma’lumotlarni notanish odamlarga hech qachon bermang. Bunday holatda ota-onangiz yoki ustozingizga xabar bering.","ru":"Личные данные нельзя сообщать незнакомцам. В такой ситуации нужно рассказать родителям или учителю.","en":"Never share personal information with strangers. In a situation like this, tell your parents or a teacher."}'::jsonb, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
('ea2dd7ac-3c80-5e91-8cee-25c993ab9be4', 'informatics-06', 'INFORMATICS', 2, 5, 9, '{"uz":"Ikkilik sanoq tizimi","ru":"Двоичная система","en":"Binary numbers"}'::jsonb, '{"uz":"Ikkilik sanoq tizimidagi 1011₂ sonini o‘nlik sanoq tizimiga o‘tkazing.","ru":"Переведите двоичное число 1011₂ в десятичную систему счисления.","en":"Convert the binary number 1011₂ to decimal."}'::jsonb, '[{"uz":"11","ru":"11","en":"11"},{"uz":"13","ru":"13","en":"13"},{"uz":"1011","ru":"1011","en":"1011"},{"uz":"9","ru":"9","en":"9"}]'::jsonb, 0, '{"uz":"Har bir xona 2 ning darajasini bildiradi: 1 · 8 + 0 · 4 + 1 · 2 + 1 · 1 = 11.","ru":"Каждый разряд — степень двойки: 1 · 8 + 0 · 4 + 1 · 2 + 1 · 1 = 11.","en":"Each digit stands for a power of 2: 1 × 8 + 0 × 4 + 1 × 2 + 1 × 1 = 11."}'::jsonb, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
('f17a317b-a057-5f49-814d-d8de7bc364e7', 'informatics-07', 'INFORMATICS', 2, 5, 9, '{"uz":"Mantiq","ru":"Логика","en":"Logic"}'::jsonb, '{"uz":"Quyidagi mantiqiy ifodalardan qaysi biri rost?","ru":"Какое из этих логических выражений истинно?","en":"Which of these logical expressions is true?"}'::jsonb, '[{"uz":"(5 > 3) VA (2 > 4)","ru":"(5 > 3) И (2 > 4)","en":"(5 > 3) AND (2 > 4)"},{"uz":"(5 > 3) YOKI (2 > 4)","ru":"(5 > 3) ИЛИ (2 > 4)","en":"(5 > 3) OR (2 > 4)"},{"uz":"EMAS (5 > 3)","ru":"НЕ (5 > 3)","en":"NOT (5 > 3)"},{"uz":"(2 > 4) VA (1 > 0)","ru":"(2 > 4) И (1 > 0)","en":"(2 > 4) AND (1 > 0)"}]'::jsonb, 1, '{"uz":"YOKI amali kamida bitta qism rost bo‘lsa, rost bo‘ladi: 5 > 3 — rost. VA uchun ikkala qism ham rost bo‘lishi kerak, 2 > 4 esa yolg‘on.","ru":"ИЛИ истинно, если истинна хотя бы одна часть: 5 > 3 — истина. Для И нужны две истинные части, а 2 > 4 — ложь.","en":"OR is true if at least one part is true, and 5 > 3 is true. AND needs both parts to be true, but 2 > 4 is false."}'::jsonb, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
('748ce62f-a042-54dc-a1d7-69789e34c97d', 'informatics-08', 'INFORMATICS', 2, 5, 9, '{"uz":"Fayllar va papkalar","ru":"Файлы и папки","en":"Files and folders"}'::jsonb, '{"uz":"Fayl manzili: D:\\Maktab\\Matematika\\uy_ishi.docx. uy_ishi.docx fayli qaysi papkada joylashgan?","ru":"Путь к файлу: D:\\Школа\\Математика\\задание.docx. В какой папке находится файл задание.docx?","en":"The file path is D:\\School\\Maths\\homework.docx. Which folder is homework.docx in?"}'::jsonb, '[{"uz":"D:","ru":"D:","en":"D:"},{"uz":"Maktab","ru":"Школа","en":"School"},{"uz":"Matematika","ru":"Математика","en":"Maths"},{"uz":"docx","ru":"docx","en":"docx"}]'::jsonb, 2, '{"uz":"Fayl yo‘lda o‘z nomidan oldin yozilgan papkada turadi — bu Matematika. U Maktab papkasi ichida, Maktab esa D: diskida.","ru":"Файл лежит в папке, указанной прямо перед его именем, — это Математика. Она находится в папке Школа на диске D:.","en":"A file sits in the folder named just before it in the path: Maths. That folder is inside School, on drive D:."}'::jsonb, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
('96884b96-35a5-556e-81f7-775f2c476819', 'informatics-09', 'INFORMATICS', 2, 5, 9, '{"uz":"Algoritmlar","ru":"Алгоритмы","en":"Algorithms"}'::jsonb, '{"uz":"Algoritm: x := 3; x := x * 2; x := x + 4; x := x * 2. Algoritm bajarilgandan so‘ng x nechaga teng bo‘ladi?","ru":"Алгоритм: x := 3; x := x * 2; x := x + 4; x := x * 2. Чему будет равно x после выполнения?","en":"Algorithm: x := 3; x := x * 2; x := x + 4; x := x * 2. What is x after it runs?"}'::jsonb, '[{"uz":"20","ru":"20","en":"20"},{"uz":"14","ru":"14","en":"14"},{"uz":"16","ru":"16","en":"16"},{"uz":"26","ru":"26","en":"26"}]'::jsonb, 0, '{"uz":"Buyruqlarni ketma-ket bajaramiz: 3 · 2 = 6, keyin 6 + 4 = 10, oxirida 10 · 2 = 20.","ru":"Выполняем команды по порядку: 3 · 2 = 6, затем 6 + 4 = 10, и наконец 10 · 2 = 20.","en":"Run the commands in order: 3 × 2 = 6, then 6 + 4 = 10, and finally 10 × 2 = 20."}'::jsonb, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
('1e58be9c-dd29-5ae6-b1d7-ca31f73252e0', 'informatics-10', 'INFORMATICS', 2, 5, 9, '{"uz":"Internet","ru":"Интернет","en":"The Internet"}'::jsonb, '{"uz":"Sayt manzili https:// bilan boshlansa, bu nimani bildiradi?","ru":"Что означает, что адрес сайта начинается с https://?","en":"What does it mean when a website address starts with https://?"}'::jsonb, '[{"uz":"Sayt bepul","ru":"Сайт бесплатный","en":"The site is free"},{"uz":"Saytda reklama yo‘q","ru":"На сайте нет рекламы","en":"The site has no ads"},{"uz":"Sayt ingliz tilida","ru":"Сайт на английском","en":"The site is in English"},{"uz":"Ulanish shifrlangan","ru":"Соединение зашифровано","en":"The connection is encrypted"}]'::jsonb, 3, '{"uz":"S harfi «secure», ya’ni «xavfsiz» degani: brauzer va sayt o‘rtasidagi ma’lumotlar shifrlanadi. Lekin bu saytning o‘zi ishonchli ekanini kafolatlamaydi.","ru":"Буква S означает secure — «защищённый»: данные между браузером и сайтом шифруются. Но это не гарантирует, что сам сайт честный.","en":"The S stands for “secure”: data between your browser and the site is encrypted. It does not prove the site itself is trustworthy, though."}'::jsonb, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
('627013bd-eeed-57c2-a5d3-ee3bc2db153d', 'informatics-11', 'INFORMATICS', 3, 5, 9, '{"uz":"Ikkilik sanoq tizimi","ru":"Двоичная система","en":"Binary numbers"}'::jsonb, '{"uz":"O‘nlik sanoq tizimidagi 13 sonini ikkilik sanoq tizimida yozing.","ru":"Запишите десятичное число 13 в двоичной системе счисления.","en":"Write the decimal number 13 in binary."}'::jsonb, '[{"uz":"1011","ru":"1011","en":"1011"},{"uz":"1101","ru":"1101","en":"1101"},{"uz":"1110","ru":"1110","en":"1110"},{"uz":"1001","ru":"1001","en":"1001"}]'::jsonb, 1, '{"uz":"13 ni 2 ning darajalari yig‘indisi sifatida yozamiz: 13 = 8 + 4 + 1 = 1 · 8 + 1 · 4 + 0 · 2 + 1 · 1. Demak, 1101.","ru":"Разложим 13 по степеням двойки: 13 = 8 + 4 + 1 = 1 · 8 + 1 · 4 + 0 · 2 + 1 · 1. Значит, 1101.","en":"Split 13 into powers of 2: 13 = 8 + 4 + 1 = 1 × 8 + 1 × 4 + 0 × 2 + 1 × 1. So it is 1101."}'::jsonb, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
('27068784-40cf-523c-81be-1fb61eb916c2', 'informatics-12', 'INFORMATICS', 3, 5, 9, '{"uz":"Axborot birliklari","ru":"Единицы информации","en":"Units of information"}'::jsonb, '{"uz":"2 Kbaytda necha bit bor? (1 Kbayt = 1024 bayt)","ru":"Сколько бит в 2 Кбайтах? (1 Кбайт = 1024 байта)","en":"How many bits are there in 2 KB? (1 KB = 1024 bytes)"}'::jsonb, '[{"uz":"2048","ru":"2048","en":"2048"},{"uz":"16 000","ru":"16 000","en":"16,000"},{"uz":"16 384","ru":"16 384","en":"16,384"},{"uz":"2000","ru":"2000","en":"2000"}]'::jsonb, 2, '{"uz":"2 Kbayt = 2 · 1024 = 2048 bayt. Har bir baytda 8 bit bor: 2048 · 8 = 16 384 bit.","ru":"2 Кбайта = 2 · 1024 = 2048 байт. В каждом байте 8 бит: 2048 · 8 = 16 384 бита.","en":"2 KB = 2 × 1024 = 2048 bytes. Each byte has 8 bits: 2048 × 8 = 16,384 bits."}'::jsonb, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
('7eaf32a7-bd87-595e-b31c-b7fb0afae21c', 'informatics-13', 'INFORMATICS', 3, 5, 9, '{"uz":"Sikllar","ru":"Циклы","en":"Loops"}'::jsonb, '{"uz":"s := 0; i ning 1, 2, 3, 4 qiymatlari uchun takrorlang: s := s + i * i. Sikl tugagach, s nechaga teng?","ru":"s := 0; для i = 1, 2, 3, 4 повторить: s := s + i * i. Чему равно s после цикла?","en":"s := 0; repeat for i = 1, 2, 3, 4: s := s + i * i. What is s after the loop?"}'::jsonb, '[{"uz":"30","ru":"30","en":"30"},{"uz":"10","ru":"10","en":"10"},{"uz":"20","ru":"20","en":"20"},{"uz":"100","ru":"100","en":"100"}]'::jsonb, 0, '{"uz":"Har bir qadamda i ning kvadrati qo‘shiladi: 1 + 4 + 9 + 16 = 30.","ru":"На каждом шаге прибавляется квадрат i: 1 + 4 + 9 + 16 = 30.","en":"Each step adds the square of i: 1 + 4 + 9 + 16 = 30."}'::jsonb, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
('959ad4a4-44a7-5562-afe6-fe25fb22d10d', 'informatics-14', 'INFORMATICS', 3, 5, 9, '{"uz":"Elektron jadvallar","ru":"Электронные таблицы","en":"Spreadsheets"}'::jsonb, '{"uz":"Elektron jadvalda A1 katakda 10 soni, B1 da =A1*2 formulasi, C1 da esa =B1-A1+5 formulasi yozilgan. C1 katakda qanday qiymat chiqadi?","ru":"В электронной таблице в ячейке A1 записано 10, в B1 — формула =A1*2, в C1 — формула =B1-A1+5. Какое значение будет в C1?","en":"In a spreadsheet, A1 contains 10, B1 contains =A1*2 and C1 contains =B1-A1+5. What value does C1 show?"}'::jsonb, '[{"uz":"25","ru":"25","en":"25"},{"uz":"5","ru":"5","en":"5"},{"uz":"35","ru":"35","en":"35"},{"uz":"15","ru":"15","en":"15"}]'::jsonb, 3, '{"uz":"Avval B1 hisoblanadi: 10 · 2 = 20. Keyin C1: 20 − 10 + 5 = 15.","ru":"Сначала вычисляется B1: 10 · 2 = 20. Затем C1: 20 − 10 + 5 = 15.","en":"First B1 is calculated: 10 × 2 = 20. Then C1: 20 − 10 + 5 = 15."}'::jsonb, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
('4dfda12a-1f38-56dc-b8d1-ac9c0e00485b', 'informatics-15', 'INFORMATICS', 3, 5, 9, '{"uz":"Axborot miqdori","ru":"Количество информации","en":"Amount of information"}'::jsonb, '{"uz":"Alifbo 32 ta belgidan iborat. Shu alifboning bitta belgisi necha bit axborot tashiydi?","ru":"Алфавит состоит из 32 символов. Сколько бит информации несёт один символ этого алфавита?","en":"An alphabet has 32 characters. How many bits of information does one character of this alphabet carry?"}'::jsonb, '[{"uz":"5 bit","ru":"5 бит","en":"5 bits"},{"uz":"32 bit","ru":"32 бита","en":"32 bits"},{"uz":"8 bit","ru":"8 бит","en":"8 bits"},{"uz":"16 bit","ru":"16 бит","en":"16 bits"}]'::jsonb, 0, '{"uz":"N = 2ⁱ formulasidan foydalanamiz: 32 = 2⁵, demak, bitta belgi 5 bit axborot tashiydi.","ru":"По формуле N = 2ⁱ: 32 = 2⁵, значит, один символ несёт 5 бит информации.","en":"Use the formula N = 2ⁱ: 32 = 2⁵, so one character carries 5 bits of information."}'::jsonb, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
('cb542402-e238-569d-a229-1fc414a616e7', 'math-01', 'MATH', 1, 5, 9, '{"uz":"Kasrlar","ru":"Дроби","en":"Fractions"}'::jsonb, '{"uz":"Hisoblang: 3/4 + 1/8","ru":"Вычислите: 3/4 + 1/8","en":"Calculate: 3/4 + 1/8"}'::jsonb, '[{"uz":"4/12","ru":"4/12","en":"4/12"},{"uz":"5/8","ru":"5/8","en":"5/8"},{"uz":"7/8","ru":"7/8","en":"7/8"},{"uz":"1","ru":"1","en":"1"}]'::jsonb, 2, '{"uz":"Kasrlarni umumiy maxrajga keltiramiz: 3/4 = 6/8. Demak, 6/8 + 1/8 = 7/8.","ru":"Приведём дроби к общему знаменателю: 3/4 = 6/8. Значит, 6/8 + 1/8 = 7/8.","en":"Bring the fractions to a common denominator: 3/4 = 6/8. So 6/8 + 1/8 = 7/8."}'::jsonb, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
('0e1e2e3e-744a-59be-af4c-7cbe50f82fbf', 'math-02', 'MATH', 1, 5, 9, '{"uz":"Foizlar","ru":"Проценты","en":"Percentages"}'::jsonb, '{"uz":"150 sonining 20 foizini toping.","ru":"Найдите 20% от числа 150.","en":"Find 20% of 150."}'::jsonb, '[{"uz":"15","ru":"15","en":"15"},{"uz":"30","ru":"30","en":"30"},{"uz":"20","ru":"20","en":"20"},{"uz":"75","ru":"75","en":"75"}]'::jsonb, 1, '{"uz":"20% — bu sonning 0,2 qismi. 150 · 0,2 = 30.","ru":"20% — это 0,2 от числа. 150 · 0,2 = 30.","en":"20% means 0.2 of the number. 150 × 0.2 = 30."}'::jsonb, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
('96b9c018-c0df-53f3-ba10-443d57f1cb0a', 'math-03', 'MATH', 1, 5, 9, '{"uz":"Uchburchak burchaklari","ru":"Углы треугольника","en":"Triangle angles"}'::jsonb, '{"uz":"Har qanday uchburchak ichki burchaklarining yig‘indisi nechaga teng?","ru":"Чему равна сумма внутренних углов любого треугольника?","en":"What is the sum of the interior angles of any triangle?"}'::jsonb, '[{"uz":"90°","ru":"90°","en":"90°"},{"uz":"360°","ru":"360°","en":"360°"},{"uz":"270°","ru":"270°","en":"270°"},{"uz":"180°","ru":"180°","en":"180°"}]'::jsonb, 3, '{"uz":"Uchburchak ichki burchaklarining yig‘indisi doimo 180° ga teng. 360° esa to‘rtburchak burchaklarining yig‘indisi.","ru":"Сумма внутренних углов треугольника всегда равна 180°. А 360° — это сумма углов четырёхугольника.","en":"The interior angles of a triangle always add up to 180°. 360° is the sum for a quadrilateral."}'::jsonb, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
('bf767f0d-fda8-59b6-9f06-f3520633b1f3', 'math-04', 'MATH', 1, 5, 9, '{"uz":"Darajalar","ru":"Степени","en":"Powers"}'::jsonb, '{"uz":"3³ nechaga teng?","ru":"Чему равно 3³?","en":"What is 3³?"}'::jsonb, '[{"uz":"9","ru":"9","en":"9"},{"uz":"27","ru":"27","en":"27"},{"uz":"81","ru":"81","en":"81"},{"uz":"6","ru":"6","en":"6"}]'::jsonb, 1, '{"uz":"3³ — bu uchta 3 ning ko‘paytmasi: 3 · 3 · 3 = 27.","ru":"3³ — это произведение трёх троек: 3 · 3 · 3 = 27.","en":"3³ is the product of three 3s: 3 × 3 × 3 = 27."}'::jsonb, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
('13dea629-699b-52b7-affd-5454d7ddbda2', 'math-05', 'MATH', 1, 5, 9, '{"uz":"Perimetr","ru":"Периметр","en":"Perimeter"}'::jsonb, '{"uz":"To‘g‘ri to‘rtburchakning tomonlari 7 sm va 4 sm. Uning perimetri nechaga teng?","ru":"Стороны прямоугольника равны 7 см и 4 см. Чему равен его периметр?","en":"A rectangle has sides of 7 cm and 4 cm. What is its perimeter?"}'::jsonb, '[{"uz":"22 sm","ru":"22 см","en":"22 cm"},{"uz":"28 sm","ru":"28 см","en":"28 cm"},{"uz":"11 sm","ru":"11 см","en":"11 cm"},{"uz":"18 sm","ru":"18 см","en":"18 cm"}]'::jsonb, 0, '{"uz":"Perimetr barcha tomonlar yig‘indisiga teng: (7 + 4) · 2 = 22 sm. 28 sm² esa bu shaklning yuzi.","ru":"Периметр — сумма всех сторон: (7 + 4) · 2 = 22 см. А 28 см² — это площадь.","en":"The perimeter is the sum of all sides: (7 + 4) × 2 = 22 cm. 28 cm² would be the area."}'::jsonb, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
('3d20fb5e-800c-57f6-b32a-0d51b8dc2149', 'math-06', 'MATH', 2, 5, 9, '{"uz":"Tenglamalar","ru":"Уравнения","en":"Equations"}'::jsonb, '{"uz":"Tenglamani yeching: 3x − 7 = 11","ru":"Решите уравнение: 3x − 7 = 11","en":"Solve the equation: 3x − 7 = 11"}'::jsonb, '[{"uz":"x = 4","ru":"x = 4","en":"x = 4"},{"uz":"x = 18","ru":"x = 18","en":"x = 18"},{"uz":"x = 3","ru":"x = 3","en":"x = 3"},{"uz":"x = 6","ru":"x = 6","en":"x = 6"}]'::jsonb, 3, '{"uz":"Ikkala tomonga 7 ni qo‘shamiz: 3x = 18. Endi 3 ga bo‘lamiz: x = 6.","ru":"Прибавим 7 к обеим частям: 3x = 18. Разделим на 3: x = 6.","en":"Add 7 to both sides: 3x = 18. Then divide by 3: x = 6."}'::jsonb, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
('497d57de-4aae-58af-95b4-ec6ef6acc2f1', 'math-07', 'MATH', 2, 5, 9, '{"uz":"Nisbatlar","ru":"Отношения","en":"Ratios"}'::jsonb, '{"uz":"45 ta konfet ikki bola o‘rtasida 2 : 3 nisbatda bo‘lindi. Ikkinchi bola nechta konfet oldi?","ru":"45 конфет разделили между двумя детьми в отношении 2 : 3. Сколько конфет получил второй ребёнок?","en":"45 sweets are shared between two children in the ratio 2 : 3. How many sweets does the second child get?"}'::jsonb, '[{"uz":"18","ru":"18","en":"18"},{"uz":"27","ru":"27","en":"27"},{"uz":"15","ru":"15","en":"15"},{"uz":"30","ru":"30","en":"30"}]'::jsonb, 1, '{"uz":"Jami 2 + 3 = 5 ulush, bir ulush 45 : 5 = 9 ta. Ikkinchi bolaga 3 · 9 = 27 ta konfet tegadi.","ru":"Всего 2 + 3 = 5 частей, одна часть — 45 : 5 = 9 конфет. Второму достаётся 3 · 9 = 27.","en":"There are 2 + 3 = 5 parts, so one part is 45 ÷ 5 = 9. The second child gets 3 × 9 = 27."}'::jsonb, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
('734c07dd-09df-5777-aabd-28006e1770b0', 'math-08', 'MATH', 2, 5, 9, '{"uz":"Uchburchak yuzi","ru":"Площадь треугольника","en":"Triangle area"}'::jsonb, '{"uz":"Uchburchakning asosi 10 sm, balandligi 6 sm. Uning yuzi nechaga teng?","ru":"Основание треугольника 10 см, высота 6 см. Чему равна его площадь?","en":"A triangle has a base of 10 cm and a height of 6 cm. What is its area?"}'::jsonb, '[{"uz":"60 sm²","ru":"60 см²","en":"60 cm²"},{"uz":"16 sm²","ru":"16 см²","en":"16 cm²"},{"uz":"30 sm²","ru":"30 см²","en":"30 cm²"},{"uz":"32 sm²","ru":"32 см²","en":"32 cm²"}]'::jsonb, 2, '{"uz":"Uchburchak yuzi asos va balandlik ko‘paytmasining yarmiga teng: 10 · 6 : 2 = 30 sm².","ru":"Площадь треугольника равна половине произведения основания на высоту: 10 · 6 : 2 = 30 см².","en":"A triangle’s area is half of base times height: 10 × 6 ÷ 2 = 30 cm²."}'::jsonb, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
('d0a874d8-9056-5fdc-b55c-0b96406f4412', 'math-09', 'MATH', 2, 5, 9, '{"uz":"Manfiy sonlar","ru":"Отрицательные числа","en":"Negative numbers"}'::jsonb, '{"uz":"Hisoblang: (−8) + 5 − (−4)","ru":"Вычислите: (−8) + 5 − (−4)","en":"Calculate: (−8) + 5 − (−4)"}'::jsonb, '[{"uz":"1","ru":"1","en":"1"},{"uz":"−7","ru":"−7","en":"−7"},{"uz":"−17","ru":"−17","en":"−17"},{"uz":"17","ru":"17","en":"17"}]'::jsonb, 0, '{"uz":"Manfiy sonni ayirish musbat sonni qo‘shishga teng: (−8) + 5 + 4 = 1.","ru":"Вычесть отрицательное число — значит прибавить положительное: (−8) + 5 + 4 = 1.","en":"Subtracting a negative number is the same as adding a positive one: (−8) + 5 + 4 = 1."}'::jsonb, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
('a96eac0f-60e7-5d03-959d-cd2a3940a83a', 'math-10', 'MATH', 2, 5, 9, '{"uz":"Foizlar","ru":"Проценты","en":"Percentages"}'::jsonb, '{"uz":"Kitob 80 000 so‘m turardi. Uning narxi 15% ga oshdi. Kitob endi qancha turadi?","ru":"Книга стоила 80 000 сумов. Её цена выросла на 15%. Сколько теперь стоит книга?","en":"A book cost 80,000 soums. Its price went up by 15%. How much does the book cost now?"}'::jsonb, '[{"uz":"95 000 so‘m","ru":"95 000 сумов","en":"95,000 soums"},{"uz":"81 200 so‘m","ru":"81 200 сумов","en":"81,200 soums"},{"uz":"92 000 so‘m","ru":"92 000 сумов","en":"92,000 soums"},{"uz":"88 000 so‘m","ru":"88 000 сумов","en":"88,000 soums"}]'::jsonb, 2, '{"uz":"80 000 so‘mning 15 foizi: 80 000 · 0,15 = 12 000 so‘m. Yangi narx: 80 000 + 12 000 = 92 000 so‘m.","ru":"15% от 80 000: 80 000 · 0,15 = 12 000 сумов. Новая цена: 80 000 + 12 000 = 92 000 сумов.","en":"15% of 80,000 is 80,000 × 0.15 = 12,000 soums. New price: 80,000 + 12,000 = 92,000 soums."}'::jsonb, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
('44a55012-0f06-503c-a17f-ba9ed4621eff', 'math-11', 'MATH', 3, 5, 9, '{"uz":"Pifagor teoremasi","ru":"Теорема Пифагора","en":"Pythagorean theorem"}'::jsonb, '{"uz":"To‘g‘ri burchakli uchburchakning katetlari 6 sm va 8 sm. Uning gipotenuzasi nechaga teng?","ru":"Катеты прямоугольного треугольника равны 6 см и 8 см. Чему равна гипотенуза?","en":"The legs of a right triangle are 6 cm and 8 cm. How long is the hypotenuse?"}'::jsonb, '[{"uz":"14 sm","ru":"14 см","en":"14 cm"},{"uz":"10 sm","ru":"10 см","en":"10 cm"},{"uz":"12 sm","ru":"12 см","en":"12 cm"},{"uz":"7 sm","ru":"7 см","en":"7 cm"}]'::jsonb, 1, '{"uz":"Pifagor teoremasi bo‘yicha: c² = 6² + 8² = 36 + 64 = 100, demak, c = 10 sm.","ru":"По теореме Пифагора: c² = 6² + 8² = 36 + 64 = 100, значит, c = 10 см.","en":"By the Pythagorean theorem: c² = 6² + 8² = 36 + 64 = 100, so c = 10 cm."}'::jsonb, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
('b2fe0cdf-8d8e-54c1-8c45-465103d4a45d', 'math-12', 'MATH', 3, 5, 9, '{"uz":"Kvadrat tenglamalar","ru":"Квадратные уравнения","en":"Quadratic equations"}'::jsonb, '{"uz":"x² − 5x + 6 = 0 tenglamaning ildizlarini toping.","ru":"Найдите корни уравнения x² − 5x + 6 = 0.","en":"Find the roots of the equation x² − 5x + 6 = 0."}'::jsonb, '[{"uz":"−2 va −3","ru":"−2 и −3","en":"−2 and −3"},{"uz":"1 va 6","ru":"1 и 6","en":"1 and 6"},{"uz":"−1 va 6","ru":"−1 и 6","en":"−1 and 6"},{"uz":"2 va 3","ru":"2 и 3","en":"2 and 3"}]'::jsonb, 3, '{"uz":"Viyet teoremasi bo‘yicha ildizlar yig‘indisi 5 ga, ko‘paytmasi esa 6 ga teng. Bular 2 va 3 sonlari.","ru":"По теореме Виета сумма корней равна 5, а произведение — 6. Это числа 2 и 3.","en":"By Vieta’s theorem the roots add up to 5 and multiply to 6. Those numbers are 2 and 3."}'::jsonb, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
('044c34b8-afa9-50d3-a47b-fc0d72dd6489', 'math-13', 'MATH', 3, 5, 9, '{"uz":"O‘rta arifmetik","ru":"Среднее арифметическое","en":"Average"}'::jsonb, '{"uz":"To‘rtta sonning o‘rta arifmetigi 15 ga teng. Ulardan uchtasi 10, 12 va 20. To‘rtinchi sonni toping.","ru":"Среднее арифметическое четырёх чисел равно 15. Три из них — 10, 12 и 20. Найдите четвёртое число.","en":"The average of four numbers is 15. Three of them are 10, 12 and 20. Find the fourth number."}'::jsonb, '[{"uz":"18","ru":"18","en":"18"},{"uz":"15","ru":"15","en":"15"},{"uz":"14","ru":"14","en":"14"},{"uz":"28","ru":"28","en":"28"}]'::jsonb, 0, '{"uz":"To‘rtta sonning yig‘indisi 4 · 15 = 60. Ma’lum sonlar yig‘indisi 42, demak, to‘rtinchi son 60 − 42 = 18.","ru":"Сумма четырёх чисел равна 4 · 15 = 60. Сумма известных — 42, значит, четвёртое число 60 − 42 = 18.","en":"The four numbers add up to 4 × 15 = 60. The known ones add up to 42, so the fourth is 60 − 42 = 18."}'::jsonb, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
('48707c72-1218-5eeb-9e09-dfbc09622b77', 'math-14', 'MATH', 3, 5, 9, '{"uz":"Chiziqli funksiya","ru":"Линейная функция","en":"Linear function"}'::jsonb, '{"uz":"Quyidagi nuqtalardan qaysi biri y = 2x − 3 funksiya grafigida yotadi?","ru":"Какая из точек лежит на графике функции y = 2x − 3?","en":"Which point lies on the graph of y = 2x − 3?"}'::jsonb, '[{"uz":"(1; 1)","ru":"(1; 1)","en":"(1, 1)"},{"uz":"(0; 3)","ru":"(0; 3)","en":"(0, 3)"},{"uz":"(4; 5)","ru":"(4; 5)","en":"(4, 5)"},{"uz":"(2; 2)","ru":"(2; 2)","en":"(2, 2)"}]'::jsonb, 2, '{"uz":"x = 4 ni qo‘yamiz: y = 2 · 4 − 3 = 5. Demak, (4; 5) nuqta grafikda yotadi, qolgan nuqtalar uchun tenglik bajarilmaydi.","ru":"Подставим x = 4: y = 2 · 4 − 3 = 5. Значит, точка (4; 5) лежит на графике, а для остальных точек равенство не выполняется.","en":"Substitute x = 4: y = 2 × 4 − 3 = 5, so (4, 5) is on the graph. The other points do not satisfy the equation."}'::jsonb, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
('c70c9bfb-9145-5d12-a2e7-b423013ad255', 'math-15', 'MATH', 3, 5, 9, '{"uz":"Ehtimollik","ru":"Вероятность","en":"Probability"}'::jsonb, '{"uz":"Xaltada 3 ta qizil va 5 ta ko‘k shar bor. Tavakkaliga olingan shar qizil bo‘lish ehtimoli qancha?","ru":"В мешке 3 красных и 5 синих шаров. Какова вероятность, что наугад вынутый шар окажется красным?","en":"A bag holds 3 red and 5 blue balls. What is the probability that a ball taken at random is red?"}'::jsonb, '[{"uz":"3/5","ru":"3/5","en":"3/5"},{"uz":"3/8","ru":"3/8","en":"3/8"},{"uz":"5/8","ru":"5/8","en":"5/8"},{"uz":"1/3","ru":"1/3","en":"1/3"}]'::jsonb, 1, '{"uz":"Jami 3 + 5 = 8 ta shar bor, ulardan 3 tasi qizil. Ehtimollik 3/8 ga teng.","ru":"Всего 3 + 5 = 8 шаров, из них 3 красных. Вероятность равна 3/8.","en":"There are 3 + 5 = 8 balls in total and 3 of them are red. The probability is 3/8."}'::jsonb, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
('fc0549d5-79da-5396-b2c6-b7b5b2abd48e', 'math-16', 'MATH', 1, 1, 4, '{"uz":"Qo‘shish","ru":"Сложение","en":"Addition"}'::jsonb, '{"uz":"7 ga 8 ni qo‘shsak, necha bo‘ladi?","ru":"Сколько будет 7 + 8?","en":"What is 7 + 8?"}'::jsonb, '[{"uz":"14","ru":"14","en":"14"},{"uz":"15","ru":"15","en":"15"},{"uz":"16","ru":"16","en":"16"},{"uz":"13","ru":"13","en":"13"}]'::jsonb, 1, '{"uz":"7 ga 3 ni qo‘shsak 10 bo‘ladi, yana 5 ni qo‘shsak 15. Demak, 7 + 8 = 15.","ru":"7 + 3 = 10, и ещё 5 — получается 15. Значит, 7 + 8 = 15.","en":"7 + 3 makes 10, and 5 more makes 15. So 7 + 8 = 15."}'::jsonb, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
('2ca01d2f-2685-59cd-b533-bafdb7c1ff61', 'math-17', 'MATH', 1, 1, 4, '{"uz":"Sonlarni taqqoslash","ru":"Сравнение чисел","en":"Comparing numbers"}'::jsonb, '{"uz":"Qaysi son eng katta?","ru":"Какое число самое большое?","en":"Which number is the largest?"}'::jsonb, '[{"uz":"506","ru":"506","en":"506"},{"uz":"560","ru":"560","en":"560"},{"uz":"605","ru":"605","en":"605"},{"uz":"650","ru":"650","en":"650"}]'::jsonb, 3, '{"uz":"Avval yuzliklarni taqqoslaymiz: 605 va 650 da 6 tadan yuzlik bor. Keyin o‘nliklarni: 5 ta o‘nlik 0 tadan ko‘p, demak, 650 eng katta.","ru":"Сначала сравним сотни: у 605 и 650 по 6 сотен. Затем десятки: 5 десятков больше, чем 0, значит, 650 — самое большое.","en":"First compare the hundreds: 605 and 650 both have 6. Then the tens: 5 tens beat 0 tens, so 650 is the largest."}'::jsonb, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
('c0bad27d-53e0-52be-a5ff-f7c2e39e924e', 'math-18', 'MATH', 1, 1, 4, '{"uz":"Shakllar","ru":"Фигуры","en":"Shapes"}'::jsonb, '{"uz":"Qaysi shaklning burchagi yo‘q?","ru":"У какой фигуры нет углов?","en":"Which shape has no corners?"}'::jsonb, '[{"uz":"Kvadrat","ru":"Квадрат","en":"Square"},{"uz":"Uchburchak","ru":"Треугольник","en":"Triangle"},{"uz":"Doira","ru":"Круг","en":"Circle"},{"uz":"To‘g‘ri to‘rtburchak","ru":"Прямоугольник","en":"Rectangle"}]'::jsonb, 2, '{"uz":"Doiraning chegarasi silliq egri chiziq, unda burchak ham, tomon ham yo‘q. Qolgan shakllarning burchaklari bor.","ru":"Граница круга — плавная линия без углов и сторон. У остальных фигур углы есть.","en":"A circle’s edge is a smooth curve with no corners or sides. All the other shapes have corners."}'::jsonb, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
('de898696-242e-5061-9900-f7d581195684', 'math-19', 'MATH', 2, 1, 4, '{"uz":"Vaqt","ru":"Время","en":"Time"}'::jsonb, '{"uz":"Multfilm soat 15:30 da boshlanadi va 1 soat 40 daqiqa davom etadi. U soat nechada tugaydi?","ru":"Мультфильм начинается в 15:30 и идёт 1 час 40 минут. Во сколько он закончится?","en":"A cartoon starts at 15:30 and lasts 1 hour 40 minutes. What time does it end?"}'::jsonb, '[{"uz":"17:10","ru":"17:10","en":"17:10"},{"uz":"16:50","ru":"16:50","en":"16:50"},{"uz":"17:40","ru":"17:40","en":"17:40"},{"uz":"16:10","ru":"16:10","en":"16:10"}]'::jsonb, 0, '{"uz":"15:30 ga 1 soat qo‘shsak, 16:30 bo‘ladi. Yana 30 daqiqadan keyin 17:00, qolgan 10 daqiqa bilan esa 17:10.","ru":"15:30 плюс 1 час — это 16:30. Ещё 30 минут — 17:00, и оставшиеся 10 минут дают 17:10.","en":"15:30 plus 1 hour is 16:30. Another 30 minutes makes 17:00, and the last 10 minutes give 17:10."}'::jsonb, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
('594d6a02-055e-50c3-9257-e81acf9e7318', 'math-20', 'MATH', 2, 1, 4, '{"uz":"Ko‘paytirish","ru":"Умножение","en":"Multiplication"}'::jsonb, '{"uz":"4 ta qutining har birida 6 tadan qalam bor. Jami nechta qalam bor?","ru":"В 4 коробках лежит по 6 карандашей. Сколько всего карандашей?","en":"There are 4 boxes with 6 pencils in each. How many pencils are there in total?"}'::jsonb, '[{"uz":"10","ru":"10","en":"10"},{"uz":"20","ru":"20","en":"20"},{"uz":"28","ru":"28","en":"28"},{"uz":"24","ru":"24","en":"24"}]'::jsonb, 3, '{"uz":"Bir xil sonlarni qayta-qayta qo‘shish o‘rniga ko‘paytiramiz: 6 · 4 = 24 ta qalam.","ru":"Вместо того чтобы складывать одинаковые числа, умножаем: 6 · 4 = 24 карандаша.","en":"Instead of adding the same number again and again, multiply: 6 × 4 = 24 pencils."}'::jsonb, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
('dd8954c2-6d51-5940-88aa-23c9f536871e', 'math-21', 'MATH', 2, 1, 4, '{"uz":"Ayirish","ru":"Вычитание","en":"Subtraction"}'::jsonb, '{"uz":"Hisoblang: 100 − 37","ru":"Вычислите: 100 − 37","en":"Work out: 100 − 37"}'::jsonb, '[{"uz":"63","ru":"63","en":"63"},{"uz":"73","ru":"73","en":"73"},{"uz":"67","ru":"67","en":"67"},{"uz":"137","ru":"137","en":"137"}]'::jsonb, 0, '{"uz":"100 dan 30 ni ayirsak 70 qoladi, 70 dan 7 ni ayirsak 63. Tekshiramiz: 63 + 37 = 100.","ru":"100 − 30 = 70, затем 70 − 7 = 63. Проверка: 63 + 37 = 100.","en":"100 − 30 = 70, then 70 − 7 = 63. Check: 63 + 37 = 100."}'::jsonb, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
('4bfda949-2dda-5560-9a85-b33b5a8cc064', 'native-01', 'NATIVE', 1, 5, 9, '{"uz":"So‘z turkumlari","ru":"Части речи","en":"Parts of speech"}'::jsonb, '{"uz":"Qaysi so‘z ot so‘z turkumiga kiradi?","ru":"Какое слово в узбекском языке является существительным (ot)?","en":"Which Uzbek word is a noun (ot)?"}'::jsonb, '[{"uz":"chiroyli","ru":"chiroyli","en":"chiroyli"},{"uz":"kitob","ru":"kitob","en":"kitob"},{"uz":"yugurmoq","ru":"yugurmoq","en":"yugurmoq"},{"uz":"tez","ru":"tez","en":"tez"}]'::jsonb, 1, '{"uz":"Ot narsa yoki shaxsni bildiradi va “kim?”, “nima?” so‘roqlariga javob beradi: kitob — nima?","ru":"Существительное (ot) обозначает предмет и отвечает на вопросы kim? (кто?) и nima? (что?): kitob — «книга».","en":"A noun (ot) names a thing or person and answers kim? (who?) or nima? (what?): kitob means book."}'::jsonb, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
('6c4c7700-f1a1-5829-b170-e26187aef9bd', 'native-02', 'NATIVE', 1, 5, 9, '{"uz":"So‘z turkumlari","ru":"Части речи","en":"Parts of speech"}'::jsonb, '{"uz":"Qaysi so‘z sifat so‘z turkumiga kiradi?","ru":"Какое узбекское слово является прилагательным (sifat)?","en":"Which Uzbek word is an adjective (sifat)?"}'::jsonb, '[{"uz":"daraxt","ru":"daraxt","en":"daraxt"},{"uz":"o‘qimoq","ru":"o‘qimoq","en":"o‘qimoq"},{"uz":"biz","ru":"biz","en":"biz"},{"uz":"baland","ru":"baland","en":"baland"}]'::jsonb, 3, '{"uz":"Sifat belgini bildiradi va “qanday?” so‘rog‘iga javob beradi: baland (qanday?).","ru":"Прилагательное (sifat) обозначает признак и отвечает на вопрос qanday? (какой?): baland — «высокий».","en":"An adjective (sifat) describes a quality and answers qanday? (what kind?): baland means tall."}'::jsonb, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
('2cefa036-2560-5eaa-b563-30770a26460f', 'native-03', 'NATIVE', 1, 5, 9, '{"uz":"Antonimlar","ru":"Антонимы","en":"Antonyms"}'::jsonb, '{"uz":"“Issiq” so‘zining antonimini toping.","ru":"Найдите антоним к узбекскому слову «issiq».","en":"Find the antonym of the Uzbek word “issiq”."}'::jsonb, '[{"uz":"sovuq","ru":"sovuq","en":"sovuq"},{"uz":"iliq","ru":"iliq","en":"iliq"},{"uz":"qaynoq","ru":"qaynoq","en":"qaynoq"},{"uz":"yumshoq","ru":"yumshoq","en":"yumshoq"}]'::jsonb, 0, '{"uz":"Antonimlar qarama-qarshi ma’noli so‘zlardir: issiq — sovuq.","ru":"Антонимы — слова с противоположным значением: issiq («горячий») — sovuq («холодный»).","en":"Antonyms have opposite meanings: issiq (hot) — sovuq (cold)."}'::jsonb, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
('bfbc8fee-e37b-579a-beea-f21c5f1dc5ab', 'native-04', 'NATIVE', 1, 5, 9, '{"uz":"Sinonimlar","ru":"Синонимы","en":"Synonyms"}'::jsonb, '{"uz":"“Chiroyli” so‘zining sinonimini toping.","ru":"Найдите синоним к узбекскому слову «chiroyli».","en":"Find the synonym of the Uzbek word “chiroyli”."}'::jsonb, '[{"uz":"xunuk","ru":"xunuk","en":"xunuk"},{"uz":"katta","ru":"katta","en":"katta"},{"uz":"go‘zal","ru":"go‘zal","en":"go‘zal"},{"uz":"aqlli","ru":"aqlli","en":"aqlli"}]'::jsonb, 2, '{"uz":"Sinonimlar ma’nosi yaqin so‘zlardir: “chiroyli” va “go‘zal” bir xil ma’noni bildiradi.","ru":"Синонимы близки по значению: chiroyli и go‘zal оба значат «красивый».","en":"Synonyms have similar meanings: chiroyli and go‘zal both mean beautiful."}'::jsonb, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
('549aff8e-4ba5-59ce-82eb-738fffc0b82b', 'native-05', 'NATIVE', 1, 5, 9, '{"uz":"Imlo","ru":"Орфография","en":"Spelling"}'::jsonb, '{"uz":"Qaysi so‘z to‘g‘ri yozilgan?","ru":"Какое узбекское слово написано правильно?","en":"Which Uzbek word is spelled correctly?"}'::jsonb, '[{"uz":"hayvon","ru":"hayvon","en":"hayvon"},{"uz":"xayvon","ru":"xayvon","en":"xayvon"},{"uz":"haybon","ru":"haybon","en":"haybon"},{"uz":"xaywon","ru":"xaywon","en":"xaywon"}]'::jsonb, 0, '{"uz":"“Hayvon” so‘zi h harfi bilan yoziladi; h va x harflarini adashtirmang.","ru":"Слово hayvon («животное») пишется с буквой h; не путайте h и x.","en":"Hayvon (animal) is spelled with h; be careful not to mix up h and x."}'::jsonb, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
('9724ddc3-f60d-50d8-b58c-053e1510665a', 'native-06', 'NATIVE', 2, 5, 9, '{"uz":"So‘z turkumlari","ru":"Части речи","en":"Parts of speech"}'::jsonb, '{"uz":"Qaysi so‘z fe’l so‘z turkumiga kiradi?","ru":"Какое узбекское слово является глаголом (fe’l)?","en":"Which Uzbek word is a verb (fe’l)?"}'::jsonb, '[{"uz":"ish","ru":"ish","en":"ish"},{"uz":"ishchi","ru":"ishchi","en":"ishchi"},{"uz":"ishchan","ru":"ishchan","en":"ishchan"},{"uz":"ishlamoq","ru":"ishlamoq","en":"ishlamoq"}]'::jsonb, 3, '{"uz":"Fe’l harakatni bildiradi va “nima qilmoq?” so‘rog‘iga javob beradi: ishlamoq.","ru":"Глагол (fe’l) обозначает действие и отвечает на вопрос nima qilmoq? (что делать?): ishlamoq — «работать».","en":"A verb (fe’l) shows an action and answers nima qilmoq? (what to do?): ishlamoq means to work."}'::jsonb, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
('2ddd7b05-40ea-52b1-920c-b4e93170db6b', 'native-07', 'NATIVE', 2, 5, 9, '{"uz":"So‘z turkumlari","ru":"Части речи","en":"Parts of speech"}'::jsonb, '{"uz":"Qaysi so‘z son so‘z turkumiga kiradi?","ru":"Какое узбекское слово является числительным (son)?","en":"Which Uzbek word is a numeral (son)?"}'::jsonb, '[{"uz":"yetmoq","ru":"yetmoq","en":"yetmoq"},{"uz":"yetti","ru":"yetti","en":"yetti"},{"uz":"yetuk","ru":"yetuk","en":"yetuk"},{"uz":"yetim","ru":"yetim","en":"yetim"}]'::jsonb, 1, '{"uz":"Son narsaning miqdorini bildiradi va “necha?” so‘rog‘iga javob beradi: yetti.","ru":"Числительное (son) обозначает количество и отвечает на вопрос necha? (сколько?): yetti — «семь».","en":"A numeral (son) shows a number and answers necha? (how many?): yetti means seven."}'::jsonb, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
('8e1421e9-dd3a-5a0e-acee-646457611758', 'native-08', 'NATIVE', 2, 5, 9, '{"uz":"So‘z turkumlari","ru":"Части речи","en":"Parts of speech"}'::jsonb, '{"uz":"Gapdagi olmoshni toping: “Biz ertaga bog‘ga boramiz.”","ru":"Найдите местоимение (olmosh) в предложении: «Biz ertaga bog‘ga boramiz.»","en":"Find the pronoun (olmosh) in the sentence: “Biz ertaga bog‘ga boramiz.”"}'::jsonb, '[{"uz":"ertaga","ru":"ertaga","en":"ertaga"},{"uz":"bog‘ga","ru":"bog‘ga","en":"bog‘ga"},{"uz":"Biz","ru":"Biz","en":"Biz"},{"uz":"boramiz","ru":"boramiz","en":"boramiz"}]'::jsonb, 2, '{"uz":"Olmosh ot o‘rnida qo‘llanadi: “biz” — kishilik olmoshi.","ru":"Местоимение заменяет существительное: biz («мы») — личное местоимение.","en":"A pronoun replaces a noun: biz (we) is a personal pronoun."}'::jsonb, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
('6fa91704-dfff-5581-a793-9687e6177e1b', 'native-09', 'NATIVE', 2, 5, 9, '{"uz":"Kelishiklar","ru":"Падежи","en":"Cases"}'::jsonb, '{"uz":"Qaysi so‘z chiqish kelishigida turibdi?","ru":"Какое узбекское слово стоит в исходном падеже (chiqish kelishigi)?","en":"Which Uzbek word is in the ablative case (chiqish kelishigi)?"}'::jsonb, '[{"uz":"maktabdan","ru":"maktabdan","en":"maktabdan"},{"uz":"maktabga","ru":"maktabga","en":"maktabga"},{"uz":"maktabda","ru":"maktabda","en":"maktabda"},{"uz":"maktabning","ru":"maktabning","en":"maktabning"}]'::jsonb, 0, '{"uz":"Chiqish kelishigi -dan qo‘shimchasi bilan yasaladi va “qayerdan?” so‘rog‘iga javob beradi.","ru":"Исходный падеж образуется суффиксом -dan и отвечает на вопрос qayerdan? (откуда?).","en":"The ablative case uses the suffix -dan and answers qayerdan? (from where?)."}'::jsonb, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
('1a6b4e9a-50e2-5c51-b452-dc65a30af9de', 'native-10', 'NATIVE', 2, 5, 9, '{"uz":"Tinish belgilari","ru":"Знаки препинания","en":"Punctuation"}'::jsonb, '{"uz":"Qaysi gap oxiriga so‘roq belgisi (?) qo‘yiladi?","ru":"В конце какого узбекского предложения ставится вопросительный знак (?)?","en":"Which Uzbek sentence should end with a question mark (?)?"}'::jsonb, '[{"uz":"Bugun havo issiq","ru":"Bugun havo issiq","en":"Bugun havo issiq"},{"uz":"Kitobni o‘qib chiqdim","ru":"Kitobni o‘qib chiqdim","en":"Kitobni o‘qib chiqdim"},{"uz":"Qanday go‘zal kun","ru":"Qanday go‘zal kun","en":"Qanday go‘zal kun"},{"uz":"Sen qachon kelasan","ru":"Sen qachon kelasan","en":"Sen qachon kelasan"}]'::jsonb, 3, '{"uz":"Bu “qachon” so‘roq so‘zi bilan berilgan savol, shuning uchun oxiriga “?” qo‘yiladi; “Qanday go‘zal kun!” esa undov gap.","ru":"Это вопрос со словом qachon («когда»), поэтому в конце ставится «?»; «Qanday go‘zal kun!» — восклицательное предложение.","en":"It is a question with qachon (when), so it ends with “?”; “Qanday go‘zal kun!” is an exclamation."}'::jsonb, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
('d8690f6c-1707-502d-8db5-94a7d3a4ef1b', 'native-11', 'NATIVE', 3, 5, 9, '{"uz":"Gap bo‘laklari","ru":"Члены предложения","en":"Parts of a sentence"}'::jsonb, '{"uz":"“Aziz kecha kutubxonaga bordi.” gapining kesimini toping.","ru":"Найдите сказуемое (kesim) в узбекском предложении: «Aziz kecha kutubxonaga bordi.»","en":"Find the predicate (kesim) in the Uzbek sentence: “Aziz kecha kutubxonaga bordi.”"}'::jsonb, '[{"uz":"bordi","ru":"bordi","en":"bordi"},{"uz":"Aziz","ru":"Aziz","en":"Aziz"},{"uz":"kecha","ru":"kecha","en":"kecha"},{"uz":"kutubxonaga","ru":"kutubxonaga","en":"kutubxonaga"}]'::jsonb, 0, '{"uz":"Kesim eganing harakatini bildiradi va “nima qildi?” so‘rog‘iga javob beradi: bordi.","ru":"Сказуемое обозначает действие подлежащего и отвечает на вопрос nima qildi? (что сделал?): bordi — «пошёл».","en":"The predicate shows what the subject did and answers nima qildi? (what did he do?): bordi means went."}'::jsonb, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
('ba5ca624-30cc-5eca-ab68-fdbe207d57c7', 'native-12', 'NATIVE', 3, 5, 9, '{"uz":"Maqollar","ru":"Пословицы","en":"Proverbs"}'::jsonb, '{"uz":"Maqolni to‘ldiring: “Bir yigitga yetmish ___ oz.”","ru":"Дополните узбекскую пословицу: «Bir yigitga yetmish ___ oz.»","en":"Complete the Uzbek proverb: “Bir yigitga yetmish ___ oz.”"}'::jsonb, '[{"uz":"do‘st","ru":"do‘st","en":"do‘st"},{"uz":"hunar","ru":"hunar","en":"hunar"},{"uz":"kitob","ru":"kitob","en":"kitob"},{"uz":"til","ru":"til","en":"til"}]'::jsonb, 1, '{"uz":"Maqol inson ko‘p hunar egallashi foydali ekanini anglatadi: “Bir yigitga yetmish hunar oz.”","ru":"Пословица означает, что человеку полезно владеть многими ремёслами (hunar — «ремесло»).","en":"The proverb means it is good for a person to master many skills (hunar means craft or skill)."}'::jsonb, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
('921011d4-c1de-5187-b34d-91ffb36cd37c', 'native-13', 'NATIVE', 3, 5, 9, '{"uz":"O‘zbek adabiyoti","ru":"Узбекская литература","en":"Uzbek literature"}'::jsonb, '{"uz":"“O‘tkan kunlar” romanining muallifi kim?","ru":"Кто автор романа «O‘tkan kunlar» («Минувшие дни»)?","en":"Who wrote the novel “O‘tkan kunlar” (Days Gone By)?"}'::jsonb, '[{"uz":"Alisher Navoiy","ru":"Alisher Navoiy","en":"Alisher Navoiy"},{"uz":"Abdulla Qodiriy","ru":"Abdulla Qodiriy","en":"Abdulla Qodiriy"},{"uz":"Cho‘lpon","ru":"Cho‘lpon","en":"Cho‘lpon"},{"uz":"G‘afur G‘ulom","ru":"G‘afur G‘ulom","en":"G‘afur G‘ulom"}]'::jsonb, 1, '{"uz":"“O‘tkan kunlar”ni Abdulla Qodiriy yozgan; bu o‘zbek adabiyotidagi birinchi roman hisoblanadi.","ru":"«O‘tkan kunlar» написал Абдулла Кадыри; это первый роман в узбекской литературе.","en":"Abdulla Qodiriy wrote “O‘tkan kunlar”; it is considered the first Uzbek novel."}'::jsonb, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
('9c0348ec-dce9-51f2-9a9e-66bd9520dbce', 'native-14', 'NATIVE', 3, 5, 9, '{"uz":"O‘zbek adabiyoti","ru":"Узбекская литература","en":"Uzbek literature"}'::jsonb, '{"uz":"“Xamsa” asarini kim yaratgan?","ru":"Кто создал произведение «Xamsa» («Хамса»)?","en":"Who created the work “Xamsa” (Khamsa)?"}'::jsonb, '[{"uz":"Abdulla Qodiriy","ru":"Abdulla Qodiriy","en":"Abdulla Qodiriy"},{"uz":"G‘afur G‘ulom","ru":"G‘afur G‘ulom","en":"G‘afur G‘ulom"},{"uz":"Alisher Navoiy","ru":"Alisher Navoiy","en":"Alisher Navoiy"},{"uz":"Cho‘lpon","ru":"Cho‘lpon","en":"Cho‘lpon"}]'::jsonb, 2, '{"uz":"“Xamsa” — Alisher Navoiyning beshta dostondan iborat mashhur asari.","ru":"«Хамса» — знаменитое произведение Алишера Навои, состоящее из пяти поэм (дастанов).","en":"“Xamsa” is the famous work of Alisher Navoiy, made up of five epic poems (dostons)."}'::jsonb, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
('b2876637-fe39-5236-a127-16c75da2bb52', 'native-15', 'NATIVE', 3, 5, 9, '{"uz":"O‘zbek adabiyoti","ru":"Узбекская литература","en":"Uzbek literature"}'::jsonb, '{"uz":"“Shum bola” qissasining muallifi kim?","ru":"Кто автор повести «Shum bola» («Озорник»)?","en":"Who wrote the story “Shum bola” (The Mischievous Boy)?"}'::jsonb, '[{"uz":"Cho‘lpon","ru":"Cho‘lpon","en":"Cho‘lpon"},{"uz":"Alisher Navoiy","ru":"Alisher Navoiy","en":"Alisher Navoiy"},{"uz":"Abdulla Qodiriy","ru":"Abdulla Qodiriy","en":"Abdulla Qodiriy"},{"uz":"G‘afur G‘ulom","ru":"G‘afur G‘ulom","en":"G‘afur G‘ulom"}]'::jsonb, 3, '{"uz":"“Shum bola” qissasini G‘afur G‘ulom yozgan; unda sho‘x bir bolaning sarguzashtlari hikoya qilinadi.","ru":"Повесть «Shum bola» написал Гафур Гулям; в ней рассказывается о приключениях озорного мальчика.","en":"G‘afur G‘ulom wrote “Shum bola”, a story about the adventures of a mischievous boy."}'::jsonb, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
('06661099-5fb1-5d72-8d83-3c643b948f79', 'native-16', 'NATIVE', 1, 1, 4, '{"uz":"Harflar","ru":"Буквы","en":"Letters"}'::jsonb, '{"uz":"Qaysi harf unli tovushni bildiradi?","ru":"Какая буква узбекского алфавита обозначает гласный звук?","en":"Which letter of the Uzbek alphabet is a vowel?"}'::jsonb, '[{"uz":"b","ru":"b","en":"b"},{"uz":"d","ru":"d","en":"d"},{"uz":"a","ru":"a","en":"a"},{"uz":"k","ru":"k","en":"k"}]'::jsonb, 2, '{"uz":"O‘zbek tilida oltita unli bor: a, o, i, u, e, o‘.","ru":"В узбекском языке шесть гласных: a, o, i, u, e, o‘.","en":"Uzbek has six vowels: a, o, i, u, e, o‘."}'::jsonb, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
('f1ff0849-5762-5660-81b4-be9296989347', 'native-17', 'NATIVE', 1, 1, 4, '{"uz":"Antonimlar","ru":"Антонимы","en":"Antonyms"}'::jsonb, '{"uz":"“Katta” so‘zining teskarisini toping.","ru":"Найдите слово, противоположное узбекскому слову «katta».","en":"Find the opposite of the Uzbek word “katta”."}'::jsonb, '[{"uz":"kichik","ru":"kichik","en":"kichik"},{"uz":"baland","ru":"baland","en":"baland"},{"uz":"uzun","ru":"uzun","en":"uzun"},{"uz":"keng","ru":"keng","en":"keng"}]'::jsonb, 0, '{"uz":"“Katta” va “kichik” — qarama-qarshi ma’noli so‘zlar.","ru":"Katta («большой») и kichik («маленький») — противоположные по значению слова.","en":"Katta (big) and kichik (small) have opposite meanings."}'::jsonb, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
('637837fa-aecf-5e36-9f87-cd7f30b0a0cc', 'native-18', 'NATIVE', 1, 1, 4, '{"uz":"Ko‘plik qo‘shimchasi","ru":"Множественное число","en":"Plural forms"}'::jsonb, '{"uz":"“Olma” so‘zining ko‘plik shaklini toping.","ru":"Найдите форму множественного числа узбекского слова «olma».","en":"Find the plural form of the Uzbek word “olma”."}'::jsonb, '[{"uz":"olmaning","ru":"olmaning","en":"olmaning"},{"uz":"olmalar","ru":"olmalar","en":"olmalar"},{"uz":"olmada","ru":"olmada","en":"olmada"},{"uz":"olmaga","ru":"olmaga","en":"olmaga"}]'::jsonb, 1, '{"uz":"Ko‘plik -lar qo‘shimchasi bilan yasaladi: olma — olmalar.","ru":"Множественное число образуется суффиксом -lar: olma («яблоко») — olmalar («яблоки»).","en":"The plural is made with the suffix -lar: olma (apple) — olmalar (apples)."}'::jsonb, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
('28b35e01-bc81-592d-8f95-bd5a8580dfa3', 'native-19', 'NATIVE', 1, 1, 4, '{"uz":"Ranglar","ru":"Цвета","en":"Colours"}'::jsonb, '{"uz":"Qor qanday rangda bo‘ladi?","ru":"Какого цвета снег? Выберите узбекское слово.","en":"What colour is snow? Choose the Uzbek word."}'::jsonb, '[{"uz":"qora","ru":"qora","en":"qora"},{"uz":"qizil","ru":"qizil","en":"qizil"},{"uz":"sariq","ru":"sariq","en":"sariq"},{"uz":"oq","ru":"oq","en":"oq"}]'::jsonb, 3, '{"uz":"Qor oppoq bo‘ladi, shuning uchun to‘g‘ri javob — “oq”.","ru":"Снег белый, а «белый» по-узбекски — oq.","en":"Snow is white, and white in Uzbek is oq."}'::jsonb, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
('dc72f472-c63f-5f65-89bb-c81d161c8a60', 'native-20', 'NATIVE', 1, 1, 4, '{"uz":"Hayvonlar","ru":"Животные","en":"Animals"}'::jsonb, '{"uz":"Qaysi hayvon “miyov” deydi?","ru":"Какое животное говорит «мяу»? Выберите узбекское слово.","en":"Which animal says “meow”? Choose the Uzbek word."}'::jsonb, '[{"uz":"mushuk","ru":"mushuk","en":"mushuk"},{"uz":"it","ru":"it","en":"it"},{"uz":"sigir","ru":"sigir","en":"sigir"},{"uz":"qo‘y","ru":"qo‘y","en":"qo‘y"}]'::jsonb, 0, '{"uz":"Mushuk “miyov-miyov” deb ovoz chiqaradi.","ru":"«Мяу» говорит кошка, а кошка по-узбекски — mushuk.","en":"A cat says meow, and cat in Uzbek is mushuk."}'::jsonb, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
('3d5d6b98-56b0-5054-923c-b2dda905f379', 'native-21', 'NATIVE', 2, 1, 4, '{"uz":"Gap tuzish","ru":"Предложение","en":"Sentences"}'::jsonb, '{"uz":"Gapni to‘ldiring: “Men maktabga ___.”","ru":"Дополните узбекское предложение: «Men maktabga ___.»","en":"Complete the Uzbek sentence: “Men maktabga ___.”"}'::jsonb, '[{"uz":"borasan","ru":"borasan","en":"borasan"},{"uz":"boradi","ru":"boradi","en":"boradi"},{"uz":"boraman","ru":"boraman","en":"boraman"},{"uz":"boramiz","ru":"boramiz","en":"boramiz"}]'::jsonb, 2, '{"uz":"“Men” olmoshi bilan fe’l -man qo‘shimchasini oladi: men boraman.","ru":"С местоимением men («я») глагол получает окончание -man: men boraman («я иду»).","en":"With men (I), the verb takes the ending -man: men boraman (I go)."}'::jsonb, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
('b5068c2e-3d5d-5456-9579-6161880b160a', 'physics-01', 'PHYSICS', 1, 5, 9, '{"uz":"Kuch","ru":"Сила","en":"Force"}'::jsonb, '{"uz":"Xalqaro birliklar tizimida (SI) kuch qanday birlikda o‘lchanadi?","ru":"В каких единицах измеряется сила в системе СИ?","en":"In SI units, what is force measured in?"}'::jsonb, '[{"uz":"Joul","ru":"Джоуль","en":"Joule"},{"uz":"Vatt","ru":"Ватт","en":"Watt"},{"uz":"Nyuton","ru":"Ньютон","en":"Newton"},{"uz":"Paskal","ru":"Паскаль","en":"Pascal"}]'::jsonb, 2, '{"uz":"Kuch nyutonlarda (N) o‘lchanadi. Joul — ish va energiya, vatt — quvvat, paskal esa bosim birligi.","ru":"Сила измеряется в ньютонах (Н). Джоуль — единица работы и энергии, ватт — мощности, паскаль — давления.","en":"Force is measured in newtons (N). The joule is for work and energy, the watt for power and the pascal for pressure."}'::jsonb, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
('02e2fe75-b3c7-5210-b186-3b71a9ec4017', 'physics-02', 'PHYSICS', 1, 5, 9, '{"uz":"Tezlik","ru":"Скорость","en":"Speed"}'::jsonb, '{"uz":"Avtomobil 2 soatda 120 km yo‘l bosdi. Uning o‘rtacha tezligi qancha?","ru":"Автомобиль проехал 120 км за 2 часа. Какова его средняя скорость?","en":"A car travels 120 km in 2 hours. What is its average speed?"}'::jsonb, '[{"uz":"240 km/soat","ru":"240 км/ч","en":"240 km/h"},{"uz":"60 km/soat","ru":"60 км/ч","en":"60 km/h"},{"uz":"30 km/soat","ru":"30 км/ч","en":"30 km/h"},{"uz":"122 km/soat","ru":"122 км/ч","en":"122 km/h"}]'::jsonb, 1, '{"uz":"Tezlik yo‘lni vaqtga bo‘lish bilan topiladi: v = s / t = 120 km : 2 soat = 60 km/soat.","ru":"Скорость равна пути, делённому на время: v = s / t = 120 км : 2 ч = 60 км/ч.","en":"Speed is distance divided by time: v = s / t = 120 km ÷ 2 h = 60 km/h."}'::jsonb, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
('d2380816-b982-5d6b-82ce-1dd07dd02a62', 'physics-03', 'PHYSICS', 1, 5, 9, '{"uz":"Yorug‘lik manbalari","ru":"Источники света","en":"Light sources"}'::jsonb, '{"uz":"Quyidagilardan qaysi biri tabiiy yorug‘lik manbayi?","ru":"Что из перечисленного является естественным источником света?","en":"Which of these is a natural source of light?"}'::jsonb, '[{"uz":"Oy","ru":"Луна","en":"The Moon"},{"uz":"Ko‘zgu","ru":"Зеркало","en":"A mirror"},{"uz":"Elektr lampa","ru":"Электрическая лампа","en":"An electric lamp"},{"uz":"Quyosh","ru":"Солнце","en":"The Sun"}]'::jsonb, 3, '{"uz":"Quyosh yorug‘likni o‘zi chiqaradi va tabiatda mavjud. Oy va ko‘zgu faqat yorug‘likni qaytaradi, lampa esa sun’iy manba.","ru":"Солнце само излучает свет и создано природой. Луна и зеркало лишь отражают свет, а лампа — искусственный источник.","en":"The Sun gives off its own light and is part of nature. The Moon and a mirror only reflect light, and a lamp is an artificial source."}'::jsonb, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
('29da4d18-e423-59c5-9eb8-de95639d3850', 'physics-04', 'PHYSICS', 1, 5, 9, '{"uz":"O‘lchov asboblari","ru":"Измерительные приборы","en":"Measuring instruments"}'::jsonb, '{"uz":"Harorat qaysi asbob bilan o‘lchanadi?","ru":"Каким прибором измеряют температуру?","en":"Which instrument measures temperature?"}'::jsonb, '[{"uz":"Barometr","ru":"Барометр","en":"Barometer"},{"uz":"Termometr","ru":"Термометр","en":"Thermometer"},{"uz":"Dinamometr","ru":"Динамометр","en":"Dynamometer"},{"uz":"Ampermetr","ru":"Амперметр","en":"Ammeter"}]'::jsonb, 1, '{"uz":"Termometr haroratni o‘lchaydi. Barometr atmosfera bosimini, dinamometr kuchni, ampermetr esa tok kuchini o‘lchaydi.","ru":"Термометр измеряет температуру. Барометр — атмосферное давление, динамометр — силу, амперметр — силу тока.","en":"A thermometer measures temperature. A barometer measures air pressure, a dynamometer force, and an ammeter electric current."}'::jsonb, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
('d1bd30db-7771-55c7-a633-c0d5af8e2ce1', 'physics-05', 'PHYSICS', 1, 5, 9, '{"uz":"Elektr o‘tkazgichlar","ru":"Проводники тока","en":"Conductors"}'::jsonb, '{"uz":"Quyidagi materiallardan qaysi biri elektr tokini yaxshi o‘tkazadi?","ru":"Какой из этих материалов хорошо проводит электрический ток?","en":"Which of these materials conducts electric current well?"}'::jsonb, '[{"uz":"Rezina","ru":"Резина","en":"Rubber"},{"uz":"Shisha","ru":"Стекло","en":"Glass"},{"uz":"Mis","ru":"Медь","en":"Copper"},{"uz":"Plastmassa","ru":"Пластмасса","en":"Plastic"}]'::jsonb, 2, '{"uz":"Mis — metall, unda erkin elektronlar ko‘p, shuning uchun simlar misdan yasaladi. Rezina, shisha va plastmassa — izolyatorlar.","ru":"Медь — металл с большим количеством свободных электронов, поэтому из неё делают провода. Резина, стекло и пластмасса — изоляторы.","en":"Copper is a metal with many free electrons, which is why wires are made of it. Rubber, glass and plastic are insulators."}'::jsonb, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
('171f72f0-ce2a-5697-a962-7aa05d6a73de', 'physics-06', 'PHYSICS', 2, 5, 9, '{"uz":"Zichlik","ru":"Плотность","en":"Density"}'::jsonb, '{"uz":"Jismning massasi 540 g, hajmi 200 sm³. Uning zichligi qancha?","ru":"Масса тела 540 г, объём 200 см³. Какова его плотность?","en":"An object has a mass of 540 g and a volume of 200 cm³. What is its density?"}'::jsonb, '[{"uz":"2,7 g/sm³","ru":"2,7 г/см³","en":"2.7 g/cm³"},{"uz":"0,37 g/sm³","ru":"0,37 г/см³","en":"0.37 g/cm³"},{"uz":"27 g/sm³","ru":"27 г/см³","en":"27 g/cm³"},{"uz":"340 g/sm³","ru":"340 г/см³","en":"340 g/cm³"}]'::jsonb, 0, '{"uz":"Zichlik massani hajmga bo‘lish bilan topiladi: ρ = m / V = 540 : 200 = 2,7 g/sm³. Bu alyuminiyning zichligi.","ru":"Плотность равна массе, делённой на объём: ρ = m / V = 540 : 200 = 2,7 г/см³. Это плотность алюминия.","en":"Density is mass divided by volume: ρ = m / V = 540 ÷ 200 = 2.7 g/cm³. That is the density of aluminium."}'::jsonb, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
('59d0d86c-6660-5601-abd2-de6cde62164d', 'physics-07', 'PHYSICS', 2, 5, 9, '{"uz":"Og‘irlik kuchi","ru":"Сила тяжести","en":"Gravity"}'::jsonb, '{"uz":"Massasi 5 kg bo‘lgan jismga qanday og‘irlik kuchi ta’sir qiladi? (g = 10 N/kg)","ru":"Какая сила тяжести действует на тело массой 5 кг? (g = 10 Н/кг)","en":"What force of gravity acts on an object with a mass of 5 kg? (g = 10 N/kg)"}'::jsonb, '[{"uz":"5 N","ru":"5 Н","en":"5 N"},{"uz":"0,5 N","ru":"0,5 Н","en":"0.5 N"},{"uz":"50 N","ru":"50 Н","en":"50 N"},{"uz":"15 N","ru":"15 Н","en":"15 N"}]'::jsonb, 2, '{"uz":"Og‘irlik kuchi F = m · g formula bilan topiladi: 5 kg · 10 N/kg = 50 N.","ru":"Сила тяжести вычисляется по формуле F = m · g: 5 кг · 10 Н/кг = 50 Н.","en":"The force of gravity is F = m × g: 5 kg × 10 N/kg = 50 N."}'::jsonb, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
('84a4812b-d6ec-5730-8240-d0636274fc60', 'physics-08', 'PHYSICS', 2, 5, 9, '{"uz":"Bosim","ru":"Давление","en":"Pressure"}'::jsonb, '{"uz":"600 N kuch 0,2 m² yuzaga tik ta’sir qilmoqda. Bosim qancha?","ru":"Сила 600 Н действует перпендикулярно на площадь 0,2 м². Каково давление?","en":"A force of 600 N acts at right angles on an area of 0.2 m². What is the pressure?"}'::jsonb, '[{"uz":"120 Pa","ru":"120 Па","en":"120 Pa"},{"uz":"30 Pa","ru":"30 Па","en":"30 Pa"},{"uz":"300 Pa","ru":"300 Па","en":"300 Pa"},{"uz":"3000 Pa","ru":"3000 Па","en":"3000 Pa"}]'::jsonb, 3, '{"uz":"Bosim kuchni yuzaga bo‘lish bilan topiladi: p = F / S = 600 : 0,2 = 3000 Pa.","ru":"Давление равно силе, делённой на площадь: p = F / S = 600 : 0,2 = 3000 Па.","en":"Pressure is force divided by area: p = F / S = 600 ÷ 0.2 = 3000 Pa."}'::jsonb, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
('676d889b-7ef2-5037-ab6b-efbf288812ac', 'physics-09', 'PHYSICS', 2, 5, 9, '{"uz":"Om qonuni","ru":"Закон Ома","en":"Ohm’s law"}'::jsonb, '{"uz":"Qarshiligi 4 Om bo‘lgan o‘tkazgichga 12 V kuchlanish berildi. Tok kuchi qancha?","ru":"На проводник сопротивлением 4 Ом подано напряжение 12 В. Какова сила тока?","en":"A voltage of 12 V is applied to a conductor with a resistance of 4 Ω. What is the current?"}'::jsonb, '[{"uz":"48 A","ru":"48 А","en":"48 A"},{"uz":"3 A","ru":"3 А","en":"3 A"},{"uz":"16 A","ru":"16 А","en":"16 A"},{"uz":"8 A","ru":"8 А","en":"8 A"}]'::jsonb, 1, '{"uz":"Om qonuni bo‘yicha tok kuchi I = U / R = 12 V : 4 Om = 3 A.","ru":"По закону Ома сила тока I = U / R = 12 В : 4 Ом = 3 А.","en":"By Ohm’s law, the current is I = V / R = 12 V ÷ 4 Ω = 3 A."}'::jsonb, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
('38c8d7d9-867f-56a3-97c8-6fa12aa69b9b', 'physics-10', 'PHYSICS', 2, 5, 9, '{"uz":"Mexanik ish","ru":"Механическая работа","en":"Work"}'::jsonb, '{"uz":"Quti 20 N kuch ta’sirida kuch yo‘nalishi bo‘yicha 5 m ga siljidi. Qancha ish bajarildi?","ru":"Ящик под действием силы 20 Н переместили на 5 м в направлении силы. Какая работа совершена?","en":"A box is pushed 5 m by a force of 20 N in the direction of the force. How much work is done?"}'::jsonb, '[{"uz":"100 J","ru":"100 Дж","en":"100 J"},{"uz":"4 J","ru":"4 Дж","en":"4 J"},{"uz":"25 J","ru":"25 Дж","en":"25 J"},{"uz":"15 J","ru":"15 Дж","en":"15 J"}]'::jsonb, 0, '{"uz":"Mexanik ish kuch va yo‘l ko‘paytmasiga teng: A = F · s = 20 N · 5 m = 100 J.","ru":"Механическая работа равна произведению силы на путь: A = F · s = 20 Н · 5 м = 100 Дж.","en":"Work equals force times distance: W = F × s = 20 N × 5 m = 100 J."}'::jsonb, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
('57c63f2c-87fe-5ccc-8a31-16ac99cba026', 'physics-11', 'PHYSICS', 3, 5, 9, '{"uz":"Kinetik energiya","ru":"Кинетическая энергия","en":"Kinetic energy"}'::jsonb, '{"uz":"Massasi 2 kg bo‘lgan to‘p 3 m/s tezlik bilan harakatlanmoqda. Uning kinetik energiyasi qancha?","ru":"Мяч массой 2 кг движется со скоростью 3 м/с. Какова его кинетическая энергия?","en":"A 2 kg ball is moving at 3 m/s. What is its kinetic energy?"}'::jsonb, '[{"uz":"6 J","ru":"6 Дж","en":"6 J"},{"uz":"3 J","ru":"3 Дж","en":"3 J"},{"uz":"18 J","ru":"18 Дж","en":"18 J"},{"uz":"9 J","ru":"9 Дж","en":"9 J"}]'::jsonb, 3, '{"uz":"Kinetik energiya E = m · v² / 2 formula bilan topiladi: 2 · 3² / 2 = 2 · 9 / 2 = 9 J.","ru":"Кинетическая энергия E = m · v² / 2: 2 · 3² / 2 = 2 · 9 / 2 = 9 Дж.","en":"Kinetic energy is E = m × v² / 2: 2 × 3² / 2 = 2 × 9 / 2 = 9 J."}'::jsonb, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
('a65264da-6dbe-5ba3-b6ef-2bc2abfdcb5e', 'physics-12', 'PHYSICS', 3, 5, 9, '{"uz":"Suyuqlik bosimi","ru":"Давление жидкости","en":"Liquid pressure"}'::jsonb, '{"uz":"Suv 5 m chuqurlikda qanday bosim hosil qiladi? (ρ = 1000 kg/m³, g = 10 N/kg, atmosfera bosimi hisobga olinmaydi)","ru":"Какое давление создаёт вода на глубине 5 м? (ρ = 1000 кг/м³, g = 10 Н/кг, атмосферное давление не учитывать)","en":"What pressure does water create at a depth of 5 m? (ρ = 1000 kg/m³, g = 10 N/kg, ignore atmospheric pressure)"}'::jsonb, '[{"uz":"5 kPa","ru":"5 кПа","en":"5 kPa"},{"uz":"50 kPa","ru":"50 кПа","en":"50 kPa"},{"uz":"500 kPa","ru":"500 кПа","en":"500 kPa"},{"uz":"0,5 kPa","ru":"0,5 кПа","en":"0.5 kPa"}]'::jsonb, 1, '{"uz":"Suyuqlik bosimi p = ρ · g · h = 1000 · 10 · 5 = 50 000 Pa, ya’ni 50 kPa.","ru":"Давление жидкости p = ρ · g · h = 1000 · 10 · 5 = 50 000 Па, то есть 50 кПа.","en":"Liquid pressure is p = ρ × g × h = 1000 × 10 × 5 = 50,000 Pa, which is 50 kPa."}'::jsonb, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
('3dd7ac68-6d26-5c70-9869-c7b4f33f4e21', 'physics-13', 'PHYSICS', 3, 5, 9, '{"uz":"Parallel ulash","ru":"Параллельное соединение","en":"Parallel circuits"}'::jsonb, '{"uz":"Qarshiliklari 6 Om va 3 Om bo‘lgan ikkita rezistor parallel ulangan. Umumiy qarshilik qancha?","ru":"Два резистора сопротивлением 6 Ом и 3 Ом соединены параллельно. Каково общее сопротивление?","en":"Two resistors of 6 Ω and 3 Ω are connected in parallel. What is the total resistance?"}'::jsonb, '[{"uz":"2 Om","ru":"2 Ом","en":"2 Ω"},{"uz":"9 Om","ru":"9 Ом","en":"9 Ω"},{"uz":"4,5 Om","ru":"4,5 Ом","en":"4.5 Ω"},{"uz":"18 Om","ru":"18 Ом","en":"18 Ω"}]'::jsonb, 0, '{"uz":"Parallel ulashda R = R₁ · R₂ / (R₁ + R₂) = 6 · 3 / 9 = 2 Om. Umumiy qarshilik eng kichik rezistornikidan ham kichik bo‘ladi.","ru":"При параллельном соединении R = R₁ · R₂ / (R₁ + R₂) = 6 · 3 / 9 = 2 Ом. Общее сопротивление меньше самого маленького из них.","en":"In parallel, R = R₁ × R₂ / (R₁ + R₂) = 6 × 3 / 9 = 2 Ω. The total is always smaller than the smallest resistor."}'::jsonb, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
('688b6397-8041-5b48-a97e-aa8182dc0a14', 'physics-14', 'PHYSICS', 3, 5, 9, '{"uz":"Quvvat","ru":"Мощность","en":"Power"}'::jsonb, '{"uz":"Kran 500 kg yukni 20 s da 12 m balandlikka tekis ko‘tardi. Kranning quvvati qancha? (g = 10 N/kg)","ru":"Кран равномерно поднял груз массой 500 кг на высоту 12 м за 20 с. Какова мощность крана? (g = 10 Н/кг)","en":"A crane steadily lifts a 500 kg load to a height of 12 m in 20 s. What is the crane’s power? (g = 10 N/kg)"}'::jsonb, '[{"uz":"300 Vt","ru":"300 Вт","en":"300 W"},{"uz":"30 kVt","ru":"30 кВт","en":"30 kW"},{"uz":"3 kVt","ru":"3 кВт","en":"3 kW"},{"uz":"1,2 kVt","ru":"1,2 кВт","en":"1.2 kW"}]'::jsonb, 2, '{"uz":"Ish A = m · g · h = 500 · 10 · 12 = 60 000 J. Quvvat N = A / t = 60 000 : 20 = 3000 Vt = 3 kVt.","ru":"Работа A = m · g · h = 500 · 10 · 12 = 60 000 Дж. Мощность N = A / t = 60 000 : 20 = 3000 Вт = 3 кВт.","en":"Work W = m × g × h = 500 × 10 × 12 = 60,000 J. Power P = W / t = 60,000 ÷ 20 = 3000 W = 3 kW."}'::jsonb, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
('0bf5426e-5010-5d2e-b05b-b0927a8a6c50', 'physics-15', 'PHYSICS', 3, 5, 9, '{"uz":"Yorug‘likning qaytishi","ru":"Отражение света","en":"Reflection of light"}'::jsonb, '{"uz":"Tushayotgan nur bilan ko‘zgu sirti orasidagi burchak 30°. Qaytish burchagi nechaga teng?","ru":"Угол между падающим лучом и поверхностью зеркала равен 30°. Чему равен угол отражения?","en":"The angle between an incoming ray and the surface of a mirror is 30°. What is the angle of reflection?"}'::jsonb, '[{"uz":"60°","ru":"60°","en":"60°"},{"uz":"30°","ru":"30°","en":"30°"},{"uz":"120°","ru":"120°","en":"120°"},{"uz":"90°","ru":"90°","en":"90°"}]'::jsonb, 0, '{"uz":"Burchaklar ko‘zguga o‘tkazilgan perpendikulyardan o‘lchanadi: tushish burchagi 90° − 30° = 60°. Qaytish burchagi unga teng, ya’ni 60°.","ru":"Углы отсчитывают от перпендикуляра к зеркалу: угол падения 90° − 30° = 60°. Угол отражения равен углу падения — 60°.","en":"Angles are measured from the line perpendicular to the mirror: the angle of incidence is 90° − 30° = 60°. The angle of reflection equals it: 60°."}'::jsonb, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
('de040473-2b8d-5011-8c79-2e2680a862f5', 'russian-01', 'RUSSIAN', 1, 5, 9, '{"uz":"Otlarning jinsi","ru":"Род существительных","en":"Noun gender"}'::jsonb, '{"uz":"Qaysi ruscha ot ayol jinsiga (женский род) kiradi?","ru":"Какое существительное женского рода?","en":"Which Russian noun is feminine (женский род)?"}'::jsonb, '[{"uz":"стол","ru":"стол","en":"стол"},{"uz":"окно","ru":"окно","en":"окно"},{"uz":"книга","ru":"книга","en":"книга"},{"uz":"дом","ru":"дом","en":"дом"}]'::jsonb, 2, '{"uz":"“Книга” -а bilan tugaydi va uni “она” olmoshi bilan almashtirish mumkin, demak u ayol jinsida.","ru":"Слово «книга» оканчивается на -а и заменяется местоимением «она», значит, это женский род.","en":"Книга ends in -а and can be replaced by она (she), so it is feminine."}'::jsonb, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
('4bfa7628-5783-5659-b529-b0759810faf7', 'russian-02', 'RUSSIAN', 1, 5, 9, '{"uz":"Antonimlar","ru":"Антонимы","en":"Antonyms"}'::jsonb, '{"uz":"“Высокий” so‘zining antonimini toping.","ru":"Подберите антоним к слову «высокий».","en":"Find the antonym of the Russian word “высокий”."}'::jsonb, '[{"uz":"большой","ru":"большой","en":"большой"},{"uz":"низкий","ru":"низкий","en":"низкий"},{"uz":"длинный","ru":"длинный","en":"длинный"},{"uz":"широкий","ru":"широкий","en":"широкий"}]'::jsonb, 1, '{"uz":"“Высокий” — baland, “низкий” — past degani; ular qarama-qarshi ma’noli so‘zlar.","ru":"Высокий и низкий — слова с противоположным значением.","en":"Высокий means tall or high and низкий means low, so they are opposites."}'::jsonb, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
('cb11f3bd-363f-50cc-bbdd-3bcc1945a78d', 'russian-03', 'RUSSIAN', 1, 5, 9, '{"uz":"So‘z turkumlari","ru":"Части речи","en":"Parts of speech"}'::jsonb, '{"uz":"Qaysi ruscha so‘z fe’l (глагол)?","ru":"Какое слово является глаголом?","en":"Which Russian word is a verb (глагол)?"}'::jsonb, '[{"uz":"бег","ru":"бег","en":"бег"},{"uz":"бегун","ru":"бегун","en":"бегун"},{"uz":"быстрый","ru":"быстрый","en":"быстрый"},{"uz":"бегать","ru":"бегать","en":"бегать"}]'::jsonb, 3, '{"uz":"Fe’l harakatni bildiradi va “что делать?” so‘rog‘iga javob beradi: бегать.","ru":"Глагол обозначает действие и отвечает на вопрос «что делать?»: бегать.","en":"A verb shows an action and answers “что делать?” (what to do?): бегать means to run."}'::jsonb, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
('420bf6b4-3797-55e9-b48c-39a2a8be8760', 'russian-04', 'RUSSIAN', 1, 5, 9, '{"uz":"Ko‘plik shakli","ru":"Множественное число","en":"Plural nouns"}'::jsonb, '{"uz":"“Друг” so‘zining ko‘plik shaklini toping.","ru":"Выберите форму множественного числа слова «друг».","en":"Choose the plural form of the Russian word “друг”."}'::jsonb, '[{"uz":"друзья","ru":"друзья","en":"друзья"},{"uz":"друга","ru":"друга","en":"друга"},{"uz":"другы","ru":"другы","en":"другы"},{"uz":"друзи","ru":"друзи","en":"друзи"}]'::jsonb, 0, '{"uz":"“Друг” so‘zining ko‘pligi qoidadan tashqari yasaladi: друг — друзья.","ru":"Слово «друг» образует множественное число особым способом: друг — друзья.","en":"Друг has an irregular plural: друг — друзья."}'::jsonb, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
('9962c380-2176-5571-9291-f281f493e269', 'russian-05', 'RUSSIAN', 1, 5, 9, '{"uz":"Sinonimlar","ru":"Синонимы","en":"Synonyms"}'::jsonb, '{"uz":"“Смелый” so‘zining sinonimini toping.","ru":"Подберите синоним к слову «смелый».","en":"Find the synonym of the Russian word “смелый”."}'::jsonb, '[{"uz":"трусливый","ru":"трусливый","en":"трусливый"},{"uz":"весёлый","ru":"весёлый","en":"весёлый"},{"uz":"храбрый","ru":"храбрый","en":"храбрый"},{"uz":"сильный","ru":"сильный","en":"сильный"}]'::jsonb, 2, '{"uz":"“Смелый” va “храбрый” — ikkalasi ham jasur degani.","ru":"Смелый и храбрый близки по значению: оба значат «не боящийся опасности».","en":"Смелый and храбрый both mean brave."}'::jsonb, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
('374aeb06-1bf1-5aa2-8d61-b277ec892c85', 'russian-06', 'RUSSIAN', 2, 5, 9, '{"uz":"Kelishiklar","ru":"Падежи","en":"Cases"}'::jsonb, '{"uz":"Rus tilida родительный падеж qaysi so‘roqlarga javob beradi?","ru":"На какие вопросы отвечает родительный падеж?","en":"Which questions does the Russian genitive case (родительный падеж) answer?"}'::jsonb, '[{"uz":"кто? что?","ru":"кто? что?","en":"кто? что?"},{"uz":"кого? чего?","ru":"кого? чего?","en":"кого? чего?"},{"uz":"кому? чему?","ru":"кому? чему?","en":"кому? чему?"},{"uz":"кем? чем?","ru":"кем? чем?","en":"кем? чем?"}]'::jsonb, 1, '{"uz":"Родительный падеж “кого? чего?” so‘roqlariga javob beradi: нет (чего?) книги.","ru":"Родительный падеж отвечает на вопросы «кого? чего?»: нет (чего?) книги.","en":"The genitive case answers “кого? чего?” (of whom? of what?), as in нет книги."}'::jsonb, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
('96e82130-297e-5ca6-9c12-7717fc0d50f2', 'russian-07', 'RUSSIAN', 2, 5, 9, '{"uz":"Fe’l tuslanishi","ru":"Спряжение глаголов","en":"Verb conjugation"}'::jsonb, '{"uz":"Qaysi ruscha fe’l II tuslanishga (II спряжение) kiradi?","ru":"Какой глагол относится ко II спряжению?","en":"Which Russian verb belongs to the 2nd conjugation (II спряжение)?"}'::jsonb, '[{"uz":"читать","ru":"читать","en":"читать"},{"uz":"писать","ru":"писать","en":"писать"},{"uz":"петь","ru":"петь","en":"петь"},{"uz":"говорить","ru":"говорить","en":"говорить"}]'::jsonb, 3, '{"uz":"-ить bilan tugaydigan fe’llar (istisnolardan tashqari) II tuslanishga kiradi: говорить — говорит, говорят.","ru":"Глаголы на -ить (кроме исключений) относятся ко II спряжению: говорить — говорит, говорят.","en":"Verbs ending in -ить (apart from a few exceptions) are 2nd conjugation: говорить — говорит, говорят."}'::jsonb, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
('7fe996fc-0042-596f-bdbf-d13792b4e9ad', 'russian-08', 'RUSSIAN', 2, 5, 9, '{"uz":"Imlo","ru":"Орфография","en":"Spelling"}'::jsonb, '{"uz":"Tushib qolgan harfni toping: г_ра (tog‘).","ru":"Вставьте пропущенную букву: г_ра.","en":"Fill in the missing letter in the Russian word: г_ра (mountain)."}'::jsonb, '[{"uz":"о","ru":"о","en":"о"},{"uz":"а","ru":"а","en":"а"},{"uz":"е","ru":"е","en":"е"},{"uz":"и","ru":"и","en":"и"}]'::jsonb, 0, '{"uz":"Urg‘usiz unlini urg‘uli shakl bilan tekshiramiz: гОры — demak, гора.","ru":"Безударную гласную проверяем ударением: гОры — значит, гора.","en":"Check the unstressed vowel with a stressed form: гОры (mountains), so it is гора."}'::jsonb, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
('d6e19ca5-5b7b-50a7-978a-e24cc56125f7', 'russian-09', 'RUSSIAN', 2, 5, 9, '{"uz":"Kelishiklar","ru":"Падежи","en":"Cases"}'::jsonb, '{"uz":"Gapni to‘ldiring: «Я живу в ___.»","ru":"Дополните предложение: «Я живу в ___.»","en":"Complete the Russian sentence: «Я живу в ___.»"}'::jsonb, '[{"uz":"Ташкент","ru":"Ташкент","en":"Ташкент"},{"uz":"Ташкента","ru":"Ташкента","en":"Ташкента"},{"uz":"Ташкенте","ru":"Ташкенте","en":"Ташкенте"},{"uz":"Ташкентом","ru":"Ташкентом","en":"Ташкентом"}]'::jsonb, 2, '{"uz":"“Где?” (qayerda?) so‘rog‘ida “в” predlogidan keyin предложный падеж ishlatiladi: в Ташкенте.","ru":"На вопрос «где?» после предлога «в» используется предложный падеж: в Ташкенте.","en":"To say where (где?), в is followed by the prepositional case: в Ташкенте."}'::jsonb, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
('3b5524ea-c1d9-5bde-a40f-6aac391c900f', 'russian-10', 'RUSSIAN', 2, 5, 9, '{"uz":"O‘zakdosh so‘zlar","ru":"Однокоренные слова","en":"Word roots"}'::jsonb, '{"uz":"Qaysi so‘z “лес” (o‘rmon) so‘zi bilan o‘zakdosh?","ru":"Какое слово является однокоренным к слову «лес»?","en":"Which Russian word has the same root as “лес” (forest)?"}'::jsonb, '[{"uz":"лестница","ru":"лестница","en":"лестница"},{"uz":"лесник","ru":"лесник","en":"лесник"},{"uz":"лезть","ru":"лезть","en":"лезть"},{"uz":"лесть","ru":"лесть","en":"лесть"}]'::jsonb, 1, '{"uz":"“Лесник” — o‘rmonni qo‘riqlovchi kishi, o‘zagi “лес”; “лестница” (narvon) esa unga faqat tashqi tomondan o‘xshaydi.","ru":"Лесник — тот, кто охраняет лес, корень у слов общий; «лестница» лишь похожа внешне.","en":"Лесник (forester) shares the root of лес; лестница (staircase) only looks similar."}'::jsonb, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
('1dbfaad2-5ce1-5831-a252-46e911b356ed', 'russian-11', 'RUSSIAN', 3, 5, 9, '{"uz":"Urg‘u","ru":"Ударение","en":"Word stress"}'::jsonb, '{"uz":"Qaysi so‘zda urg‘u to‘g‘ri qo‘yilgan? (Urg‘uli unli bosh harf bilan berilgan.)","ru":"В каком слове ударение поставлено верно? (Ударная гласная выделена заглавной буквой.)","en":"In which Russian word is the stress marked correctly? (The stressed vowel is a capital letter.)"}'::jsonb, '[{"uz":"звОнит","ru":"звОнит","en":"звОнит"},{"uz":"тортЫ","ru":"тортЫ","en":"тортЫ"},{"uz":"щАвель","ru":"щАвель","en":"щАвель"},{"uz":"красИвее","ru":"красИвее","en":"красИвее"}]'::jsonb, 3, '{"uz":"To‘g‘ri talaffuz: красИвее; qolganlari звонИт, тОрты, щавЕль deb aytiladi.","ru":"Верно: красИвее; в остальных словах ударение такое: звонИт, тОрты, щавЕль.","en":"The correct one is красИвее; the others are stressed звонИт, тОрты, щавЕль."}'::jsonb, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
('23aa53cc-cd3f-5c89-b079-db086edd482e', 'russian-12', 'RUSSIAN', 3, 5, 9, '{"uz":"Imlo","ru":"Орфография","en":"Spelling"}'::jsonb, '{"uz":"Qaysi ruscha so‘z to‘g‘ri yozilgan?","ru":"Какое слово написано правильно?","en":"Which Russian word is spelled correctly?"}'::jsonb, '[{"uz":"мячь","ru":"мячь","en":"мячь"},{"uz":"дочь","ru":"дочь","en":"дочь"},{"uz":"врачь","ru":"врачь","en":"врачь"},{"uz":"ключь","ru":"ключь","en":"ключь"}]'::jsonb, 1, '{"uz":"Shipilovchi undoshlardan keyin ь faqat ayol jinsidagi otlarda yoziladi: дочь; мяч, врач, ключ — erkak jinsida.","ru":"После шипящих ь пишется только у существительных женского рода: дочь; мяч, врач, ключ — мужского рода.","en":"After ж, ш, ч, щ the letter ь is written only in feminine nouns: дочь; мяч, врач and ключ are masculine."}'::jsonb, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
('3bd155d9-faa8-5cd4-a60d-c473db2cbde8', 'russian-13', 'RUSSIAN', 3, 5, 9, '{"uz":"Kelishiklar","ru":"Падежи","en":"Cases"}'::jsonb, '{"uz":"«Я написал письмо другу» gapida “другу” so‘zi qaysi kelishikda turibdi?","ru":"В каком падеже стоит слово «другу» в предложении «Я написал письмо другу»?","en":"Which case is “другу” in the Russian sentence «Я написал письмо другу»?"}'::jsonb, '[{"uz":"родительный","ru":"родительный","en":"родительный"},{"uz":"винительный","ru":"винительный","en":"винительный"},{"uz":"дательный","ru":"дательный","en":"дательный"},{"uz":"творительный","ru":"творительный","en":"творительный"}]'::jsonb, 2, '{"uz":"“Другу” so‘zi “кому?” so‘rog‘iga javob beradi, bu дательный падеж.","ru":"Слово «другу» отвечает на вопрос «кому?» — это дательный падеж.","en":"Другу answers “кому?” (to whom?), which is the dative case (дательный)."}'::jsonb, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
('80024774-35ee-56d0-b92b-6d30ad960595', 'russian-14', 'RUSSIAN', 3, 5, 9, '{"uz":"So‘z turkumlari","ru":"Части речи","en":"Parts of speech"}'::jsonb, '{"uz":"Qaysi ruscha so‘z ravish (наречие)?","ru":"Какое слово является наречием?","en":"Which Russian word is an adverb (наречие)?"}'::jsonb, '[{"uz":"вчера","ru":"вчера","en":"вчера"},{"uz":"вчерашний","ru":"вчерашний","en":"вчерашний"},{"uz":"вечер","ru":"вечер","en":"вечер"},{"uz":"вечерний","ru":"вечерний","en":"вечерний"}]'::jsonb, 0, '{"uz":"Ravish harakat belgisini bildiradi va o‘zgarmaydi: вчера (когда?) — kecha.","ru":"Наречие обозначает признак действия, не изменяется и отвечает здесь на вопрос «когда?»: вчера.","en":"An adverb describes an action, never changes its form and here answers “когда?” (when?): вчера means yesterday."}'::jsonb, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
('4966997a-f23f-5043-bb68-29c40f72281d', 'russian-15', 'RUSSIAN', 3, 5, 9, '{"uz":"Iboralar","ru":"Фразеологизмы","en":"Idioms"}'::jsonb, '{"uz":"“Бить баклуши” iborasi nimani anglatadi?","ru":"Что означает фразеологизм «бить баклуши»?","en":"What does the Russian idiom “бить баклуши” mean?"}'::jsonb, '[{"uz":"много работать","ru":"много работать","en":"много работать"},{"uz":"громко спорить","ru":"громко спорить","en":"громко спорить"},{"uz":"быстро бегать","ru":"быстро бегать","en":"быстро бегать"},{"uz":"бездельничать","ru":"бездельничать","en":"бездельничать"}]'::jsonb, 3, '{"uz":"“Бить баклуши” — bekorchilik qilmoq, ya’ni hech ish qilmay vaqt o‘tkazish degani.","ru":"«Бить баклуши» значит бездельничать, проводить время без пользы.","en":"“Бить баклуши” means to idle about and do nothing useful."}'::jsonb, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
('877acedd-7d2a-51e1-9a92-6eef5a5c10f6', 'russian-16', 'RUSSIAN', 1, 1, 4, '{"uz":"Alifbo","ru":"Алфавит","en":"Alphabet"}'::jsonb, '{"uz":"Rus alifbosida “Б” harfidan keyin qaysi harf keladi?","ru":"Какая буква идёт после «Б» в алфавите?","en":"Which letter comes after “Б” in the Russian alphabet?"}'::jsonb, '[{"uz":"А","ru":"А","en":"А"},{"uz":"Г","ru":"Г","en":"Г"},{"uz":"В","ru":"В","en":"В"},{"uz":"Д","ru":"Д","en":"Д"}]'::jsonb, 2, '{"uz":"Rus alifbosi shunday boshlanadi: А, Б, В, Г, Д…","ru":"Алфавит начинается так: А, Б, В, Г, Д…","en":"The Russian alphabet starts like this: А, Б, В, Г, Д…"}'::jsonb, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
('0570b83f-3c30-5cc0-b94b-cc724fdbe030', 'russian-17', 'RUSSIAN', 1, 1, 4, '{"uz":"Unli harflar","ru":"Гласные буквы","en":"Vowels"}'::jsonb, '{"uz":"Qaysi ruscha harf unli tovushni bildiradi?","ru":"Какая буква обозначает гласный звук?","en":"Which Russian letter is a vowel?"}'::jsonb, '[{"uz":"м","ru":"м","en":"м"},{"uz":"т","ru":"т","en":"т"},{"uz":"р","ru":"р","en":"р"},{"uz":"о","ru":"о","en":"о"}]'::jsonb, 3, '{"uz":"“О” — unli harf, “м”, “т”, “р” esa undosh harflar.","ru":"О — гласная буква, а м, т, р — согласные.","en":"О is a vowel; м, т and р are consonants."}'::jsonb, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
('289d42f3-b4b8-5b95-bbf5-da6061c071e5', 'russian-18', 'RUSSIAN', 1, 1, 4, '{"uz":"Hayvonlar","ru":"Животные","en":"Animals"}'::jsonb, '{"uz":"Mushukning bolasi rus tilida qanday ataladi?","ru":"Как называется детёныш кошки?","en":"What is a baby cat called in Russian?"}'::jsonb, '[{"uz":"щенок","ru":"щенок","en":"щенок"},{"uz":"котёнок","ru":"котёнок","en":"котёнок"},{"uz":"телёнок","ru":"телёнок","en":"телёнок"},{"uz":"цыплёнок","ru":"цыплёнок","en":"цыплёнок"}]'::jsonb, 1, '{"uz":"Mushuk bolasi — котёнок; щенок — kuchukcha, телёнок — buzoq, цыплёнок — jo‘ja.","ru":"Детёныш кошки — котёнок; щенок — у собаки, телёнок — у коровы, цыплёнок — у курицы.","en":"A baby cat is котёнок; щенок is a puppy, телёнок is a calf and цыплёнок is a chick."}'::jsonb, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
('e3cb2c00-fc6d-53a0-90fa-eb8b9e8e8fd6', 'russian-19', 'RUSSIAN', 1, 1, 4, '{"uz":"Ranglar","ru":"Цвета","en":"Colours"}'::jsonb, '{"uz":"Pishgan limon qanday rangda? Ruscha so‘zni tanlang.","ru":"Какого цвета спелый лимон?","en":"What colour is a ripe lemon? Choose the Russian word."}'::jsonb, '[{"uz":"жёлтый","ru":"жёлтый","en":"жёлтый"},{"uz":"синий","ru":"синий","en":"синий"},{"uz":"чёрный","ru":"чёрный","en":"чёрный"},{"uz":"фиолетовый","ru":"фиолетовый","en":"фиолетовый"}]'::jsonb, 0, '{"uz":"Pishgan limon sariq bo‘ladi, rus tilida sariq — “жёлтый”.","ru":"Спелый лимон жёлтого цвета.","en":"A ripe lemon is yellow, and yellow in Russian is жёлтый."}'::jsonb, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
('c4eb0cf1-0967-541c-b822-2e1cb977652e', 'russian-20', 'RUSSIAN', 1, 1, 4, '{"uz":"Antonimlar","ru":"Антонимы","en":"Antonyms"}'::jsonb, '{"uz":"“День” so‘zining teskarisini toping.","ru":"Подберите слово, противоположное по значению слову «день».","en":"Find the opposite of the Russian word “день” (day)."}'::jsonb, '[{"uz":"ночь","ru":"ночь","en":"ночь"},{"uz":"утро","ru":"утро","en":"утро"},{"uz":"вечер","ru":"вечер","en":"вечер"},{"uz":"солнце","ru":"солнце","en":"солнце"}]'::jsonb, 0, '{"uz":"“День” — kun, “ночь” — tun; ular qarama-qarshi ma’noli so‘zlar.","ru":"День и ночь — слова с противоположным значением.","en":"День (day) and ночь (night) are opposites."}'::jsonb, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
('c4a22466-cb55-5d9b-9992-271d7161e6a7', 'russian-21', 'RUSSIAN', 2, 1, 4, '{"uz":"Ko‘plik shakli","ru":"Множественное число","en":"Plural nouns"}'::jsonb, '{"uz":"“Кот” so‘zining ko‘plik shaklini toping.","ru":"Выберите форму множественного числа слова «кот».","en":"Choose the plural form of the Russian word “кот”."}'::jsonb, '[{"uz":"кота","ru":"кота","en":"кота"},{"uz":"коты","ru":"коты","en":"коты"},{"uz":"коту","ru":"коту","en":"коту"},{"uz":"котом","ru":"котом","en":"котом"}]'::jsonb, 1, '{"uz":"Ko‘plikda “кот” so‘ziga -ы qo‘shimchasi qo‘shiladi: кот — коты.","ru":"Во множественном числе слово «кот» получает окончание -ы: коты.","en":"In the plural, кот takes the ending -ы: коты."}'::jsonb, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP)
